COLLDATA("sh132971","ar",[[3324,"٢١٠٢ - أبو عمر الصينى (٢)، روى عن أبى الدرداء، روى عنه عبد العزيز ابن رفيع.","",{"fn":"زاد في الميزان \"وقيل: أبو عمرو\" وكذا في التهذيب والتقريب أيضًا. ٢١٠٢ - كنى البخارى (ص ٥٥)، تاريخ ابن معين (٢/ ٧١٧)، الجرح (٤/ ٢/ ٤٠٧) وقال: قال أبو زرعة: لا نعرفه إلا برواية حديث واحد عن أبى الدرداء عن النبى -صلى الله عليه وآله وسلم- \"سبقنا الأغنياء بالدنيا والآخرة يصلون كما نصلى ويصومون كما نصوم\" الحديث - ولا يسمى، المقتنى في سرد الكنى (١٠٢/ أ)، تهذيب الكمال (٣/ ١٦٢٩)، التهذيب (١٢/ ١٧٦)، التقريب (٢/ ٤٥٤) وقال: يقال: اسمه نشيط، وهو وهم، ووهم أيضًا من قال فيه: الضبى، بالمعجمة والموحدة مقبول، من السادسة، وروايته عن أبى الدراء مرسلة./ س وقال العلائى في جامع التحصيل (ص ٣٨٨) روى عن أبى الدراء، وقيل: هو مرسل، بل هو عن أم الدراء، عن أبى الدراء رضي الله عنه. قلت: وسيأتى أبو عمر المنبهى، وقيل: اسمه نشيط. انظر الترجمة (٢١٠٦).\nالصينى: بكسر الصاد وسكون الياء المثناة من تحتها وفى آخرها نون - هذه النسبة إلى موضعين. أحدهما بلاد الصين، وهو الاقليم المشهور ="}],[3325,"٢١٠٣ - أبو عمر البيروتى (١)، عن أبى الدرداء، روى عنه عبد الرحمن بن يزيد بن جابر."],[3326,"٢١٠٤ - أبو عمر الجدلى، عن أبى هريرة، روى عنه داود بن أبى هند، وقيل: أنه شيخ من ربيعة."],[3327,"٢١٠٥ - أبو عمر البزار (٢)، عن عامر الشعبى، وإبراهيم بن يزيد النخعى، ومسلم البطين، روى عنه سفيان الثورى، قال أحمد بن حنبل: قال وكيع: أبو عمر البزار ثقة (٣).","",{"fn":"البيروتى: نسبة إلى بيروت، بالفتح ثم السكون، وضم الراء، وسكون الواو والتاء فوقها، نقطتان، مدينة مشهورة على بحر الشام، تعد من أعمال دمشق، بينها وبين صيدا ثلاثة فراسخ. انظر اللباب (١/ ١٩٦) مراصد الاطلاع (١/ ٢٤٠). ٢١٠٤ - الجرح (٤/ ٢/ ٤٠٨)، الميزان (٤/ ٥٥٥). وقال: لا يدرى من هو. اللسان (٧/ ٨٦). وقال: لا يدرى من هو. المقتنى في سرد الكنى (١٠٢/ أ). ٢١٠٥ - كنى البخارى (ص ٥٦)، الجرح (٤/ ٢/ ٤٠٧ - ٤٠٨)، اللسان (٧/ ٤٧٥) وقال: هو دينار بن عمر الاعمى.\nفي الأصل \"البزاز\" آخره زاى. والمثبت عن مصادر الترجمة \"البزار\" آخره راء مهملة. ونص الحافظ ابن حجر في التقريب (١/ ٢٣٧) في ترجمة دينار ابن عمر أبو عمر البزار بأن آخره راء مهملة. واللَّه أعلم.\nانظر العلل ومعرفة الرجال لأحمد (١/ ١٠٧ و٢١٥) وذكره ابن أبى حاتم في الجرح (٤/ ١/ ٤٠٨) أيضًا عن عبد اللَّه بن أحمد عن أبيه به."}],[3328,"٢١٠٦ - أبو عمر النخعى المنبهى (١). سمع أبا جحيفة روى عنه (٢)."],[3329,"٢١٠٧ - أبو عمر، مولى بشر بن غالبا (٣)، عن محمد بن الحنفية، روى عنه إسماعيل بن (سلمان) (٤) الازرق.","",{"fn":"المنبهى: منبه: مدينة من مدن الشام بناها كسرى لما غلب على الشام فعربت وقيل: مَنْبِج، بالفتح ثم السكون وباء موحدة مكسورة وجيم، والنسبة إليها منْبِجى، بفتح الميم وسكون السكون كسر الباء الموحده وبعدها جيم. انظر معجم البلدان (٥/ ٢٠٥)، اللباب (٣/ ٢٥٩)، تبصير المنتبه (٤/ ١٣٩٤).\nهكذا في الأصل \"روى عنه\" ولم يذكر شيئا بعدها وكذا هو في الجرح وفى مصادر الترجمة \"روى عنه شريك القاضى\". ٢١٠٧ - الجرح (٤/ ٢/ ٤٣٠) وقال: دينار بن عمر أبو عمر البزار الاسدى مولى بشر ابن غالب، كوفى، روى عن زيد بن ارقم، وابن الحنفية ومسلم البطين، روى عنه إسماعيل بن سلمان، وسفيان الثورى، . . وذكر توثيق أحمد بن حنبل له. التهذيب (٣/ ٢١٦).\nبشر بن غالب، أسدى ذكره ابن أبى حاتم في الجرح (١/ ١/ ٣٦٣) ولم يذكر فيه شيئا.\nفي الأصل \"سليمان\" والتصحيح عن الجرح (١/ ٢/ ٤٣٠) وعن التهذيب (٣/ ٢١٦) ذكراه في ترجمة دينار بن عمر أبو عمر البزار. وقال ابن أبى حاتم أيضًا في الجرح (١/ ١/ ١٧٦) إسماعيل بن سلمان الكوفى الازرق، وذكر روايته عن أبى عمر البزار، وقال ابن حجر في التهذيب (١/ ٣٠٣): إسماعيل بن سلمان بن أبى المغيرة الازرق التميمى الكوفى، روى عن أنس ="}],[3330,"٢١٠٨ - أبو عمر الشامى (١) عن عبيد بن الخشخاش (٢) عن أبى ذر روى عنه المسعودى."],[3331,"٢١٠٩ - أبو عمر الدمشقى، عن كعب، روى عنه معاوية بن صالح."],[3332,"٢١١٠ - أبو عمر، روى عن عاصم الجحدرى، روى عنه هارون النحوى (٣)."],[3333,"٢١١١ - أبو عمر، مولى لبنى خزيمة، روى عن مورّق العجلى، روى عنه سلام بن مسكين."],[3334,"٢١١٢ - أبو عمر، روى عن الحسن، روى عنه إسماعيل بن عبد الملك (٤) قال أبو حاتم: هو مجهول.","",{"fn":"في الميزان \"الدمشقى\".\nفي كنى البخارى، والتهذيب \"الحسحاس\" بالمهملات، وفى التقريب (١/ ٥٤٣)، عبيد بن الخشخاش بمعجمات، وقيل: بمهملات، لين من الثالثة. ٢١٠٩ - كنى البخارى (ص ٥٦)، الجرح (٤/ ٢/ ٤٠٧). ٢١١٠ - الجرح (٤/ ٢/ ٤٠٨).\nهارون بن موسى الازدى العتكى، مولاهم، الاعور النحوى البصرى، ثقة، مقرئ إلا أنه رمى بالقدر، من السابعة. انظر التقريب (٢/ ٣١٣). ٢١١١ - كنى البخارى (ص ٥٦)، الجرح (٤/ ٢/ ٤٠٨)، الثقات (٧/ ٦٦٠). ٢١١٢ - كنى البخارى (ص ٥٥)، الجرح (٤/ ٢/ ٤٠٨) وقال: سمعت أبى يقول: هو مجهول، الميزان (٤/ ٥٥٥). وقال: مجهول.\nإسماعيل بن عبد الملك بن أبى الصُّفَيْر، بالمهملة والفاء مصغرا، صدوق، كثير الوهم، من السادسة. التقريب (١/ ٧٢)."}],[3335,"٢١١٣ - أبو عمر الدِّيلى، روى عن عبد العزيز بن أبى رواد، روى عنه ابن أبى فديك."],[3336,"٢١١٤ - وعمر الهِزَّانِى (١). سمع محمد بن على. روى عنه حجاج بن حسان (٢)."],[3337,"٢١١٥ - أبو عمر الازرق، الازدى بن المنهال (. . . .) (٣) سمع سفيان بن عيينة. روى عنه محمد بن عمرو الرازى (٤)."],[3338,"٢١١٦ - أبو عمر (الاشجعى) (٥) كوفى. عن سالم بن أبى الجعد، روى عنه عطاء بن مسلم الخفاف (٦).","",{"fn":"الهِزَّانى: بكسر الهاء وفتح الزاى المشددة وبعد الالف نون - هذه النسبة إلى هِزَّان وهو بطن من العتيك، والعتيك من ربيعة وهو هزان بن صباح بن عتيك بن اسلم. اللباب (٣/ ٣٨٧).\nحجاج بن حسان القيسى، البصرى، لا بأس به، من الخامسة. التقريب (١/ ١٥٢)، التهذيب (٢/ ٢٠٠). ٢١١٥ - المقتنى في سرد الكنى (١٠٢/ أ).\nيوجد بياض في الأصل بمقدار كلمة.\nمحمد بن عمرو بن بكر الرازى، أبو غسان زنُيَجْ، بزاى ونون وجيم، مصغرا، ثقة، من العاشرة، مات في آخر سنة (٢٤٠) أو أول التى بعدها. التقريب (٢/ ١٩٥). ٢١١٦ - الميزان (٤/ ٥٥٥) وقال: مجهول. المقتنى في سرد الكنى (١٠٢/ أ).\nغير واضح في الأصل، والمثبت عن الميزان.\nعطاء بن مسلم الخفاف، كوفى، نزل حلب، صدوق يخطئ كثيرا، من الثامنة (ت: ١٩٠). انظر التقريب (٢/ ٢٢)."}],[3339,"٢١١٧ - أبو عمر الصَّفَّار عن عبيد (١) اللَّه بن العيزار روى عنه المقبرى (٢).","",{"fn":"في كنى البخارى \"عبد اللَّه\".\nفي كنى البخارى \"المُقْرئ\"."}],[3340,"باب أبى عثمان"],[3341,"٢١١٨ - أبو عثمان، شهد عبد اللَّه بن عباس والحسن بن على اتتهما امرأة فقالت: إن زوجى يطلقنى ويجحدنى فقال ابن عباس: ارفعى أمره إلى معاوية فقال الحسن إلا تفتيهما قال: بماذا؟ فقال: يحلف ثلاث مرات ما طلق (١)."],[3342,"روى عنه الهذيل بن بلال الفزارى (٢).","",{"fn":"الأثر أخرجه سعيد بن منصور في السنن (١/ ٣٥٨) وابن أبى شيبة (٥/ ٧٩) عن الحسن قال: تقدمه إلى السلطان فتستحلفه ثلاثا وأخرجه أيضًا ابن أبى شيبة من طريق شيخ يكنى أبا عمرو قال: كنت جالسا عند ابن عباس فأتته امرأة فقالت: إن زوجها يطلقها في السر ويجحد في العلانية فقال: عليه أن يحلف أربع شهادات باللَّه ما طلق والخامسة أن لعنة اللَّه عليه إن كان فعل. وأخرجه أيضًا عبد الرزاق (٦/ ٤١٤ و٤١٥) من طريق قتادة عن الحسن قال: يستحلف ثم يكون الاثم عليه. قال: وقال قتادة: يستحلف بين الركن والمقام.\nهذيل بن بلال الفزارى، ذكره ابن أبى حاتم في الجرح (٤/ ٢/ ١١٣) وقال: سألت أبى عن هذيل بن بلال فقال: محله الصدق، يكتب حديثه. . سئل أبو زرعة عنه فقال: هو لين ليس بالقوى، وقال الدورى عن ابن معين كان ينزل المدائن، وليس بشئ. انظر التاريخ (٢/ ٦١٥)."}],[3343,"٢١١٩ - أبو عثمان بن (سَنَّه) (١)، (٢) شامى. روى عن ابن مسعود. روى عنه الزهرى قال أبو زرعة: لا أعرف اسمه. قال أبو عمر: قد ذكره بعضهم في الصحابة وغير بعيد ان يدرك النبى عليه السلام."],[3344,"٢١٢٠ - أبو عثمان، روى عن أبيه عن معقل بن يسار عن النبى عليه السلام أنه قال: \"اقرأوا \"ياسين\" على موتاكم\" (٣)، رواه محمد بن كثير عن ابن المبارك عن سليمان التيمى عنه وليس بالنهدى (١).","",{"fn":"صورتها في الأصل \"سبط\" والذى في مصادر الترجمة \"سنة\" وقال في التقريب سنة بفتح المهملة وتشديد النون. فاللَّه أعلم.\nزاد في التهذيب \"الخزاعى الكعبى الدمشقى\". ٢١٢٠ - كنى البخارى (ص ٥٧) وذكره كما هنا. الثقات (٧/ ٦٦٤) وقال: ليس بالنهدى. الجرح (٤/ ٢/ ٤٠٨) وذكر الحديث. الميزان (٤/ ٥٥٠) وقال: يقال: اسمه سعد، عن أبيه. . الخ وقال: لا يعرف أبوه ولا هو ولا روى عنه سوى سليمان التيمى، التهذيب (١٢/ ١٦٣) وقال: قيل: اسمه سعد روى عن معقل بن يسار وأنس بن مالك بن جندل، وقيل: عن أبيه عن معقل. . روى عنه سليمان التيمى. قال ابن المدينى: لم يرو عنه غيره وهو مجهول، وقال في التقريب (٢/ ٤٤٩) مقبول، من الرابعة./ د. س. ق.\nالحديث أخرجه أبو داود \"الجنائز\" باب القراءة عند الميت (٣/ ١٩١) وابن ماجه \"كتاب الجنائز\" باب ما يقال عند المريض إذا حضر (١/ ٤٦٥)، وأحمد في المسند (٥/ ٢٦/ ٢٧) وابن حبان. كما في موارد الظمآن (ص ="}],[3345,"٢١٢١ - أبو عثمان العدوى. روى عن أبى جهم (٢) عن سالم (٣) عن أبيه عن النبى عليه السلام قال: \"لا ينظر اللَّه إلى الاشمط الزانى\" (٤). قال أبو زرعة: لا أعرفه إلا بهذا الحديث.","",{"fn":"النهدى، هو أبو عثمان النهدى المتقدم في (٢٦٠). ٢١٢١ - الجرح (٤/ ٢/ ٤٠٨) وقال: سألت أبا زرعة عنه فقال: لا أعرفه إلا في هذا الحديث.\nهو ابن صخير انظر (١٤٥٢).\nهو ابن عبد اللَّه بن عمر.\nالحديث رواه الطبرانى من حديث ابن عمر قال: قال رسول اللَّه -صلى الله عليه وآله وسلم- \"لا ="}],[3346,"٢١٢٢ - أبو عثمان. سمع أبا هريرة قال: أوصانى خليلى (١) أن أوتر بسبع (٢) روى عنه معاوية بن صالح."],[3347,"٢١٢٣ - أبو عثمان الترمسى دمشقى.","",{"fn":"قال الحافظ ابن حجر في الفتح (٣/ ٥٧): الخليل: الصديق الخالص الذى تخللت محبته القلب فصارت في خلاله، أى في باطنه.\nالحديث أخرجه البخارى في الكنى (ص ٥٧) وابن حبان في الثقات (٥/ ٥٦٧) وابن أبى حاتم في الجرح (٤/ ٢/ ٤٠٩) وفيه عندهم لفظ \"أوصانى خليلى أن اوتر بسبع سور أقرا في ثلاث الوتر منهن\" ﴿قُلْ هُوَ اللَّهُ أَحَدٌ﴾ والمعوذتين. والحديث أخرجه أيضًا البخارى \"التهجد\" باب صلاة الضحى في الحضر (٣/ ٥٦) وفى \"الصوم\" باب صيام البيض (٤/ ٢٢٦) ومسلم \"صلاة المسافرين\" باب استحباب صلاة الضحى (١/ ٤٩٩)، والنسائى \"الصيام\" باب ذكر الاختلاف على أبى عثمان في حديث أبى هريرة في صيام ثلاثة أيام (٤/ ٢١٨) ومحمد بن نصر المروزى في كتاب الوتر - باب اختيار الوتر أول الليل (ص ٢٠١) وأبو داود \"الصلاة\" باب الوتر قبل النوم (٢/ ٦٥)، وأحمد في المسند (٢/ ٢٢٩، ٢٣٣، ٢٥٤، ٢٦٠، ٢٦٥، ٢٧١، ٣١١، ٣٢٩، ٣٤٧، ٣٧٧، ٤٠٢، ٤٥٩، ٤٧٢، ٤٨٤، ٤٨٩، ٤٩٧، ٤٩٩، ٥٠٥، ٥٢٦)، واسحاق بن راهوية. وأبو يعلى في المسند كما في فتح البارى (٢/ ٤٨٦) كلهم أخرجوه بنحوه من حديث أبى هريرة رضي الله عنه. ٢١٢٣ - لم أقف له على ترجمة عند غير المؤلف."}],[3348,"٢١٢٤ - أبو عثمان الجهنى المدنى. سمع ربيعة بن أبى عبد الرحمن (١). روى عنه مطرف بن مازن الصنعانى (٢)."],[3349,"٢١٢٥ - أبو عثمان الجيشانى مصرى. عن عقبة بن عامر. روى عنه جعفر القتبانى."],[3350,"٢١٢٦ - أبو عثمان من ولد أبى العاص قال: غزا محمد بن أبى حذيفة بن عتبة. روى عنه محمد بن وهب بن هشام."],[3351,"٢١٢٧ - أبو عثمان بن جبيريت مطعم. روى عن أبيه. روى عنه كلاب بن على (٣).","",{"fn":"ربيعة بن أبى عبد الرحمن هو ربيعة الرأى، واسم أبيه فروخ، ثقة فقيه مشهور، قال ابن سعد: كانوا يتقونه لموضع انرأى، من الخامسة. التقريب (١/ ٢٤٧).\nمطرّف بن مازن الصنعانى، ولى القضاء بصنعاء، وتوفى بالرّقَّة، ويقال: مات بمنبج، قال ابن أبى حاتم: قرئ على العباس الدورى قال: سئل يحيى بن معين عن مطرف بن مازن فقال: كذاب. انظر الجرح (٤/ ١/ ٣١٤)، تاريخ ابن معين (٢/ ٥٧٠). ٢١٢٥ - المقتنى في سرد الكنى (٩٢/ أ). ٢١٢٦ - لم أقف له على ترجمة عند غير المؤلف. ٢١٢٧ - المقتنى في سرد الكنى (٩٣/ أ).\nكلاب بن على الجعفرى العامرى، مجهول، من السادسة. تمييز التقريب (٢/ ١٣٧)، التهذيب (٨/ ٤٥٢)."}],[3352,"باب أبى على"],[3353,"٢١٢٨ - أبو على الكاهلى (١)، سمع أبا موسى الاشعرى، سمع منه عبد الملك بن أبى سليمان."],[3354,"٢١٢٩ - أبو على (٢) الصيقل (٣) روى عن جعفر بن تمام (٤). روى عنه منصور والثورى.","",{"fn":"الكاهلى: بفتح أوله وسكون الألف كسر الهاء واللام - نسبة إلى كاهل بن الحارث بن تميم بن سعد هذيل بن مدركة بن الياس بن مضر. اللباب (٣/ ٧٩). ٢١٢٩ - كنى البخارى (ص ٥٢)، الجرح (٤/ ٢/ ٤٠٩)، الميزان (٤/ ٥٥٤) وقال: قال أبو على بن السكن وغيره: مجهول، اللسان (٧/ ٨٣) وقال: مثل قول الذهبى. تعجيل المنفعة (ص ٣٣٢).\nزاد في تعجيل المنفعة \"الرداد\".\nزاد في الميزان واللسان \"مولى بنى أسد\".\nذكره ابن أبى حاتم في الجرح (١/ ١/ ٤٧٥) فقال: جعفر بن تمام بن العباس بن عبد المطلب روى عن أبيه روى عنه أبو حازم المدينى، وابن أبى ذئب، وأبو على الصيقل سمعت أبى يقول ذلك. ثم قال ابن أبى حاتم: سئل أبو زرعة عن جعفر بن تمام بن العباس بن عبد المطلب فقال: مدينى ثقة، أهـ."}],[3355,"٢١٣٠ - أبو على بن يزيد بن مُشْكان (١). الايلى -أخو يونس بن يزيد الايلى- مولى معاوية بن أبى سفيان روى عن ابن شهاب الزهرى. روى عنه أخوه يونس بن يزيد."],[3356,"٢١٣١ - أبو على الخزاز. عن عبد الرحمن بن أبى ليلى يعد في الكوفيين."],[3357,"٢١٣٢ - أبو على الليثى من بنى ليث بن بكر بن عبد مناة المدنى حكى موت الصَّعْب بن جَثَّامَة (٢) روى عنه محمد بن إسماعيل البخارى.","",{"fn":"مُشْكَان: بالشين المعجمة وضم الميم. الاكمال (٧/ ٢٥٦). ٢١٣١ - المقتنى في سرد الكنى (٩٩/ ب) وقال: أبو على الهمدانى من عبد الرحمن ابن أبى ليلى. كوفى. ٢١٣٢ - المقتنى في سرد الكنى (٩٩/ ب).\nالصعب، بفتح أوله وسكون المهملة، ابن جثامة، بفتح الجيم وتشديد المثلثة، الليثى، صحابى، مات في خلافة الصديق، والأصح أنه عاش إلى خلافة عثمان. انظر التقريب (١/ ٣٦٧)."}],[3358,"باب أبى عمرو"],[3359,"٢١٣٣ - أبو عمرو بن عاصم بن عدى الأنصارى المدنى الاوسى العجلانى يعرف بأبى البدّاح بن عاصم بن عدى. روى عن أبيه (١). روى عنه أبو بكر بن محمد بن عمرو بن حزم وابنه عاصم بن أبى البداح."],[3360,"٢١٣٤ - أبو عمرو. سمع عثمان. روى عنه ابنه."],[3361,"٢١٣٥ - أبو عمرو بن حِمَاس (٢) بن عمرو الليثى. من أنفسهم مدنى كان عندهم من العبَاد. سمع مالك بن أوس بن الحَدَثَان النّصرى (٣) وحمزة بن عبد اللَّه بن عمر بن الخطاب (١). روى عنه محمد بن عمرو بن علقمة بن وقاص وابنه شداد بن أبى عمرو (٢)، ويحيى بن سعيد.","",{"fn":"عاصم بن عدى بن الجد بن العجلان بن حارثة البلوى، يروى عنه ابنه وسهل ابن سعد والشعبى، حليف بنى عمرو بن عوف أخو معن، بدرى أُحُدِى، وكان سيد بنى العجلان، وهو والد أبى البداح. انظر التجريد (١/ ٢٨٢). ٢١٣٤ - لم أقف له على ترجمة عند غير المؤلف. ٢١٣٥ - كنى البخارى (ص ٥٥) الطبقات الكبرى (٥/ ٦٢)، المقتنى في سرد الكنى (١٠٥/ أ)، الجرح (٤/ ٢/ ٤١٠)، الميزان (٤/ ٥٥٧) وقال: مجهول، التهذيب (٢/ ١٧٨)، التقريب (٢/ ٤٥٤) وقال: مقبول، من السادسة. (ت: ١٣٩)./ د.\nحماس: قال ابن ماكولا في الاكمال (٢/ ٤٩٩) حماس: بالسين المهملة فهو حماس بن عمرو الليثى، عن عمر بن الخطاب رضي الله عنه روى عنه ابنه أبو عمر. اهـ. وفى تبصير المنتبه (١/ ٤٥٢) حِمَاس، بالكسر وتخفيف الميم. اهـ.\nمالك بن أوس بن الحَدَثَان، بفتح المهملة والمثلثة النصرى بالنون أبو سعيد ="}],[3362,"٢١٣٦ - أبو عمرو العبدى (٣). ويقال: العنزى كان له علم. روى عنه عبد اللَّه بن أبى الهذيل العمرى قوله."],[3363,"٢١٣٧ - أبو عمرو السَّيْبَانى (٤). والد يحيى بن أبى عمرو، شامى سمع عمر بن الخطاب، وعقبة بن عامر الجهنى، روى عنه ابنه يحيى.","",{"fn":"عبد اللَّه هو شقيق سالم، ثقة، من الثالثة. التقريب (١/ ١٩٩).\nشداد أبى عمرو حِمَاس، بكسر المهملة، الليثى المدنى، مجهول من السادسة. التقريب (١/ ٣٤٧). ٢١٣٦ - كنى البخارى (ص ٥٤)، الجرح (٤/ ٢/ ٤٠٩).\nزاد في كنى البخارى \"السروى\". ٢١٣٧ - كنى البخارى (ص ٥٤)، الجرح (٤/ ٢/ ٤٠٩)، الاكمال (٥/ ١١١) المقتنى في سرد الكنى (١٠٥/ أ)، الثقات (٥/ ٥٨١) وقال أبو عمرو السيبانى، من أهل الرملة يروى عن عمر بن الخطاب، روى عنه ابنه يحيى ابن أبى عمرو، وأبو عمرو السيبانى من أهل الكوفة. اهـ. الميزان (٤/ ٥٥٨) وقال: أبو عمرو السيبانى بمهملة، الفلسطينى، اسمه زرعة له من عقبة بن عامر وأبى هريرة وعنه ابنه يحيى بن أبى عمرو السيبانى وجماعة وهو مقل يقال: لحق عمر، وثقة يعقوب الفسوى. اهـ. اللسان (٧/ ٤٧٦)، التهذيب (١٢/ ١٨٢) وقال أبو عمرو السيبانى الشامى الفلسطينى اسمه زرعة وهو عم الأوزاعى. التقريب (٢/ ٤٥٥) وقال: مقبول، من الثانى./ بخ.\nالسَّيبانى: بالمهملة والموحدة بينهما تحتانية ساكنة، اللسان (٧/ ٤٧٦) وقال في الاكمال (٥/ ١١١): السَّيبانى، بسين مهملة. وانظر تبصير المنتبه (٢/ ٨٢٠) وسيبان بطن من حمير كما سبق وأن عرفت."}],[3364,"٢١٣٨ - أبو عمرو (١) بن حريث.","",{"fn":"في تهذيب الكمال والتهذيب، والميزان، واللسان \"أبو عمرو بن محمد بن حريث\" وفى تهذيب الكمال، والتهذيب واللسان، وقيل: \"أبو محمد بن عمرو بن حريث، جد لاسماعيل بن أمية لأمه\". وقد ذكره ابن حبان في أبى محمد فقال: أبو محمد بن عمرو بن حريث. . الخ. قلت: وقد اختلف عليه في حديثه وهو حديث الخط، فقد أخرج البخارى في التاريخ الكبير (١/ ٢/ ٧١) عن أبى هريرة، وابن ماجه \"الإقامة\" باب ما يستر المصلى (١/ ٣٠٣) من طريق حميد الأسود وسفيان بن عيينه كلاهما عن إسماعيل بن أمية عن أبى عمرو بن محمد بن عمرو بن حريث عن جده حريث بن سليم، عن أبى هريرة عن النبى -صلى الله عليه وآله وسلم- قال: \"إذا صلى أحدكم فليجعل تلقاء وجهه شيئا فإن لم يجد فلينصب عصا فإن لم يجد فليخط خطا، ثم لا يضره ما بين يديه. وأخرجه أحمد في المسند (٢/ ٢٤٩) من طريق سفيان عن إسماعيل بن أميه عن أبى محمد بن عمرو بن حريث قال مرة: عن أبى عمرو بن محمد بن حريث عن جده، عن أبى هريرة به. وفى المسند (٢/ ٢٥٥) أيضًا من طريق معمر والثورى عن إسماعيل بن أمية عن عمرو بن حريث عن أبيه عن أبى هريرة به. وأيضًا في المسند (٢/ ٢٦٦) من طريق معمر والثورى عن إسماعيل بن أمية عن أبى عمرو بن حريث عن أبيه، عن أبى هريرة به. والاضطراب ظاهر في هذا الحديث كما هو ملاحظ، وقيل: الاضطراب فيه من إسماعيل بن أمية، وقال البخارى في التاريخ الكبير (١/ ٢/ ٧٢) قال سفيان: جاءنا بصرى عتبة أبو معاذ قال: لقيت هذا الشيخ الذى روى عنه إسماعيل فسألته فخلط على. قال الحافظ في التهذيب (٢/ ٢٣٦) فهذا يدل على أن أبا عمرو بن ="}],[3365,"العذرى (١). روى عن جده (٢)، عن أبى هريرة روى عنه إسماعيل بن أمية وعبيد النصرى."],[3366,"٢١٣٩ - أبو عمرو العدوى. وقيل: العبدى الاجدع كوفى، كان من أصحاب على رضي الله عنه. وروى (عن) (٣) على في \"الجدّاب\" (٤). روى عنه ليث بن أبى سليم.","",{"fn":"العذرى: بضم العين وسكون الذال وفى آخرها راء - نسبة إلى عذرة قبيلة من قضاعة. اللباب (٢/ ٣٣١).\nجده: هو حريث، نسب أبو عمرو إليه، وفى التقريب (١/ ١٥٩) حريث رجل من بنى عذرة، اختلف في اسه أبيه فقيل: ابن سليم، أو سليمان أو عمار، مختلف في صحبته، وعندى أن راوى حديث الخط، غير الصحابى، بل هو مجهود، من الثالثة. اهـ. ٢١٣٩ - كنى البخارى (ص ٥٤)، الجرح (٤/ ٢/ ٤٠٩ - ٤١٠)، المقتنى في سرد الكنى (١٠٥/ أ).\nفي الأصل \"عنه\" بزيادة الهاء في آخره. والمثبت، عن مصادر الترجمة وعن أصول التخريج كما سيأتى. وهو الصواب.\nالحديث أخرجه البخارى في الكنى (ص ٥٤)، والبيهقى (٦/ ٢٤٦) من طريق حفص بن غياث عن ليث عن أبى عمرو العبدى، عن على رضي الله عنه قال: \"الديّة لمن احرز الميراث، والجد أب\". وأخرجه أيضًا عبد الرزاق (١٠/ ٢٦٤) من حديث على رضي الله عنه به. ويشهد لهذا الحديث حديث علقه البخارى \"الفرائض\" باب ميراث الجد مع الأب والاخوة. قال: وقال أبو بكر وابن عباس، وابن الزبير: الجد أب ="}],[3367,". . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . ."],[3368,"٢١٤٠ - أبو عمرو، مولى المطلب بن حنطب (١) رأى ابن عمر (٢). روى عنه محمد بن اسحاق."],[3369,"٢١٤١ - أبو عمرو، مولى أنس بن مالك بصرى، روى عنه الربيع بن سليمان (٣)."],[3370,"٢١٤٢ - أبو عمرو الازدى، شامى. روى عن بشير مولى معاوية روى عنه معاوية بن صالح."],[3371,"٢١٤٣ - أبو عمرو الموصلى، عن فراس، روى عنه معن بن عيسى."],[3372,"٢١٤٤ - أبو عمرو الرازى (٤). روى عن ابن عجلان وزيد بن أسلم. هو عندهم مجهول.","",{"fn":"المطّلب، بن حنطب بن الحارث المخزومى أبو عبد اللَّه، ذكره ابن اسحاق فيمن أُسر يوم بدر ثم أسلم. روى عنه ابنه عبد اللَّه. الإصابة (٣/ ٤٢٥)، التجريد (٢/ ٧٩).\nفي الثقات والجرح (رأى عمر). ٢١٤١ - كنى البخارى (ص ٥٥)، الجرح (٤/ ٢/ ٤١٠).\nفي كنى البخارى والجرح \"سليم\". ٢١٤٢ - كنى البخارى (ص ٥٥)، الجرح (٤/ ٢/ ٤١٠)، المقتنى في سرد الكنى (١٠٥/ أ). ٢١٤٣ - كنى البخارى (ص ٥٥)، الجرح (٤/ ٢/ ٤١٠)، المقتنى في سرد الكنى (١٠٥/ أ). ٢١٤٤ - كنى البخارى (ص ٥٥)، المقتنى في سرد الكنى (١٠٥/ أ)، الجرح (٤/ ٢/ ٤١٠) وقال: سمعت أبى يقول: هو مجهول، ديوان الضعفاء (ص ٣٦٢) وقال: مجهول، الميزان (٤/ ٥٥٦). وقال: مجهول اللسان (٧/ ٨٧) وقال: مجهول.\nفي الجرح، والميزان، وديوان الضعفاء \"الدارى\" بالدال المهملة والراء."}],[3373,"٢١٤٥ - أبو عمرو الجَمَلى (١) مجهول. روى عن زاذان، روى عنه صدقة (ابن) (٢) سهل."],[3374,"٢١٤٦ - أبو عمرو (٣) مولى بنى أمية. سمع محمد بن أبى سفيان (٤)، روى عنه ابن المبارك."],[3375,"٢١٤٧ - أبو عمرو، صاحب القمص. قال يحيى بن معين: أبو عمرو صاحب القمص ثقة، ذكره اسحاق بن منصور عن ابن معين (٥)."],[3376,"٢١٤٨ - أبو عمرو، روى عن قيس بن سعد المكى، روى عنه معتمر بن سليمان.","",{"fn":"الجَمَلى: بفتح الجيم والميم وبعدها اللام -هذه النسبة- إلى جمل بن كنانة بن ناجية بن مراد وهو بطن من مراد. اللباب (١/ ٢٩٢).\nهكذا في الأصل \"بن\" وفى كنى البخارى والجرح والمقتنى \"أبو\" وفى الجرح (٢/ ١/ ٤٣١) قال ابن أبى حاتم عن أبيه: صدقة أبو سهل الهنائى، روى عن محمد بن سيرين وأبى عمرو الجملى وشيخ كبير من بنى شيبة. وذكر أن ابن معين وثقه. ٢١٤٦ - الجرح (٢/ ١/ ٤١٠)، الثقات (٧/ ٦٥٩)، كنى البخارى (ص ٥٦).\nالذى في مطبوعة كنى البخارى \"أبو عمر مولى بنى أمية\".\nمحمد بن أبى سفيان بن حرب، الأموى، أخو معاوية، مقبول، من الثالثة، وقيل: الصواب، عنبسة بن أبى سفيان./ س. التقريب (٢/ ١٦٥). ٢١٤٧ - الجرح (٤/ ٢/ ٤١١).\nانظر الجرح (٤/ ٢/ ٤١١). ٢١٤٨ - الجرح (٢/ ٢/ ٤١١) وقال: سئل أبو زرعة عنه فقال: لا أعرفه."}],[3377,"٢١٤٩ - أبو عمرو. روى عن أنس بن مالك عن النبى عليه السلام أنه قال: \"يخرج من النار قوم يسمون الجهنَّميُّون\" (١).","",{"fn":"الحديث أخرجه ابن أبى حاتم في الجرح (٤/ ٢/ ٤١١)، والطبرانى في الأوسط من حديث أنس رضي الله عنه قال: قال رسول اللَّه -صلى الله عليه وآله وسلم- \"إن أناسا من أهل لا إله إلا اللَّه يدخلون النار بذنوبهم فيقول لهم أهل اللات والعزى ما أغنى عنكم قولكم لا اله إلا اللَّه وأنتم معنا في النار، فيغضب اللَّه لهم فيخرجهم فيقذف بهما في نهر الحياة فيبرؤون من حرقهم، كما بيرأ القمر من كسوفه فيدخلون الجنة فيسميهم أهل الجنة الجهنميين، فقال رجل: يا أنس سمعت هذا من رسول اللَّه -صلى الله عليه وآله وسلم- فقال أنس: سمعت رسول اللَّه -صلى الله عليه وآله وسلم- يقول: \"من كذب على متعمدا فليتبوأ مقعده من النار\"، أنا سمعت رسول اللَّه -صلى الله عليه وآله وسلم- يقول هذا. انظر مجمع الزوائد (١٠/ ٣٧٩) وقال الهيثمى: فيه من لم أعرفهم. وحديث أنس أخرجه أيضًا البخارى \"الرقاق\" باب صفة جهنم (١١/ ٤١٦) وفى \"التوحيد\" باب ما جاء في قوله اللَّه تعالى ﴿إِنَّ رَحْمَتَ اللَّهِ قَرِيبٌ مِنَ الْمُحْسِنِينَ﴾ [الأعراف: ٥٦] (٣/ ٣٤٣) من طريق قتادة عنه مرفوعًا بلفظ \"يخرج قوم من النار بعد ما مسهم منها سَفْع فيدخلون الجنة فيسميهم أهل الجنة الجهنميين\". والسَّفْع بفتح المهملة وسكون الفاء ثم عين مهملة، أى سواد فيه زرقة، أو صفرة، يقال: سفعته النار إذا لفحته فغيرت لون بشرته. انظر فتح البارى (١١/ ٤٢٩). وأخرجه أيضًا ابن خزيمة في كتاب التوحيد ص (٢٨١) عن أنس به ويشهد لحديث أنس هذا حديث عمران بن حصين رضي الله عنهما أخرجه البخارى \"الرقاق\" باب صفة جهنم (١١/ ٤١٨) مرفوعا به. وحديث جابر رضي الله عنه أخرجه مسلم \"الإيمان\" باب أدنى أهل الجنة منزلة فيها (١/ ١٧٩) بنحو حديث أنس رضي الله عنه. وحديث المغيرة أخرجه الطبرانى في الأوسط مرفوعا بلفظ قال: \"يخرج ="}],[3378,"روى عنه زيد بن أبى أنيسة (١)."],[3379,"٢١٥٠ - أبو عمرو بن العلاء بن عمار بن العريان بن خزاعى بن مازن بن مالك بن عمرو بن تميم التميمى (المازنى) (٢) صاحب القراءة والغريب. قيل: اسمه كنيته. وقيل: اسمه زبّان وقد ذكرناه فيمن وقف على اسمه ممن عرف بكنيته."],[3380,"٢١٥١ - أبو عمرو، أو أبو عمر مولى بشر بن غالب. روى عن محمد بن (الحنفية) (٣). روى عنه إسماعيل بن (سليمان) (٤) الازرق.","",{"fn":"زيد بن أبى أنيسة، كوفى، سكن الرها، ثقة له افراد، من السادسة (ت: ١١٩) وقيل: (١٢٤). التقريب (١/ ٢٧٢). ٢١٥٠ - تقدم. انظر الترجمة (٩٣٩) والتعليق عليها وترجمته هناك مطولة أكثر منها هنا.\nالحق في هامش الأصل. وكتب عنده كلمة \"صح\". ٢١٥١ - تقدم في أبى عمر انظر الترجمة (٢١٠٧) والتعليق عليها.\nفي الأصل \"الحبيب\" وفى ترجمة أبى عمر في (٢١٠٧) \"الحنفية\"، وهو محمد بن الحنفية كما أثبته واللَّه أعلم.\nهكذا في الأصل \"سليمان\" ولعل الصواب سلمان كما سبق وإن عرفت في ترجمة أبى عمر مولى بشر في (٢١٠٧)."}],[3381,"باب أبى عيسى"],[3382,"٢١٥٢ - أبو عيسى (١) الأُسْوارى (٢)، بصرى، روى عن أبى سعيد الخدرى، وعبد اللَّه بن عمر، روى عنه قتادة، وعاصم بن سليمان الأحول، وقد قال الميمونى، عن أحمد بن حنبل: لا أعلم أحدا روى عن أبى عيسى الاسوارى غير قتادة."],[3383,"٢١٥٣ - أبو عيسى، مدنى، روى عن أنس بن مالك عن النبى عليه السلام. روى عنه صفوان بن سليم."],[3384,"٢١٥٤ - أبو عيسى، سمع عطاء الخراسانى. روى عنه سعيد بن أبى أيوب يعد في المصريين. واظنه أبا عيسى موسى بن عيسى القرشى.","",{"fn":"زاد في: الثقات \"الحارثى\".\nالاسوارى: بضم الهمزة وسكون السين المهملة وفتح الواه وفى آخرها الراء المهملة - هذه النسبة إلى أُسْوار. والمشهور بهذه النسبة أبو عيسى الاسوارى. كذا قال ابن الاثير. اللباب (١/ ٦٠). ٢١٥٣ - الجرح (٤/ ٢/ ٤١٢). ٢١٥٤ - المقتنى في سرد الكنى (١٠٨/ أ)."}],[3385,"٢١٥٥ - أبو عيسى الدمشقى، سمع ابن شهاب الزهرى، روى عنه هشام ابن عمار عن الزهرى، قال: \"مر النبى عليه السلام برجل يتوضأ وهو يفرغ الماء في وضوئه إفراغا فقال: لا تسرف فقال: يا رسول اللَّه وفى الوضوء اسراف؟ قال: نعم وفى كل شئ اسراف\" (١)."],[3386,"٢١٥٦ - أبو عيسى الناجى، بصرى، كان من قدماء أصحاب الحسن، روى عن الحسن، وعن سعيد بن مِينْا (٢). روى عنه الجريرى والسرى بن يحيى.","",{"fn":"الحديث ذكره السيوطى في الجامع الكبير (٢/ ٨١٤) من مراسيل الزهرى ولم يعزه. ولكن يشهد له حديث ابن عمر رضي الله عنه في سنن ابن ماجه \"الطهارة\" - باب ما جاء في القصد في الوضوء وكراهية التعدى (١/ ١٤٧) قال: \"رأى رسول اللَّه -صلى الله عليه وآله وسلم- رجلا يتوضأ فقال: \"لا تسرف لا تسرف\" وقال السندى: إسناده ضعيف. وأخرح ابن ماجه أيضًا (١/ ١٤٧) حديث عبد اللَّه بن عمرو \"أن رسول اللَّه -صلى الله عليه وآله وسلم- مر بسعد، وهو يتوضأ فقال: ما هذا السرف؟ فقال: أفى الوضوء اسراف؟ قال: نعم. وإن كنت على نهر جار\" وقال السندى: إسناده ضعيف، وقال البخارى \"كتاب الوضوء\" باب ما جاء في الوضوء (١/ ٢٣٢). وبين النبى -صلى الله عليه وآله وسلم- إن فرض الوضوء مرة مرة. ويتوضأ أيضًا مرتين، وثلاثًا ولم يزد على ثلاث وكره أهل العلم الإسراف فيه وأن يجاوزوا فعل النبى -صلى الله عليه وآله وسلم-. اهـ ٢١٥٦ - كنى البخارى (ص ٥٧)، الثقات (٧/ ٦٥٨)، الجرح (٤/ ٢/ ٤١٢) وقال: سألت أبى عنه فقال: هو شيخ للجريرى ليس بمعروف، المقتنى في سرد الكنى (١٠٨/ ب).\nسعيد بن مِينا -أى بكسر الميم ومد النون-، مولى البخترى، بن أبى ذباب الحجازى، مكى أو مدنى، يكنى أبا الوليد، ثقة، من الثالثة./ التقريب (١/ ٣٠٦)، الخلاصة (ص ١٤٣)."}],[3387,"٢١٥٧ - أبو عيسى الخراسانى، سكن الشام، رأى عمر بن الخطاب. روى عنه يحيى بن أيوب المصرى، قال أبو أحمد الحاكم: وقد أخرجت أبا عيسى هارون بن يزيد الخراسانى. روى عنه حيوة بن شريح. ولا أدرى أهما اثنان أم واحد."],[3388,"٢١٥٨ - أبو عيسى. روى عنه معاوية بن صالح الحمصى حديثا مرسلا."],[3389,"٢١٥٩ - أبو عيسى. روى عن (ابن مسعود) (١) مرسلا. روى عنه محمد بن عجلان. هو والذى قبله مجهولان.","",{"fn":"في الأصل بياض، والمثبت عن مصادر الترجمة."}],[3390,"باب أبى عمارة"],[3391,"٢١٦٠ - أبو عُمَارة (١)، كوفى. روى عن على بن أبى طالب رضي الله عنه. روى عنه إسماعيل بن عبد الرحمن السدى."],[3392,"٢١٦١ - أبو عمارة بن عبد اللَّه بن عتبة الهذلى. أخو عبيد اللَّه بن عبد اللَّه ابن عتبة بن مسعود. ذكر سفيان بن عيينة أنه كان مضعوفا. روى عن على بن المدينى عن سفيان قال: كنا عند الزهرى فجاء أخ لعبيد اللَّه بن عبد اللَّه يقال له أبو عمارة كان ضعيفا كان يقال له \"يا أبا عمارة احسن علف حمارك فيغضب أو فيرمى\".","",{"fn":"بضم العين أول الحروف وتخفيف الميم. تبصير المنتبه (٣/ ٩٦٩). ٢١٦١ - المقتنى في سرد الكنى (١٠٠/ أ) وقال: قال ابن عيينة: كان ضعيفًا."}],[3393,"باب أبى عامر"],[3394,"٢١٦٢ - أبو عامر الشرعبى. روى عن عبد اللَّه بن عباس. روى عنه عبد اللَّه ابن دينار الحمصى من حديثه ما رواه عثمان بن عبد الرحمن الطرائفى عن اسحاق بن ثعلبة (١) عن عبد اللَّه بن دينار الحمصى عن أبى عامر الشرعبى عن ابن عباس قال: سئل النبى عليه السلام عن الأشربة فقال: \"كل مسكر خمر وكل خمر حرام ولا يكون شراب أحد طرفيه حلال والاخر حرام، ما أسكر كثيره فقليله حرام\" (٢).","",{"fn":"إسحاق بن ثعلبة، ذكره ابن أبى حاتم في الجرح (١/ ١/ ٢١٥) وذكر رواية عثمان بن عبد الرحمن الطرائفى عنه. وقال: سألت أبى عنه فقال: شيخ مجهول منكر الحديث. اهـ.\nالحديث أخرجه أحمد في المسند (١/ ٢٧٤ و٢٧٩ و٣٥٠) عن ابن عباس وفيه \"كل مسكر حرام\" والبخارى \"الأشربة\" باب الباذق، ومن نهى عن كل مسكر من الأشربة (١٠/ ٦٢) وأبو داود \"الأشربة\" باب النهى عن المسكر (٣/ ٣٢٧) والطبرانى في الأوسط كما في مجمع الزوائد (٥/ ٥٣) وقال الهيثمى فيه حفص بن عمر الإمام وهو ضعيف جدا، والبزار أيضًا كما في مجمع الزوائد (٥/ ٥٣) وقال الهيثمى فيه محمد بن عمارة بن صبيح شيخ البزار ولم أعرفه وبقية رجاله رجال الصحيح. كلهم أخرجوه من حديث ابن عباس رضي الله عنهما. ويشهد لهذا الحديث أيضًا حديث عائشة رضي الله عنها بنحو حديث ابن عباس. أخرجه البخارى \"الأشربة\" باب الخمر من العسل (١٠/ ٤١) ومسلم (٣/ ١٥٨٥ و١٥٨٦)، وأبو داود \"الأشربة\" باب النهى عن المسكر (٣/ ٣٢٩) والترمذى \"الأشربة\" باب ما جاء في كل مسكر حرام (٥/ ٦٠٢) ="}],[3395,"٢١٦٣ - أبو عامر الحَجْرى (١). سمع أبا ريحانة: روى عنه الهيثم بن شَفِى (٢) حديثه في أهل مصر."],[3396,"٢١٦٤ - أبو عامر. روى عن ابن عباس.","",{"fn":"الحَجْرى، بفتح الحاء المهملة وسكون الجيم وفى آخرها راء - نسبة إلى حَجْر ذى رعين. انظر الاكمال (٢/ ٣٨٧)، اللباب (١/ ٣٤٣) تبصير المنتبه (٢/ ٤٨٨).\nالهيثم بن شَفِى، بمعجمة وفاء رزن على في الاصح الرعينى، أبو الحصين الحَجْرى، بفتح المهملة وسكون الجيم، مصرى، ثقة، من الثانية، التقريب (٢/ ٣٢٧). ٢١٦٤ - كنى البخارى (ص ٥٧)، الجرح (٢/ ١/ ٤١١)، الميزان (٤/ ٥٤٣) وقال: أبو عامر عن ابن عباس، وعنه إبراهيم بن زياد، وهما مجهولان. وانظر ديوان الضعفاء (ص ٣٦٣)، اللسان (٧/ ٧٠)."}],[3397,"روى عنه إبراهيم بن زياد (١)."],[3398,"٢١٦٥ - أبو عامر. روى عن ابن شهاب أنه سئل عن الرجل يجب عليه الحد فيمرض فقال: يؤخر حتى يصح (٢). روى عنه معاوية بن صالح الحضرمى."],[3399,"٢١٦٦ - أبو عامر الأَلْهَانى (٣)، شامى، روى عن ثوبان، وأبى أمامة روى عنه ارطاة (٤) بن المنذر، ومعاوية بن صالح."],[3400,"٢١٦٧ - أبو عامر الاوصابى (٥). روى عن أبى أمامة. روى عنه محمد بن الوليد الزبيدى.","",{"fn":"إبراهيم بن زياد قال ابن أبى حاتم: سألت أبى عنه فقال: مجهول. انظر الجرح (١/ ١/ ١٠٠) وقال البخارى في التاريخ الكبير (١/ ١/ ٢٨٧) لم يصح إسناده. اهـ. ٢١٦٥ - كنى البخارى (ص ٥٧)، الجرح (٢/ ١/ ٤١١) وقال: سمعت أبى يقول: هو مجهول، الميزان (٤/ ٥٤٣) وقال: هو مجهول، اللسان (٧/ ٧٠).\nأخرجه البخارى في الكنى (ص ٥٧). ٢١٦٦ - كنى البخارى (ص ٥٧)، الثقات (٥/ ٥٧٧)، الجرح (٤/ ٢/ ٤١١) تهذيب الكمال (٣/ ١٦١٩)، التهذيب (١٢/ ١٤٤) وذكره بكنيته وقال: اسمه عبد اللَّه بن عامر تقدم. وكذا قال في التقريب (٢/ ٤٤٣) ولم اظفر به فيمن اسمه عبد اللَّه بن عامر في الكتابين، ولا في تهذيب الكمال. واللَّه أعلم.\nالأَلْهَانى: بفتح الالف وسكون اللام، وفتح الهاء وفى آخرها النون هذه النسبة إلى أَلْهان بن مالك أخى همدان بن مالك. اللباب (١/ ٨٣).\nفي كنى البخارى \"ابن ارطاة\". ٢١٦٧ - كنى البخارى (ص ٥٧)، الجرح (٤/ ٢/ ٤١١) المقتنى في سرد الكنى (٧٨/ ب)، التهذيب (١٢/ ١٤٥) ذكره في الكنى وقال: اسمه لقمان بن عامر. وذكره فيمن اسمه لقمان (٨/ ٤٥٥)، وقال: قال أبو حاتم يكتب حديثه، وذكره ابن حبان في الثقات وقال: قال أبو حاتم الرازى: روايته عن أبى الدراء مرسلة. وقال في التقريب (٢/ ١٣٨) صدوق، من الثالثة./ د. س. فق. وانظر الجرح (٣/ ٢/ ١٨٢). ذكره باسمه \"لقمان\".\nزاد في التهذيب \"ويقال: الوصابى\". والاوصابى، بفتح الالف وسكون الواو ="}],[3401,"باب أبى عمار"],[3402,"٢١٦٨ - أبو عمار، روى عن على كوفى. روى عنه السدّى."],[3403,"٢١٦٩ - أبو عمار الحداد (١) الفارسى، رأى أنس بن مالك، روى عنه نافع بن يزيد."],[3404,"٢١٧٠ - أبو عمار التيمى. روى عن أبيه (٢) عن سفينة مولى النبى عليه السلام. روى عنه عمرو بن حكام القسملى (٣). من حديث عبيد اللَّه بن جرير ابن (. . . .) (٤) عن عمرو بن حكام عن أبى عمار التيمى عن أبيه قال: صحبت سفينه مولى النبى عليه السلام في سفر فعرض لنا الأسد وذكر الخبر (٥).","",{"fn":"الحداد: بفتح الحاء المهملة وبالالف بين الدالين المهملتين أو لاهما مشدده - نسبة إلى بيع الحديد وشرائه. اللباب (١/ ٣٤٦). ٢١٧٠ - المقتنى في سرد الكنى (١٠٠/ أ).\nلم أقف عليه.\nعمرو بن حكام القسملى والقساملة قبيلة من الازد. قال أحمد بن حنبل كان يروى عن شعبة نحوا من أربعة الآف حديث وترك حديثه. وقال أبو زرعة ليس بالقوى. انظر الجرح (٣/ ١/ ٢٧٧ - ٢٢٨)، اللسان (٤/ ٣٦٠)، اللباب (٣/ ٣٧).\nفي الأصل بياض بمقدار كلمة.\nالحديث ذكره الهيثمى في مجمع الزوائد (٩/ ٣٦٦) عن سفينة قال: كنت ="}],[3405,"٢١٧١ - أبو عمار صاحب المزاود (١). قال: ركبت سفينة فيها أنس بن مالك فذكر حديثا في الصلاة (١).","",{"fn":"في الجرح \"المراوزة\". والمزاود: جمع مزود كالاوعية في وعاء او تجمع أيضًا أزودة جمع زاد على غير القياس. انظر النهاية (٢/ ٣١٧)."}],[3406,"٢١٧٢ - أبو عمار، شامى، سمع أبا عبيدة بن الجراح، روى عنه أزهر بن سعيد الحرازى (٢) يعد في الشاميين."],[3407,"٢١٧٣ - أبو عمار مولى (لقوم) (٣) بالمدينة. سمع عبد اللَّه بن هدّاج (٤) روى عنه إبراهيم بن المنذر الحزامى.","",{"fn":"الخبر أخرجه البخارى في الكنى \"قال: ركبت سفينة فيها أنس بن مالك فصلى وانصرف ذات الشمال ولم يركع في الموضع الذى صلى فيه وما أحب أن لى برؤية أنس مفروح أرجو أن أكون من التابعين. ونحو هذا ذكره ابن أبى حاتم أيضًا. انظر مصادر الترجمة. ولأنس أيضًا حديث آخر في الصلاة في السفينة أخرجه ابن أبى شيبه في المصنف \"الصلوات\" - باب من قال: صل في السفينة جالسا (٢/ ٢٦٦) من طريق ابن سيرين قال: خرجت مع أنس إلى بنى سيرين في سفينه عظيمة قال: فأمنا فصلى بنا فيها جلوسا ركعتين ثم صلى بنا ركعتين أخراوين. وبنحو هذا أخرجه الطبرانى في الكبير أيضًا. وقال الهيثمى رجاله ثقات. انظر مجمع الزوائد (٢/ ١٦٣). ٢١٧٢ - المقتنى في سرد الكنى (١٠٠/ أ).\nازهر بن سعيد الحَرَازى، بمهملة وراء خفيفة وبعد الالف زاى، حمصى صدوق، ويقال: هو ازهر بن عبد اللَّه، من الخامسة (ت: ١٠٨) وقيل سنة (١٢٩). التقريب (١/ ٥١). ٢١٧٣ - كنى البخارى (ص ٥٩)، الجرح (٤/ ٢/ ٤١٣).\nفي الأصل \"القوم\" وفى مصادر الترجمة \"لقوم\" بلا همزة كما اثبته وهو الصواب. واللَّه أعلم.\nعبد اللَّه بن هداج -بدال مهملة- الحنفى، من بنى عدى بن حنيفة روى عن أبيه روى عنه أبو عمار هاشم بن غطفان بن عمار بن مهران المدينى الجرح (٢/ ٢/ ١٩٥)، الاكمال (٧/ ٤١٦)."}],[3408,"٢١٧٤ - أبو عمار الاسدى، روى عن ابن مسعود، روى عنه عثمان بن زفر (١).","",{"fn":"في اللسان \"زافر\"."}],[3409,"باب أبى عمران"],[3410,"٢١٧٥ - أبو عمران الأَلهانى، روى عن أبى هريرة، وثوبان وأبى امامة، روى عنه معاوية بن صالح، وارطاة بن المنذر هكذا ذكره أبو أحمد الحاكم وذكره ابن أبى حاتم في باب أبى عامر (١)."],[3411,"٢١٧٦ - أبو عمران الفلسطينى. عن يعلى بن شداد ومجاهد. روى عنه معاوية بن صالح."],[3412,"٢١٧٧ - أبو عمران، عن الجعد، اراه أبا عثمان (٢). روى عنه بكر بن خنيس من حديث طالوت بن عبّاد (٣) عن بكر بن خنيس عن أبى عمران عن الجعد عن أنس بن مالك فقال: ما صلى بنا رسول اللَّه صلاة المكتوبة إلا أقبل بوجهة علينا فقال: \"اللهم إنى أعوذ بك من عمل يخزى وأعوذ بك من صاحب يردى وأعوذ بك من أمل يلهى وأعوذ بك من فقر ينسى، وأعوذ بك من غنى يطغى\" (١).","",{"fn":"انظر الجرح (٢/ ١/ ٤١١) وقد تقدمت ترجمة أبى عامر الالهانى في (٢١٦٦) وقد ذكر ابن أبى حاتم في كتاب بيان خطأ محمد بن إسماعيل البخارى في تاريخه (ص ١٥٩) أبا عمران الألهانى -في الأصل الحلابى مُحرفه- عن أبى هريرة وثوبان وأبى امامة روى عنه معاوية بن صالح وارطاه قال: وإنما هو أبو عامر الألهانى روى عن ثوبان يروى عنه ارطاه وأبو عمران روى عن أبى هريرة روى عنه معاوية بن صالح ولم يرو عن أبى امامة قال: سمعت أبى يقول: ذلك. اهـ. ٢١٧٦ - كنى البخارى (ص ٦٠)، الجرح (٤/ ٢/ ٤١٥). الثقات (٧/ ٦٥٩)، المقتنى في سرد الكنى (١٠٥/ ب). ٢١٧٧ - المقتنى في سرد الكنى (١٠٥/ ب) وقال: أبو عمران، عن الجعد وعنه بكر ابن خنيس.\nالجعد بن دينار اليشكرى، أبو عثمان الصيرفى، بصرى، ثقة، من الرابعة. التقريب (١/ ١٢٨)، الجرح (١/ ١/ ٥٢٨).\nطالوت بن عبَّاد الصيرفى، قال ابن حجر: شيخ معمر ليس به بأس، وقال أبو ="}],[3413,"قال أبو عمر: أبو عمران هذا والجعد مجهولان. والحديث لا يعرف له أصل في الإسناد.","",{"fn":"الحديث أخرجه ابن السنى في عمل اليوم والليلة (ص ٥٤) من طريق طالوت ابن عباد به بمثله لكن قال في سنده \"عن أبى الجعد عن أنس\"، وإنما هو الجعد عن أنس. وأخرجه أبو يعلى. كما في المطالب العالية (٣/ ٢٤٨) من طريق الجعد قال: صلى أنس بن مالك في مسجد بنى رفاعة هاهنا فأمر رجلا من أصحابه أن يؤذن فصلى بهم الصبح فلما أن فرغ من صلاته أقبل على القوم فقال: كان رسول اللَّه -صلى الله عليه وآله وسلم- إذا صلى بأصحابه أقبل على القوم فقال: \"اللهم إنى أعوذ بك من عمل يخزينى، اللهم إنى أعوذ بك من غنى يطغينى. اللهم إنى أعوذ بك من صاحب يؤذينى. . إلخ\" وذكره الهيثمى في مجمع الزوائد (١٠/ ١١٠) من حديث أنس به وقال الهيثمى: رواه البزار وفيه بكر بن خنيس وهو متروك، وقد وثق، ورواه أبو يعلى وفيه عقبة بن عبد اللَّه الاصم وهو ضعيف جدا. وأخرج البخارى \"الجهاد\" باب ما يتعوذ من الجبن (٦/ ٣٦) من حديث سعد قال: إن رسول اللَّه -صلى الله عليه وآله وسلم- كان يتعوذ منهن دبر كل صلاة \"اللهم إنى أعوذ بك من الجبن، وأعوذ بك من أن أرد إلى أرذل العمر، وأعوذ بك من فتنة الدنيا، وأعوذ بك من عذاب القبر\" وعند البخارى أيضًا في نفس الباب السابق (٦/ ٣٦) حديث أنس قال: كان النبى -صلى الله عليه وآله وسلم- يقول: \"اللهم إنى أعوذ بك من العجز والكسل، والجبن والهرم، وأعوذ بك من فتنة المحيا والممات، وأعوذ بك من عذاب القبر."}],[3414,"٢١٧٨ - أبو عمران الأنصارى، روى عن النبى عليه السلام حديثا مرسلا، روى عنه ثعلبة بن مسلم الخثعمى (١). سئل عنه أبو زرعة فقال: هو من التابعين لا أعرف اسمه.","",{"fn":"مستور من الخامسة./ د. فق. التقريب (١/ ١١٩)."}],[3415,"باب أبى عقيل"],[3416,"٢١٧٩ - أبو عقيل عن أبى صالح، عن عثمان بن عفان، روى عنه أبو معن (١). غير منسوب أيضًا ولا مسمى. قال البخارى: أظن أبا صالح هذا مولى عثمان (٢)."],[3417,"٢١٨٠ - أبو عقيل الأنصارى، مولى بنى زريق، سمع عائشة، روى عنه أبو بكر بن عثمان، يعد في أهل المدينة."],[3418,"٢١٨١ - أبو عقيل، روى عنه ابنه رضى بن أبى عقيل (٣)، لم يذكر بغير هذا.","",{"fn":"أبو معن هو المتقدم في (١٨٤٦).\nأبو صالح مولى عثمان هو المتقدم في (١٩٥٦). ٢١٨٠ - الجرح (٤/ ٢/ ٤١٦)، المقتنى في سرد الكنى (٩٦/ أ). ٢١٨١ - كنى البخارى (ص ٦٢)، الجرح (٤/ ٢/ ٤١٦).\nذكره ابن أبى حاتم في الجرح (١/ ٢/ ٥٢٣) وذكر روايته عن أبيه ورواية محمد بن فضل عنه ولم يذكر فيه شيئا. اهـ."}],[3419,"باب أبى عون"],[3420,"٢١٨٢ - أبو عون بن أبى حازم مدنى، روى عن المسور بن مخرمة، وعبد اللَّه بن الزبير، روى عنه عبد اللَّه بن جعفر المخرمى (١). سئل أبو زرعة الرازى عنه فقال: لا أعرفه وهو مدنى (٢). قال أبو محمد بن أبى حاتم: إذا يعرفه (٣) فقد جعله مجهولا (٤). قال أبو عمر: كل من لم يرو عنه إلا رجل واحد لا يعرف إلا بذلك فهو مجهول عندهم لا تقوم به حجة (٥). وأكثر هؤلاء الذين لا يعرفون إلا بكناهم كذلك.","",{"fn":"عبد اللَّه بن جعفر بن عبد الرحمن بن المسور بن مخرمة أبو محمد المدنى المَخْرَمى، بسكون المعجمة، وفتح الراء الخفيفة، ليس به بأس، من الثامنة (ت: ١٧٠). اخت. م. عـ. التقريب (١/ ٤٠٦) والمخرمى، نسبة إلى المسور بن مخرمة بن نوفل. اللباب (٣/ ١٧٨).\nو(٤) انظر الجرح (٤/ ٢/ ٤١٤).\nزاد في الجرح لفظ \"مثله\".\nقال الحافظ ابن الصلاح في مقدمة علوم الحديث (ص ٣٥٤) بلغنى عن أبى عمر بن عبد البر الاندلسى وجادة قال: كل من لم يرو عنه إلا رجل واحد فهو عندهم مجهول إلا أن يكون رجلا مشهورا في غير حمل العلم كاشتهار مالك بن دينار بالزهد وعمرو بن معدى كرب بالنجدة\" أهـ."}],[3421,"٢١٨٣ - أبو عون بن أبى عبد اللَّه الأنصارى. شامى (١). روى عن أبى هريرة وابن عمر وأبى إدريس الخولانى. وروى عن عثمان مرسلا. روى عنه ثور بن يزيد وأبو بكر أبى مريم ومحمد بن الوليد الزبيدى وقد روى معاوية بن صالح عن محمد بن أيوب عنه."],[3422,"٢١٨٤ - أبو عون بن أبى رُكَبَة، روى عن غيلان بن جرير. عن أنس، قال ابن أبى حاتم: سألت عنه أبى فقال: هو مجهول. والحديث الذى رواه منكر."],[3423,"٢١٨٥ - أبو عون بن أبى عبيد، حديثه في قدوم عمر الشام (٢). روى عنه ابن الهادى (٣).","",{"fn":"زاد في كنى البخارى والجرح \"الاعور\". ٢١٨٤ - الجرح (٤/ ٢/ ٤١٤) وفيه قال: سألت أبى عنه. . الخ. الميزان (٤/ ٥٦٠) وقال: مجهول، اللسان (٧/ ٨١) وقال أيضًا: مجهول. ٢١٨٥ - كنى البخارى (ص ٦٢)، الثقات (٥/ ٥٧١). المقتنى في سرد الكنى (١٠٧/ ب).\nومثله في كنى البخارى والثقات.\nهكذا في الأصل \"الهادى\" وفى مصادر الترجمة \"الهاد\" بلا ياء. وفى التقريب (٢/ ٣٦٧) يزيد بن عبد اللَّه بن أسامة بن الهاد الليثى."}],[3424,"٢١٨٦ - أبو عون الهجيمى، سمع قبيصة بن مُخَارق الهلالى (١).","",{"fn":"قبيصة بن المخارق، بضم الميم وتخفيف المعجمة، ابن عبد اللَّه الهلالى، صحابى، سكن البصرة. التقريب (٢/ ١٢٣)."}],[3425,"باب أبى عاصم"],[3426,"٢١٨٧ - أبو عاصم السدوسى - كوفى، روى عن ضرار العبدى، روى عنه عبد الواحد بن زياد العدوى من حديث محمد بن الحسن الاسدى (١)، عن عبد الواحد، عن أبى عاصم، عن ضرار قال: \"قام عمار بين الصفين يوم الجمل فقال: يا صحاب رسول اللَّه نظر كل رجل منكم لحليلته فأغلق بابه دونها وارخى ستره عليها وأخرجتم حليلة رسول اللَّه -صلى الله عليه وآله وسلم- بين الكتائب\" (٢)."],[3427,"٢١٨٨ - أبو عاصم التمار، روى عن سعيد بن جبير، روى عنه الأزهر بن راشد الكاهلى (٣)."],[3428,"٢١٨٩ - أبو عاصم الضرير، البصرى، سمع موسى بن عمران الليثى (٤)، روى عنه محمد بن إسماعيل البخارى.","",{"fn":"محمد بن الحسن بن الزبير الاسدى، الكوفى، لقبه التل بفتح المثناة وتشديد اللام، صدوق، فيه لين، من التاسعة (ت: ٢٠٠)./ خ. س. ق. التقريب (٢/ ١٥٤).\nلم أقف عليه. ٢١٨٨ - كنى البخارى (ص ٦٠)، كنى مسلم (ص ٧٣١)، الجرح (٤/ ٢/ ٤١٤) الثقات (٧/ ٦٦٢)، كنى ابن منده (١٩٦/ ب).\nأزهر راشد الكاهلى، ضعيف، من الثامنة. التقريب (١/ ٥١). ٢١٨٩ - اللسان (٧/ ٧٠) وقال: ذكره أبو أحمد الحاكم في من لا يعرف اسمه. وذكره ابن حجر أيضًا في اللسان (٦/ ١٢٩) في ترجمة شيخه موسى بن عمران الليثى.\nانظر ترجمته في اللسان (٦/ ١٢٩)."}],[3429,"٢١٩٠ - أبو عاصم الغنوى. روى عن أبى الطفيل عامر بن واثلة. روى عنه حماد بن سلمه. قال ابن أبى حاتم: سألت أبى عن أبى عاصم الغنوى فقال: لا أعلم أحدا روى عنه غير حماد بن سلمة ولا أعرفه بأكثر من هذا ولا أعرف اسمه (١). ذكر اسحاق بن منصور الكوسج (٢) عن يحيى بن معين أنه قال: أبو عاصم الغنوى ثقة (٣).","",{"fn":"انظر الجرح (٤/ ٢/ ٤١٤).\nالكوسج: أولها وسكون الواو وفتح السين المهملة وفى آخرها جيم عرف بهذا أبو يعقوب إسحاقى بن منصور بن بهرام الكوسج المروزى، اللباب (٣/ ١١٧).\nانظر الجرح (٤/ ٢/ ٤١٤)."}],[3430,"باب أبى عصام"],[3431,"٢١٩١ - أبو عصام، سمع أنس بن مالك، روى عنه هشام الدستوائى وعبد الوارث بن سعيد، وقد روى عن شعبة عنه. إن كان ذلك محفوظا."],[3432,"٢١٩٢ - أبو عصام الازدى، بصرى، روى عن كعب بن سور، روى عنه قتادة."],[3433,"٢١٩٣ - أبو عصام، روى عن الحسن، روى عنه السرى بن يحيى."],[3434,"باب أبى عصمة"],[3435,"٢١٩٤ - أبو عصمة، روى عن رجل قال: رأيت عليا رضي الله عنه، روى عنه يحيى بن واضح (١). قال أبو أحمد الحاكم: وخليقا أن يكون نوح بن أبى مريم (٢) واللَّه أعلم."],[3436,"٢١٩٥ - أبو عصمة. روى عن سفيان الثورى. روى عنه أحمد بن أبى الحوارى الزاهد.","",{"fn":"يحيى بن واضح: هو أبو تميلة، مشهور بكنيته. انظر الترجمة (٥٠٠).\nنوح بن أبى مريم هو أبو عصمة المتقدم في (٩٩٢). ٢١٩٥ - لم أقف عليه عند غير المؤلف."}],[3437,"باب أبى العلاء"],[3438,"٢١٩٦ - أبو العلاء قال: رأيت عليا يأتزر فوق السرة (١)، مدنى روى عنه محمد بن أبى يحيى الاسلمى."],[3439,"٢١٩٧ - أبو العلاء، روى عن امرأة، عن ابن سيرين، روى عنه سعيد بن عبد الرحمن."],[3440,"٢١٩٨ - أبو العلاء الاودى، روى عن حميد بن عبد الرحمن الحميرى (٢)، روى عنه يزيد أبو خالد الدالانى."],[3441,"٢١٩٩ - أبو العلاء بن أبى اللجلاج. وقيل: القعقاع بن اللجلاج وقيل: حصين بن اللجلاج. روى عن أبى هريرة. روى عنه صفوان بن أبى يزيد (٣) اختلف فيه ولا تعرف صحته.","",{"fn":"الخبر. ذكره أيضا ابن أبى حاتم هنا. وأيضا أخرجه الذهبى في المقتنى في سرد الكنى. انظر مصادر الترجمة. ٢١٩٧ - كنى البخارى (ص ٦٠)، الجرح (٤/ ٢/ ٤١٥)، المقتنى في سرد الكنى (٩٧/ أ). ٢١٩٨ - لم أقف له على ترجمة عند غير المؤلف.\nبصرى، ثقة، فقيه، من الثالثة. التقريب (١/ ٢٠٣). ٢١٩٩ - المقتنى في سرد الكنى (٩٧/ أ) وقال: أبو العلاء بن أبى اللجلاج سمع أبا هريرة. ويقال: القعقاع بن اللجلاج. وقيل: حصين بن اللجلاج لا يهتدى إلى صحته. عنه صفوان بن أبى يزيد. اهـ.\nصفوان بن أبى يزيد. ويقال: ابن سليم المدنى، مقبول، من الرابعة. التقريب (١/ ٣٦٩)."}],[3442,"٢٢٠٠ - أبو العلاء. قال: خرجت معتمرا فكسرت فبعثت إلى ابن عمر وابن عباس فقالا: ليس له وقت كوقت الحج."],[3443,"٢٢٠١ - أبو العلاء. سمع الحسن. روى عنه ابن عيينة."],[3444,"٢٢٠٢ - أبو العلاء، عن عامر الشعبى."],[3445,"باب أبى العالية"],[3446,"٢٢٠٣ - أبو العالية الشامى عن عمر بن الخطاب. روى عنه عبد اللَّه بن مسلم بن هرمز (١)."],[3447,"٢٢٠٤ - أبو العالية القيسى عن أبى المليح (٢) روى عنه عقبة بن أبى الصهباء الباهلى (٣) -يعد في البصريين."],[3448,"٢٢٠٥ - أبو العالية (المكى) (٤)! عن سعيد بن جبير، روى عنه يحيى بن كثير العنبرى (٥).","",{"fn":"مكى، ضعيف، من السادسة. التقريب (١/ ٤٥٠). ٢٢٠٤ - كنى مسلم (ص ٧٤٨)، كنى بن منده (١٩٧/ ب).\nزاد مسلم \"الهذلى، وتقد تقدم أبو المليح الهذلى في (٨١٥) واسمه عامر ابن أسامة بن عمير.\nعقبة بن أبى الصهباء أبو خريم، بصرى، قال: أحمد بن حنبل: شيخ صالح، وقال: ابن معين: ثقة. وقال أبو حاتم: محله الصدق. انظر الجرح (٣/ ١/ ٣١٢). ٢٢٠٥ - كنى مسلم (ص ٧٤٨)، كنى ابن منده (١٩٧/ ب).\nغير واضحة في الأصل والمثبت عن الكنى لمسلم.\nيحيى بن كثير العنبرى، بصرى، يكنى أبا غسان، ثقة، من التاسعة (ت: ٢٠٦)، التقريب (٢/ ٣٥٦). والعنبرى، بفتح العين وسكون النون وفتح الباء الموحدة وفى آخرها راء - هذه النسبة إلى العنبر بن عمرو بن تميم. ويقال لهم: بلعنبر أيضا. اهـ. اللباب (٢/ ٣٦٠)."}],[3449,"باب أبى العوام"],[3450,"٢٢٠٦ - أبو العوام. شيخ روى عنه ابن عجلان انه سأل ابن عمر عن الرجل يعزب (١) في ابله وليس معه ماء أياتى أهله؟ فقال: \"اما ابن عمر فلم يكن يفعله وأما أنت فاتق اللَّه فإذا وجدت الماء فاغتسل\" (٢)."],[3451,"٢٢٠٧ - أبو العوام سادن (٣) بيت المقدس. روى عن عمر بن الخطاب ومعاذ بن جبل كعب الاحبار. روى عنه روح بن (عائذ) (١) قال أحمد بن حنبل: أبو العوام سادن بيت المقدس لا أدرى ما اسمه؟ قال أبو عمر: من حديثه عند حماد بن سلمة عن على بن زيد عن أبى المليح (٢) عن روح بن عائذ عن أبى العوام عن معاذ بن جبل عن النبى عليه السلام \"من قال لا اله إلا اللَّه دخل الجنة\" (٣).","",{"fn":"يعزب: أى يبعد في المرعى. انظر النهاية (٣/ ٢٢٧) وفى القاموس (١/ ١٠٣) مادة \"عزب\" العَزَب: محركة من لا أهل له كالمِعزابة والعزيب ولا تقل أعزب أو قليل ج أعزاب وهى عزَبَه وعَزَب والاسم العُزْبة والعُزُوبه مضمومتين والفعل كَنَصَر، وتَعَزَّب ترك النكاح، والعُزُوب، الغَيْبة يعْزُبُ وَيعْزِبُ والذهاب والمِعْزَابة: من طالت عزوبته، من يعزُبُ بماشيته كالمِعْزَاب والعَزيب، الرجل يعزب عن أهله وماله. اهـ.\nالأثر: أخرجه ابن أبى شيبة (١/ ٩٧) من طريق محمد بن عجلان عن أبى العوام قال: كنت جالسا عند ابن عمر فجاء أعرابى فقال له: إنَّا نَعْزُبُ في الماشية عن الماء فيحتاج احدنا إلى أن يصيب أهله قال: اما ابن عمر فلم يكن ليفعله وأما أنت فإذا وجدت الماء فاغتسل\". ومن طريق محمد بن عجلان عن أبى العوام به أخرجه عبد الرزاق (١/ ٢٤) والدولابى في الكنى (٢/ ٤٧). ٢٢٠٧ - كنى البخارى (ص ٦٠)، كنى مسلم (ص ٧٥٠)، كنى ابن منده (١٩٧/ ب) الجرح (٤/ ٢/ ٤١٥) وقال: نا على بن الحسن الهسنجانى قال: سمعت أبا عبد اللَّه -يعنى أحمد بن حنبل قال: أبو العوام سادن بيت المقدس لا أدرى ما اسمه. الثقات (٥/ ٥٦٤) وقال: روى عنه أهل الشام ومصر. تعجيل المنفعة (ص ٣٣٣).\nقال أبو عبيد في غريب الحديث (١/ ٢٣٧، ٢٨٨): السدانه في كلام =\nهكذا هنا \"روح بن عائذ\" وكذا في مصادر الترجمة. وفى التاريخ الكبير (٢/ ١/ ٣٠٨) \"روح بن عابد عن أبى العوام، روى عن على بن زيد عن أبى المليح. اهـ. وفى الجرح (١/ ٢/ ٤٩٧) أيضا روح بن عابد شامى روى عن أبى العوام، روى عنه على بن زيد وأبو المليح. وقال ابن حجر في تعجيل المنفعة (ص ٩١): روح بن عابد شامى، روى عن أبى العوام عن معاذ، وعنه أبو المليح بن أسامة وعلى بن زيد بن جدعان، فيه جهالة. وقال: كذا ذكر الحسينى. ثم قال ابن حجر: والذى في المسند رواية على بن زيد عن أبى المليح عن روح، فعلى يروى عن أبى المليح لا عن روح. اهـ. وستأتى هذه الرواية في تخريج الحديث وقد ذكر ابن ماكولا (٦/ ١ - ٢) عابد وضبطه بالباء المعجمة بواحدة ودال مهملة وقال: روح بن عابد سادن بيت المقدس، يروى عن أبى العوام روى عنه أبو المليح. اهـ.\nهو عامر بن اسامه، اشتهر بكنيته.\nالحديث أخرجه أحمد المسند (٥/ ٢٣٤) من طريقين عن حماد بن سلمة عن على بن زيد عن أبى المليح عن روح بن عابد عن أبى العوام عن معاذ ابن جبل قال: كنت ردف النبى -صلى الله عليه وآله وسلم- على جمل أحمر فقال: يا معاذ قلت: لبيك قال: هل تدرى ما حق اللَّه على العباد. قال: فقلت: اللَّه ورسوله اعلم قالها ثلاثا فقلت ذلك ثلاثا قال: حقه عز وجل أن يعبدوه ولا يشركوا به شيئا ثم قال: هل تدرى ما حق العباد على اللَّه إذا فعلوا ذلك؟ فقلت: اللَّه ورسوله اعلم. قالها ثلاثا وقلت ذلك ثلاثا. فقال: حقهم عليه إذا هم فعلوا ذلك أن ="}],[3452,". . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . ."],[3453,"٢٢٠٨ - أبو العوام الدوسى. روى عن أبى ذر وحسن أو حسين (١) بن على خبرا. روى عنه نوح بن قيس (٢)."],[3454,"٢٢٠٩ - أبو العوام قال: كتب عمر بن الخطاب إلى أبى موسى الاشعرى روى عنه معمر.","",{"fn":"في كنى البخارى \"حسين\" وفى الجرح \"حسن\".\nنوح بن قيس بن رباح الازدى، أبو روح البصرى، أخو خالد صدوق، رمى بالتشيع، من الثامنة (ت: ١٨٣ أو ١٨٤) التقريب (٢/ ٣٠٨)، التهذيب (١٠/ ٤٨٥). ٢٢٠٩ - المقتنى في سرد الكنى (١٠٧/ أ) وقال: أبو العوام قال: كتب عمر إلى أبى موسى وعنه معمر. قلت: وكتاب عمر إلى أبى موسى. أخرجه البيهقى في المعرفة من طريق أبى عبد اللَّه الحافظ ثنا أبو العباس محمد بن يعقوب ثنا محمد بن اسحاق الصنعانى، ثنا محمد بن عبد اللَّه بن كناسه ثنا جعفر بن برقان عن معمر البصرى عن أبى العوام البصرى قال: كتب عمر. فذكره وسيأتى لفظه إن شاء اللَّه في آخر التخريج. انظر نصب الراية (٤/ ٨٢) وقال الألبانى في ارواء الغليل (٨/ ٢٤٢): اسناده إلى أبى العوام صحيح وأما أبو العوام البصرى ففى الرواة ثلاثة كلهم يكنى بهذه الكنية وكلهم بصريون وهم، فائد بن كيسان. وعبد العزيز بن الربيع الباهلى. وعمران ابن داور القطان. ولم يتعين عندى ايهم المراد هنا وثلاثتهم من اتباع التابعين، كلهم ثقات إلا الأول فلم يوثقة إلا ابن حبان ولم يدكر في ترجمة أحد منهم أنه روى عنه معمر. واللَّه أعلم. وعلى كل حال فهذه الطريق معضلة. اهـ. والاثر أخرجه أيضا الدارقطنى في الاقضية (٤/ ٢٠٦)، والجاحظ في البيان والتبيين (٢/ ٤٨)، وما بعدها من طريق عبيد اللَّه بن أبى حميد عن أبى ="}],[3455,"٢٢١٠ - أبو العوام عن عبادة بن الصامت. روى عنه زياد بن أبى سودة قال أبو أحمد الحاكم: وخليقا أن يكون هذا هو الذى روى عن معاذ بن جبل (١).","",{"fn":"لعله يريد بالذى روى عن معاذن جبل أبا العوام سادن بيت المقدس المتقدم في (٢٢٠٧). واللَّه أعلم."}],[3456,"باب أبى عروة"],[3457,"٢٢١١ - أبو عروة، عن زياد بن (أبى) (١) عمار، عن أنس بن مالك، روى عنه المفضل بن فضالة المصرى."],[3458,"٢٢١٢ - أبو عروة، سمع عمرو بن شعيب، روى عنه خليفة (٢) بن غالب (٣).","",{"fn":"الحق في هامش الأصل، كتب بعده كلمة \"صح\". ٢٢١٢ - كنى البخارى (ص ٦٣). المقتنى في سرد الكنى (٩٣/ ب).\nفي كنى البخارى \"خلف\".\nخليفة بن غالب الليثى، أبو غالب البصرى، صدوق، من السابعة. التقريب (١/ ٢٢٧)."}],[3459,"باب أبى عتبة"],[3460,"٢٢١٣ - أبو عتبة الكندى الحمصى. سمع أبا أمامة الباهلى. روى عنه معاوية بن صالح. وروى معاوية بن صالح عن أبى عتبة أن عمر بن عبد العزيز قال: ادرأوا الحدود ما استطعتم في كل شبهة فإن الوالى إذا أخطأ في العفو خير من أن يخطئ في العقوبة (١).","",{"fn":"الأثر أخرجه ابن الجوزى في سيرة عمر بن عبد العزيز (ص ٨٤) من طريق الليث بن سعد عن معاوية بن صالح عن أبى عقبة -هكذا في سيرة عمر \"عقبة\" وهو تصحيف وإنما هو \"عتبة\" واللَّه أعلم- أن عمر بن عبد العزيز قال: \"ادرؤا الحدود ما استطعتم. . الخ\". وأخرجه أيضا ابن عساكر في تاريخ دمشق (١٩/ ١٧١/ ٢) من طريق محمد بن أحمد بن ثابت نا أبو مسلم إبراهيم بن عبد الصمد نا محمد بن أبى بكر المقدمى نا محمد بن على الشامى نا أبو عمران الجونى قال: قال عمر بن عبد العزيز فذكره. وفيه قصة مطولة. قال الشيخ الألبانى في ارواء الغليل (٧/ ٣٤٤): ضعيف. وأخرجه من هذا الوجه أيضا أبو سعد بن السمعانى في \"الذيل\" كما في المقاصد الحسنة (ص ٣٠) وقال: قال شيخنا: وفى سنده من لا يعرف. اهـ. وأخرجه أيضا ابن أبى شيبة (٩/ ٥٦٦) من طريق هشيم عن منصور عن الحارث عن إبراهيم قال: قال عمر بن الخطاب لئن أعطل الحدود بالشبهات أحب إلى من أن اقيمها بالشبهات. ولعائشة رضي الله عنها حديث مرفوع ="}],[3461,"قال أبو أحمد الحاكم (وخليقا ان يكون) (١) هذا والذى تقدم واحدا."],[3462,"٢٢١٤ - (أبو عتبة مولى مروان رأى عبد اللَّه بن مُغَفّل روى عنه عبد اللَّه بن الوليد) (٢)، (٣)."],[3463,"٢٢١٥ - أبو عتبة. روى عن عائشة روى عنه مسعر بن كدام قال أبو حاتم: هو مجهول لا يعرف روى عنه مسعر عن رجل عن عائشة.","",{"fn":"في الأصل غير واضح ولعل الصواب ما اثبته واللَّه أعلم. ٢٢١٤ - كنى البخارى (ص ٥٨)، الجرح (٤/ ٢/ ٤١٢)، تاريخ ابن معين (٢/ ٧١٤) كنى الدولابى (٢/ ٢٦)، المقتنى في سرد الكنى (٩٠/ ب).\nفي كنى البخارى زيادة \"بن معقل\" وفى الجرح \"عبد اللَّه بن الوليد بن عبد اللَّه بن معقل\" وفى التقريب (١/ ٤٥٩) عبد اللَّه بن الوليد بن مغفل المزنى، الكوفى، ويقال: له: العجلى، ثقة، من السابعة./ ت. س. اهـ.\nالحقت هذه الترجمة بكاملها في الهامش كتب عندها \"صح أصل\". ٢٢١٥ - الجرح (٤/ ٢/ ٤١٢) وقال: سمعت أبى يقول: لا يدرى من هو ولا يعرف. تهذيب الكمال (٣/ ١٦٢٥)، الميزان (٤/ ٥٤٩) وقال: شيخ لمسعر له عن عائشة أو عن رجل عنها فيه جهالة. اللسان (٧/ ٤٧٣) وقال: مجهول. ="}],[3464,"٢٢١٦ - أبو عتبة عن سعيد بن جبير، روى عنه (ادريس الاودى) (١).","",{"fn":"غير واضح في الأصل \"والمثبت عن مصادر الترجمة\" وادريس الاودى: هناك أثنان يسمى كل منهما ادريس الاودى وكلاهما من طبقة واحدة فالأول ادريس ابن صبيح الاودى، مجهول من السابعة، ويقال هو ابن يزيد./ ق. والاخر ادريس بن يزيد بن عبد الرحمن الاودى، ثقة، من السابعة./ ع. انظر التقريب (١/ ٥٠)، التهذيب (١/ ١٩٥) والجرح (١/ ١/ ٢٦٣ - ٢٦٤)، وتهذيب الكمال (١/ ٧٣)."}],[3465,"باب أبى علقمة"],[3466,"٢٢١٧ - أبو علقمة الهاشمى، مولى بنى هاشم وقد قيل: مولى ابن عباس وقيل: حليف بنى هاشم. وقيل: الأنصارى روى عن أبى هريرة، روى عنه يعلى بن عطاء، ومحمد بن الحارث بن سفيان (١)، ويونس بن خباب، ويعقوب بن عطاء ابن أبى رباح."],[3467,"٢٢١٨ - أبو علقمة عن عائشة روى عنه (مسعر بن كدام) (٢)."],[3468,"٢٢١٩ - (أبو علقمة، عن سعيد بن المسيب أنه سأله، روى عنه) (٣) شعبة."],[3469,"٢٢٢٠ - أبو علقمة، مولى ابن عباس. روى عن يسار بن نمير (٤). روى عنه أيوب بن حصين (١).","",{"fn":"مكى، مقبول، من السادسة. التقريب (٢/ ١٥٢). ٢٢١٨ - كنى البخارى (ص ٥٦). المقتنى في سرد الكنى (٩٦/ أ).\nالحق في هامش الأصل، كتب بعده \"صح أصل\". ٢٢١٩ - كنى البخارى (ص ٥٩) وقال: \"أبو علقمة سألت سعيد بن المسيب روى عنه شعبة\"، المقتنى في سرد الكنى (٩٦/ أ).\nالحق في هامش الأصل، وكتب بعده \"صح أصل\". ٢٢٢٠ - كنى مسلم (ص ٧٥٨)، كنى ابن منده (٩٨/ أ)، المقتنى في سرد الكنى (٩٦/ أ).\nيسار بن نمير، ذكره ابن حجر في التهذيب (١١/ ٣٧٦) فقال: يسار ="}],[3470,"٢٢٢١ - أبو علقمة. روى عنه عبد الرحمن بن زياد المعافرى ضعفه يحيى ابن معين وقال: ليس بشئ.","",{"fn":"أيوب بن حصين. ذكره ابن أبى حاتم فيمن اسمه محمد فقال: محمد بن حصين التميمى، وقال بعضهم: أيوب بن حصين، ومحمد بن حصين أصح، روى عن أبى علقمة مولى ابن عباس. . الخ ولم يذكر فيه شيئا. انظر الجرح (٣/ ٢/ ٢٣٥) وذكره ابن حجر. في التهذيب (٩/ ١٢٢) أيضا في المحمدين فقال: محمد بن الحصين وذكر روايته عن أبى علقمة مولى ابن عباس، وقال في التقريب (٢/ ١٥٥) محمد بن الحصين التميمى وسماه بعضهم أيوب كنية أبيه أبو أيوب، مجهول، من السادسة. اهـ. ٢٢٢١ - المقتنى في سرد الكنى (٩٦/ أ) وقال: أبو علقمة شيخ ضعفه ابن معين الميزان (٤/ ٥٥٤) وقال: قال ابن معين: ليس بشئ، اللسان (٧/ ٨٢)."}],[3471,"باب أبى عائشة"],[3472,"٢٢٢٢ - أبو عائشة، كوفى روى عن عبد اللَّه بن عمر. روى عنه عبيد اللَّه ابن مروان (١). قال: وكان رجل صدق (٢)."],[3473,"٢٢٢٣ - أبو عائشة، جد أبى عاصم الثقفى (٣). قال: كان على رضي الله عنه (يوهب) (٤) الطلاء (٥)، روى عنه أبو عاصم الثقفى.","",{"fn":"عبيد اللَّه بن مروان. ذكره ابن أبى حاتم في الجرح (٢/ ٢/ ٣٣٤) وقال: سمع أبا عائشة يحدث عن ابن عمر، ولم يذكر فيه شيئا.\nومثله في مصادر الترجمة. ٢٢٢٣ - كنى البخارى (ص ٦٠)، الجرح (٤/ ٢/ ٤١٧)، المقتنى في سرد الكنى (٧٩/ أ).\nتقدم في الكتاب الثانى (٩٦٦).\nهكذا صورتها في الأصل \"يوهب\" وفى كنى البخارى \"يرزقنا\" بلا ذكر \"الطلاء\" وفى الجرح \"يرزقنا الطلاء\".\nالأثر أخرجه النسائى \"الأشربة\" (٨/ ٣٢٩) من طريق الشعبى قال: كان على رضي الله عنه يرزق الناس الطلاء يقع فيه الذباب ولا يستطيع أن يخرج منه\"، وابن أبى شيبة \"الأشربة\" باب الطلاء (٧/ ١٧١) من طريق عبد اللَّه البجلى عن رجل قد سماه قال: كان على يرزق الناس من الطلاء ما ذهب ثلثاه وبقى ثلث، ومن طريق عبد الرحمن بن أبى ليلى وأبى جحيفة قالا: كان على يرزقنا الطلاء وأيضا في (٧/ ١٧٤) من طريق السدى عن شيخ من الحضرميين قال: قسم على طلاء فبعث الىَّ بقدح. . الخ وفى (٧/ ١٧٦) من طريق عطاء عن أبى عبد الرحمن عن على قال كان يرزقنا الطلاء فقلت له: ما هيئته؟ قال: اسود يأخذه أحدنا باصبعه، وقد ذكر ابن التركمانى في الجوهر النقى ="}],[3474,"٢٢٢٤ - أبو عائشة، مدنى سمع شعبة (١) مولى ابن عباس. روى عنه عمر ابن عقبة (٢)."],[3475,"٢٢٢٥ - أبو عائشة (٣) مولى سعيد بن العاص، روى عن حذيفة وأبى موسى الاشعرى. روى عنه مكحول.","",{"fn":"شعبة بن دينار الهاشمى، مولى ابن عباس، المدنى، صدوق، سئ الحافظ، من الرابعة، مات في وسط خلافة هشام./ د. التقريب (١/ ٣٥١).\nفي المقتنى \"عمر بن عقبة شيخ للواقدى\". ٢٢٢٥ - المقتنى في سرد الكنى (٧٩/ أ)، الميزان (٤/ ٥٤٣) وقال: غير معروف، اللسان (٧/ ٤٧٢)، التهذيب (١٢/ ١٤٦)، التقريب (٢/ ٤٤٤)، وقال: مقبول من الثانية./ د.\nفي مصادر الترجمة زيادة \"جليس أبى هريرة\"."}],[3476,"باب أبى عزرة"],[3477,"٢٢٢٦ - أبو عَزْرة (١) بن شهاب أخو طارق بن شهاب، وقد قيل: فيه أبو عزة، وكان كثير الصلاة. سأل بلالا، وسلمان، روى عنه طارق بن شهاب."],[3478,"٢٢٢٧ - أبو عَزْرة، روى عن ثوبان عن النبى عليه السلام من حديث الأعمش.","",{"fn":"عَزْرة: بفتح العين وسكون الزاى وفتح الراء، الاكمال (٦/ ٢٠٠) تبصير المنتبه (٣/ ٩٤٦). ٢٢٢٧ - كنى البخارى (ص ٦٠) وذكر حديثه عن ثوبان مرفوعا \"يوشك أن تداعى عليكم الامم تداعى الاكلة على القصعة. الجرح (٤/ ٢/ ٤١٣) وذكر حديثه أيضا، الاكمال (٦/ ٢٠٢) ذكره المحقق في الهامش. قلت: وحديث ثوبان هذا أخرجه أبو داود \"الملاحم\" باب في تداعى الامم على الاسلام (٤/ ١١١)، وأحمد في المسند (٥/ ٢٧٩) وأبو نعيم في الحلية (١/ ١٨٢). وعزاه الهيثمى في مجمع الزوائد (٧/ ٢٨٧) إلى أحمد والطبرانى في الأوسط. وقال: اسناد أحمد جيد. اهـ."}],[3479,"باب أبى عطية"],[3480,"٢٢٢٨ - أبو عطية (العقيلى) (١) بصرى مولى لبنى عُقَيْل (٢). سمع مالك بن الحويرث الليثى روى عنه بديل بن ميسرة قال أبو حاتم: لم يرو عنه غير بديل بن ميسرة (. . .) (٣) عن بديل بن ميسرة قال: نا أبو عطية مولى لنا (٤) عن مالك بن الحويرث قال: كان يأتينا في مصلانا فقيل له تقدم فصل بنا فقال: ليتقدم بعضكم اننى اخبركم ان رسول اللَّه -صلى الله عليه وآله وسلم- قال: \"إذا زار أحدكم قوما فلا يصل بهم. وليصل بهم رجل منهم\" (٥).","",{"fn":"الحق في هامش الأصل. كتب عنده \"صح\".\nبضم العين كما في الخلاصة (ص ٤٥٥).\nفي الأصل بياض بمقدار كلمتين.\nفي المعجم الكبير وتهذيب الكمال \"مولى منا\".\nالحديث أخرجه أحمد في المسند (٣/ ٤٣٦ و٤٣٧ و٥/ ٥٣). وأبو داود \"الصلاة\" باب امامة الزائر (١/ ١٦٢)، والترمذى وقال حسن صحيح \"الصلاة\" باب من زار قوما فلا يصل بهم (٢/ ٣٣٨)، والنسائى \"الإمامة\" امامة الزائر (٢/ ٨٠) كلهم أخرجوه من طريق بديل بن ميسرة قال حدثنا أبو عطية، عن مالك بن الحويرث به. ="}],[3481,"٢٢٢٩ - أبو عطية المذبوح حديثه عند أبى بكر بن أبى مريم عن حماد ابن سعيد (١). ذكره البخارى.","",{"fn":"زاد البخارى في الكنى \"بن أبى عطية\" وقد ذكر ابن أبى حاتم حماد بن سعيد بن أبى عطية المذبوح في الجرح (١/ ٢/ ١٤٠) وقال: روى عن أبيه روى عنه أبو بكر بن أبى مريم ولم يذكر فيه شيئا. اهـ."}],[3482,"باب أبى عطاء"],[3483,"٢٢٣٠ - أبو عطاء، سمع عليا رضي الله عنه لم يذكروه بغير هذا."],[3484,"٢٢٣١ - أبو عطاء اليحبورى شامى. روى عن عبادة بن الصامت حديثه عند حماد بن سلمة عن داود بن أبى هند (١) عن أبى منيب (٢) عن عبادة في الخسف والمسخ (٣).","",{"fn":"في كنى البخارى \"منيب\".\nفي كنى البخارى \"داود بن أبى منيب\" وإنما هو أبو منيب كما هنا وفى بقية المصادر. وهو أبو المنيب الاحدب \"وانظر الترجمة (١٨٦٢).\nالحديث أخرجه البخارى في الكنى وفيه عنده زيادة لفظ \"انها السنين يتبع بعضها بعضا\". وذكره الهيثمى في مجمع الزوائد (٨/ ١٠) من طريق حبيب أبى حبيب الشامى عن أبى عطاء عن عبادة بن الصامت وغير واحد من الصحابة رضي الله عنهم عن النبى -صلى الله عليه وآله وسلم- قال: \"والذى نفس محمد بيدة ليبيتن أناس من امتى على أشر وبطر ولعب ولهو فيصبحوا قردة وخنازير باستحلالهم الحرام واتخاذهم القينات وشربهم الخمر وبأكلهم الربا ولبسهم الحرير. وقال: رواه عبد اللَّه ورواه الطبرانى من حديث أبى أمامة فقط وفرقد ضعيف أهـ."}],[3485,"٢٢٣٢ - أبو عطاء، مولى عتبة. قال: قدم ابن عباس على معاوية. روى عنه أبو خالد (١).","",{"fn":"هو المتقدم في (١٥٧٣) حيث جاء في ترجمته هناك أنه روى عن أبى عطاء مولى عتبه بن أبى سفيان."}],[3486,"باب أبى عمير"],[3487,"٢٢٣٣ - أبو عمير، عن عاصم الجحدرى، روى عنه هارون النحوى."],[3488,"٢٢٣٤ - أبو عمير قال: كنا مع ابن سيرين في سفر فنمنا حتى طلعت الشمس، سمع منه الثورى."],[3489,"٢٢٣٥ - أبو عمير بن أنس بن مالك، روى عن عمومته (١). روى عنه أبو بشر جعفر بن أبى وحشية.","",{"fn":"في كنى البخارى \"عمر مثله\" وهو تحريف. واللَّه أعلم والصواب \"عن عمومته\" كما هو مثبت واللَّه أعلم."}],[3490,"٢٢٣٦ - أبو عمير (١) بن سَرِيع، كان عريفا لبنى سَرِيع (٢). روى عن عبد اللَّه ابن عمرو. روى عنه توبة بن نمر (٣).","",{"fn":"هكذا في الأصل \"عمير\" بالميم، وفى كنى البخارى والجرح \"عفير\" بالفاء المعجمة وقد ذكره ابن حبان في الثقات (٥/ ٢٨٢) فقال: عرِيَف بن سريع يروى عن عبد اللَّه بن عمر روى عنه توبة بن نمر. وجاء في الجرح (١/ ١/ ٤٤٦) في ترجمة توبة بن نمر الحضرمى المصرى أنه روى عن أبى عفير عن ابن عمر. وفى التاريخ الكبير (١/ ٣/ ١٥٦) في ترجمة توبة بن نمر أيضا أنه سمع أبا عفير عريف بن سريع عن عبد اللَّه بن عمرو أن عمر حمل على فرس في سبيل اللَّه فقال النبى -صلى الله عليه وآله وسلم-: إذا تصدقت فامضها روى عنه الليث \" أهـ. وفى تعجيل المنفعة (ص ١٩٠) عريف بن سريع أبو عفير، عن ابن عمر رضي الله عنهما وعنه توبة بن نمر، وثقه ابن حبان. اهـ. وقال ابن ماكولا في الاكمال (٦/ ١٦٩)، وأما عَرِيف بفتح العين كسر الراء فهو عريف بن سريع أبو عفير المصرى، روى عن عبد اللَّه بن عمرو، روى عنه أبو توبة. اهـ. والى هذا ذهب ابن حجر في تبصير المنتبه (٣/ ٩٤٤). قلت: وقد أخرج أحمد في المسند (٢/ ١٧٣) من حديث عمرو بن العاص وفيه قال -صلى الله عليه وآله وسلم- \"إذا تصدقت بصدقة فامضها. من طريق عمرو بن الحارث أن توبة بن نمر حدثه أن أبا عريف سريع حدثه أن رجلا سأل ابن عمرو بن العاص. الحديث.\nالنسبة اليهم سَرِيعى: بفتح السين كسر الراء وسكون الياء المثناة من تحتها وفى آخرها عين مهملة، وهو بطن من المعافر. انظر اللباب (٢/ ١١٥).\nتوبة بن نمر الحضرمى المصرى. ذكره ابن أبى حاتم في الجرح (١/ ١/ ٤٤٦) والبخارى في التاريخ الكبير (١/ ٢/ ١٥٦) ولم يذكرا فيه شيئا."}],[3491,"باب أبى عياش"],[3492,"٢٢٣٧ - أبو عياش، مصرى، روى عن جابر بن عبد اللَّه. روى عنه يزيد بن أبى حبيب، وخالد بن أبى عمران المصريان."],[3493,"٢٢٣٨ - أبو عياش سمع رحيلة مولى عائشة. روى عنه بقية بن الوليد."],[3494,"٢٢٣٩ - أبو (العياش) (١). روى عن سعيد بن المسيب، روى عنه الحارث ابن عبد الرحمن بن أبى ذباب (١) حديثه عن على وعن النبى عليه السلام \"في اسباغ الوضوء في المكاره\" (٢) وقد روى عنه عبد الرحمن بن الحارث بن عبد اللَّه ابن عياش (١).","",{"fn":"هكذا ذكره ابن عبد البر هنا في باب أبى عياش بالمثناة التحتانية المشددة والذى في كنى البخارى والجرح \"أبو العباس\" بالباء الموحدة، وزاد في كنى البخارى قوله \"ويقال: أبو العياس\" وجزم ابن أبى حاتم في بيان خطأ البخارى في التاريخ (ص ١٦٠) بأنه أبو العياس بالمثناة من تحتها وبالسين المهملة. وقال ابن ماكولا في الاكمال (٦/ ٦٤): وأما عياس: بياء مشددة معجمة باثنتين من تحتها فهو أبو العياس، شيخ مدنى، روى عن سعيد بن المسيب =\nالحارث بن عبد الرحمن بن أبى ذباب. الذال مضمومة. فوقها نقطة وتحت الباء نقطة. كذا قال العسكرى في تصحيفات المحدثين (٢/ ٦٦٢) والحارث هذا ذكره ابن أبى حاتم في الجرح (١/ ٢/ ٧٩ - ٨٠) وقال: سألت أبى عنه فقال: ليس بذاك القوى، يكتب حديثه. وقال: قال أبو زرعة: لا بأس به.\nالحديث أخرجه الحاكم في الكنى (٢/ ٤٢/ ب)، وأخرجه أيضا أبو يعلى والزار باسناد صحيح، انظر الترغيب والترهيب (١/ ١٣٢) ولفظه عندهم \"اسباغ الوضوء على المكاره، واعمال الاقدام إلى المساجد وانتظار الصلاة بعد الصلاة يغسل الخطايا غسلًا. وروى الطبرانى في الأوسط من حديث على رضي الله عنه عن النبى -صلى الله عليه وآله وسلم- قال: \"من اسبع الوضوء في البرد الشديد كان له من الاجر كفلان\" قال الهيثمى في مجمع الزوائد (١/ ٢٣٧) فيه عمر بن حفص العبدى وهو متروك. وانظر الترغيب والترهيب (١/ ١٣٣). وروى عبد اللَّه في زياداته على أبيه عن على بن أبى طالب قال: قال رسول اللَّه -صلى الله عليه وآله وسلم-: \"يا على اسبع الوضوء وان شق عليك ولا تأكل الصدقة ولا تنزى الحمر على الخيل ولا تجالس أصحاب النجوم\". قال الهيثمى في مجمع الزوائد (١/ ٢٣٦) فيه القاسم بن عبد الرحمن وفيه ضعف. ويشهد لهذا الحديث ما أخرجه مسلم \"الطهارة باب فضل اسباغ الوضوء (١/ ٢١٩)، والنسائى \"الطهارة\" باب فضل اسباغ الوضوء (١/ ٨٩)، وابن ماجه \"الطهارة - باب اسباغ الوضوء\" (١/ ١٤٨) والترمذى \"الطهارة\" باب اسباغ الوضوء (١/ ١٧١). وقال: حديث حسن صحيح. وفى الباب عن على وعبد اللَّه بن عمرو =\nعبد الرحمن بن الحارث بن عبد اللَّه بن عياش، بتحتانية، ومعجمة، ابن أبى ربيعة المخزومى، أبو الحارث، المدنى، صدوق، له أوهام، من السابعة (ت: ١٤٣). انظر التقريب (١/ ٤٧٦)."}],[3495,"باب أبى عقبة"],[3496,"٢٢٤٠ - أبو عقبة الأَلهانى. عن أبى هريرة. روى عنه ثابت بن اسلم البنانى. يعد في أهل البصرة."],[3497,"٢٢٤١ - أبو عقبة روى عن عبد اللَّه بن عمر. روى عنه عبد العزيز بن المختار (١) من حديثه قال: \"مررت مع ابن عمر فمر بغلمة من حبش يلعبون فأعطاهم درهمين\" (٢).","",{"fn":"عبد العزيز بن المختار الدباغ، البصرى، مولى حفصه بنت سيرين، ثقة، من السابعة./ ع. التقريب (١/ ٥١٢).\nالأثر ذكره البخارى في الكنى، وابن أبى حاتم في الجرح. انظر مصادر الترجمة."}],[3498,"باب أبى العجماء"],[3499,"٢٢٤٢ - أبو العجماء السلمى. عن عبد اللَّه بن عمرو بن العاص روى عنه صالح بن جبير الصُّدَائى (١)."],[3500,"٢٢٤٣ - أبو العجماء (٢). عن عمر. روى عنه يحيى بن أبى عمرو السيبانى (٣).","",{"fn":"صالح بن جبير الصُّدائى، بضم المهملة وتخفيف الدال: نسبة إلى صُدَا قبيلة من اليمن. انظر اللباب (٢/ ٢٣٦)، وصالح هذا كاتب لعمر بن عبد العزيز، صدوق، من الرابعة. التقريب (١/ ٣٥٨). ٢٢٤٣ - كنى البخارى (ص ٦٢)، كنى الحاكم (٢/ ٣٢/ أ) وذكره هو وسابقه في باب أبى العجفاء بالفاء، ثم قال في آخر هذه الترجمة: وخليقا أن يكون هذا أبو العجماء بالميم. اهـ بيان خطأ البخارى في تاريخه (ص ١٦٠)، الجرح (٤/ ٢/ ٤٢٠)، الاكمال (٦/ ١٤٩).\nهكذا في الأصل \"العجماء\" بالميم وكذا في الجرح والاكمال وبيان خطأ البخارى في تاريخه. والذى في كنى البخارى \"العجفاء\" بالفاء.\nفي كنى البخارى \"الشيبانى\" بالشين المعجمة. ونبه ابن أبى حاتم في بيان خطأ البخارى في التاريخ بأنه بالسين المهملة \"السّيبانى\" وذكره ابن ماكولا أيضا فقال: أبو العجماء بالميم فهو أبو العجماء السّيبانى روى عن عمر بن الخطاب، روى عنه يحيى بن أبى عمرو السيبانى. انظر مصادر الترجمة."}],[3501,"باب الكنى الشتى"],[3502,"٢٢٤٤ - أبو عمرة الجهنى. مولى زيد بن خالد الجهنى المدنى. روى عن (١) زيد بن خالد الجهنى. روى عنه محمد بن يحيى بن حَبَّان (٢)."],[3503,"٢٢٤٥ - أبو العَنْبَس (٣) الأكبر (٤). روى عن عبد اللَّه بن عمرو بن العاص وروى عن جابر بن زيد عن ابن عباس. روى عنه شعبة بن الحجاج وعبد الملك ابن عمير. يعد في البصريين.","",{"fn":"في الميزان \"عن مولاه عن زيد بن خالد\".\nمحمد بن يحيى بن حَبَّان: بفتح الحاء المهملة وبالباء المعجمة بواحدة، ابن منقذ الأنصارى المدنى، ثقة فقيه، من الرابعة (ت ١٢١) وهو ابن أربع وسبعين سنة. الاكمال (٢/ ٣٠٤)، تصحيفات المحدثين (٢/ ٤٤٨) التقريب (٢/ ٢١٦). ٢٢٤٥ - الجرح (٤/ ٢/ ٤١٩) وقال: سمعت أبى يقول: لا يسمى، فقلت: ما حاله؟ فقال: شيخ: وكذا قال أبو زرعة: لا يعرف اسمه. تاريخ ابن معين (٢/ ٧١٨) وقال: لا أعرف اسمه، كنى الدولابى (٢/ ٤٦)، الاكمال (٦/ ١٨)، الميزان (٤/ ٥٥٩) وقال: لم يسم وقيل: هو عبد اللَّه بن مروان، التهذيب (١٢/ ١٨٩)، التقريب (٢/ ٤٥٧) وقال: قيل: اسمه عبد اللَّه بن مروان، مقبول، من السادسة./ د. س.\nالعَنْبس: بفتح أوله، وسكون النون، وفتح الموحدة بعدها مهملة، تبصير المنتبه (٣/ ٩١٩).\nأبو العَنْبَس الاصغر هو الملائى واسمه سعيد بن كثير تقدم في (٩٨٥)."}],[3504,"٢٢٤٦ - أبو عدى الايامى (١)، روى عن ثوبان مولى رسول اللَّه -صلى الله عليه وآله وسلم- روى عنه (٢)."],[3505,"٢٢٤٧ - أبو عُذْرة (٣) أدرك النبى عليه السلام. وروى عن عائشة عن النبى عليه السلام \"أنه نهى الرجال والنساء عن الحمامات ثم رخص للرجال في المآزر\" (٤). روى عنه عبد اللَّه بن شداد قال أبو زرعة: لا أعلم روى حماد بن سلمة عن عبد اللَّه بن شداد غير هذا الحديث.","",{"fn":"الإيَامى، بكسر الالف وفتح الياء المنقوطة باثنتين من تحتها - هذه النسبة إلى إِيَام ويقال: يَام أيضا بغير الف. وهو بطن من همدان. اللباب (١/ ٩٦).\nهكذا ذكر ابن عبد البر هذه الترجمة فقال: روى عنه. ولم يذكر من روى عنه. ٢٢٤٧ - كنى البخارى (ص ٦١)، الجرح (٤/ ٢/ ٤١٨) وقال: سئل أبو زرعة عن أبى عذرة هل يسمى فقال: لا أعلم أحدا سماه. ولم يرو حماد بن سلمة عن عبد اللَّه بن شداد إلا هذا الحديث. الثقات (٥/ ٥٧٧) وقال: قيل: له صحبة. اللسان (٧/ ٨٠) وقال: مجهول، كنى الحاكم (٢/ ٤٠/ ب) وقال: يقال: انه كان شيخ من تجار واسط.\nعذرة: هكذا هو مضبوط في الأصل بضم العين وسكون الذال المعجمة وانظر الاكمال (٦/ ٢٠٣)، وتبصير المنتبه (٣/ ٩٣٨).\nالحديث أخرجه البخارى في الكنى والحاكم في الكنى من طريق حماد بن سلمة عن عبد اللَّه بن شداد عن أبى عذرة عن عائشة به. وأخرجه أيضا أحمد في المسند (٦/ ١٣٩، ١٧٩) وأبو داود \"الحمام\" (٤/ ٣٩)، وابن ماجه \"الأدب\" باب دخول الحمام (٢/ ١٢٣٤). والترمذى \"الأدب\" باب ما جاء في دخول الحمام (٨/ ٨٦) وقال: حديث لا نعرفه إلا من حديث حماد بن سلمة واسناده ليس بذاك القائم. كلهم أخرجوه من طريق حماد بن سلمة عن عبد اللَّه بن شداد عن أبى عذرة به زاد أحمد وابن ماجه \"ولم يرخص للنساء\" وقد ذكر الحافظ المنذرى في ="}],[3506,"٢٢٤٨ - أبو عِيْش (١) روى عن هارون التيمى. روى عنه اسحاق بن سليمان الرازى قال أبو حاتم: لا يعرف أبو عيش ولا هارون التيمى."],[3507,"٢٢٤٩ - أبو عذبة (٢). روى عن عمر بن الخطاب اللهم عجل عليهم بالغلام الثقفى (٣). روى عنه سريج بن عبيد."],[3508,"٢٢٥٠ - أبو عُطَارِد (٤)، روى عن ابن مسعود، روى عنه إِيَاد بن لَقِيط (٥).","",{"fn":"عِيْش: بكسر العين وبعدها ياء ساكنة معجمه باثنتين من تحتها وآخره شين معجمة: الاكمال (٦/ ٩٣)، تبصير المنتبه (٣/ ٩١١). ٢٢٤٩ - كنى البخارى (ص ٦٢)، الجرح (٤/ ٢/ ٤٢٠)، الميزان (٤/ ٥٥١). وقال مجهول، كنى الحاكم (٢/ ٤٢/ أ). الاكمال (٦/ ١٦٥).\nفي كنى البخارى \"عذية\" بالياء المثناة من تحتها، وفى الاكمال (٦/ ١٦٥) \"عذبة\": بعين مفتوحة وذال معجمة وباء معجمة بواحدة فهو أبو عذبة عن عمر.\nالأثر أخرجه البخارى في الكنى، والحاكم في الكنى كما في مصادر الترجمة وابن قتيبة في المعارف (ص ٣٩٧)، وابن العماد الحنبلى في شذرات الذهب (١/ ١٠٦ - ١٠٧) كلهم أخرجوه من طريق أبى عذبة به. ٢٢٥٠ - كنى البخارى (ص ٦٢)، الجرح (٤/ ٢/ ٤٢٠)، كنى الحاكم (٢/ ٤٢/ ب) وذكره عن محمد بن إسماعيل البخارى.\nعطار: بضم عين وكسر راء. المغنى (ص ٥٤).\nإياد، بكسر أوله ثم تحتانية، بن لقيط، بفتح لام كسر قاف وبطاء مهملة، ="}],[3509,"٢٢٥١ - أبو العَيْزَار (١)، والد عقبة (٢) بن أبى العيزار كوفى، سمع ابن عباس روى عنه ابنه عقبة، وروى عنه عاصم بن كليب."],[3510,"٢٢٥٢ - أبو عَنْبَسَة (٣). قال: \"حججت فلقيت ابن عمر\" (٤) روى عنه معاوية بن صالح."],[3511,"٢٢٥٣ - أبو العذراء (٥)، روى عن أبى الدرداء، روى عنه عمير (٦) بن هانئ (٧)","",{"fn":"العيزار: بفتح مهملة وسكون تحتية وبزاى والف وراء المغنى (ص ٥٧).\nعقبة بن أبى العيزار، ذكره ابن أبى حاتم في الجرح (٣/ ١/ ٣١٥) وذكر أنه سئل عنه يحيى القطان فقال: لم يكن به بأس. . اهـ. وقال أحمد بن حنبل: صالح الحديث. . وقال أبو زرعة: لا بأس به. ٢٢٥٢ - كنى البخارى (ص ٦٢) ذكره كما هنا. الجرح (٤/ ٢/ ٤٢٠)، كنى الحاكم (٢/ ٤٢/ ب) وقال: يقال: مات سنة أربع وعشرين ومائة.\nعَنْبَسَة: بفتح عين وسكون نون رفتح موحدة وسين مهملة. المغنى (ص ٥٦).\nأخرجه البخارى في الكنى، والحاكم في الكنى، وابن أبى حاتم في الجرح، من طريق معاوية بن صالح عن أبى عنبسة به. انظر مصادر الترجمة. ٢٢٥٣ - كنى البخارى (ص ٦٣)، الجرح (٤/ ٢/ ٤٢٠)، الميزان (٤/ ٥٥١) وقال: أبو العذراء عن أم الدرداء، وعنه عمير بن هانئ، مجهول، اللسان (٧/ ٨١)، كنى الحاكم (٢/ ٤٢/ ب).\nالعذراء: بالذال المعجمة.\nفي كنى البخارى \"عمر\".\nزاد الحاكم في الكنى \"العنسى\" وفى التقريب (٢/ ٨٧) عمير بن هانئ العنسى، بسكون النون ومهملتين، أبو الوليد الدمشقى الدارانى، ثقة، من كبار الرابعة، قتل سنه (١٢٧). وقيل: قبل ذلك. اهـ."}],[3512,"وقد روى عن أم الدرداء (١) عن أبى الدرداء."],[3513,"٢٢٥٤ - أبو العجلان المحاربى، وكان في جيش ابن الزبير، سمع ابن عمر، الفضل بن يزيد (*) وحميد بن أبى غنِيَّة (٢)."],[3514,"٢٢٥٥ - أبو عَبْس (٣) بن محمد بن أبى عبس بن جبر الأنصارى. روى عنه ابنه عبد المجيد (١).","",{"fn":"هناك زوجتان لأبى الدرداء تسمى كل واحدة منهما أم الدرداء كبرى وصغرى فالكبرى تسمى خيرة بنت أبى حدرد صحابية من فضلى النساء وعقلائهن وذوات الرأى فيهن مع العبادة والنسك توفيت قبل أبى الدرداء وذلك بالشام في خلافة عثمان رضي الله عنه وكانت حفظت عن النبى -صلى الله عليه وآله وسلم- وعن زوجها روى عنها جماعة من التابعين منهم ميمون بن مهران. انظر الإصابة (٤/ ٢٩٥) وأما أم الدرداء الصغرى فاسمها هجيمة، وقيل: جهيمة الاوصابية الدمشقية، ثقة، فقيهة، من الثالثة (ت: ٨١) /ع التقريب (٢/ ٦٢١) وانظر أيضا تهذيب الكمال (٣/ ١٧٠٢ - ١٧٠٣). ٢٢٥٤ - كنى البخارى (ص ٦٣)، الجرح (٤/ ٢/ ٤٢٠) كنى الحاكم (٢/ ٤٣/ ب) تهذيب الكمال (٣/ ١٦٢٦)، الميزان (٤/ ٥٥١) وقال: مجهول التهذيب (١٢/ ١٦٥) وقال: قال العجلى: أبو العجلان المحاربى شامى تابعى ثقة، وذكر ابن عبد البر أنه كان في جيش ابن الزبير. وفى التقريب (٢/ ٤٥٠) أبو العجلان المجاربى. وقيل فيه: أبو المخارق، مقبول من الرابعة./ بخ *. زاد في الجرح \"الثمالى\" وفى التقريب (٢/ ١١٢) الفضل بن يزيد الثمالى، بضم المثلثة، ويقال: البجلى، الكوفى، صدوق، من السادسة./ ت.\nحميد بن أبى غنية، بفتح المعجمة كسر النون وتشديد التحتانية، صدوق من السابعة التقريب (١/ ٢٠٣). ٢٢٥٥ - كنى البخارى (ص ٦٣) كنى الحاكم (٢/ ٣٠/ ب)، الجرح (٤/ ٢/ ٤٢٠) وقد ذكره ابن حجر في التهذيب (١٢/ ١٥٧) في ترجمة أبى عبس بن جبر عرضا فقال: أبو عبس بن محمد بن أبى عبس. الاكمال (٦/ ٨٩).\nبفتح العين وسكون الباء الموحدة. كما في الاكمال (٦/ ٨٨)."}],[3515,"٢٢٥٦ - أبو عكاشة (٢). روى عن أبى رفاعة (٣). روى عنه أبو ليلى الهمدانى (٤)."],[3516,"٢٢٥٧ - أبو عَتِيق (٥) (البصرى) (٦) روى عن ابان بن يزيد الرقاشى (٧) (. . . .) (٨)."],[3517,"٢٢٥٨ - أبو العبّاس، روى عن إبراهيم، روى عنه أبو الاحوص."],[3518,"٢٢٥٩ - أبو عكرمة. روى عن القاسم أبى عبد الرحمن، روى عنه عبد اللَّه ابن صالح.","",{"fn":"ذكره ابن أبى حاتم في الجرح (٣/ ١/ ٦٤) وذكر روايته عن أبيه وقال: سألت أبى عنه فقال: هو لين. اهـ. ٢٢٥٦ - كنى البخارى (ص ٦٣)، الجرح (٤/ ٢/ ٤٢٠)، كنى الحاكم (٢/ ٤٣/ أ)، الميزان (٤/ ٥٥٣) وقال: لا يكاد يعرف. التهذيب (١٢/ ١٧٢)، التقريب (٢/ ٤٥٢) وقال: مجهول من السادسة./ ق.\nزاد الحاكم \"الهمدانى\".\nفي كنى الحاكم والميزان، والتهذيب \"رفاعة\" وزاد الحاكم \"البجلى\".\nأبو ليلى الهمدانى، هو المتقدم في الترجمة (١٧٣١). ٢٢٥٧ - كنى البخارى (ص ٦٣)، الجرح (٤/ ٢/ ٤٢٠)، كنى الحاكم (٢/ ٣١/ أ) الاكمال (٦/ ١١١).\nعتيق: بفتح العين. الاكمال (٦/ ١٠٩).\nغير واضح في الأصل، والمثبت عن مصادر الترجمة.\nأبان بن يزيد الرقاشى: ذكره ابن أبى حاتم في الجرح (١/ ١/ ٢٩٥) وقال: سمعت أبى يقول: أبان الرقاشى، لم يصح حديثه. إنما روى حديثا واحدا. يرويه عنه ابنه، ما نقدر أن نقول فيه.\nفي الأصل بياض بمقدار كلمة. ٢٢٥٨ - كنى البخارى (ص ٦٣)، الجرح (٤/ ٢/ ٤٢١). ٢٢٥٩ - كنى البخارى (ص ٦٣)، الجرح (٤/ ٢/ ٤٢١)، كنى الحاكم (٢/ ٣٢/ ب) ="}],[3519,"٢٢٦٠ - أبو عَطَّاف (١) الازدى، عن أبى هريرة، روى عنه الجريرى."],[3520,"٢٢٦١ - أبو عبدة (٢) روى عن أنس بن مالك عن النبى عليه السلام في تخليل اللحية (٣). روى عنه موسى بن داود قاضى طرسوس.","",{"fn":"عَطَّاف: بفتح العين والطاء المهملة المشددة. تبصير المنتبه (٣/ ٩٥٧). ٢٢٦١ - الجرح ٤/ ٢/ ٤٢١.\nعبدة: بفتح العين المهملة أول الحروف وسكون الباء الموحدة من تحتها. تبصير المنتبه (٣/ ٩٠٧).\nالحديث لم أقف عليه من طريق أبى عبدة. ولكن حديث أنس أخرجه أبو داود \"الطهارة\" باب تخليل اللحية (١/ ٣٦) وابن ماجه \"الطهارة\" - باب ما جاء في تخليل اللحية (١/ ١٤٨) والحاكم \"الطهارة\" باب تخليل اللحية (١/ ٣٨)، وأبو بكر الشافعى في الفوائد (٨٤٨) ولفظه عند أبى داود \"أن رسول اللَّه -صلى الله عليه وآله وسلم-\" كان إذا توضأ أخذ كفا من ماء فأدخله تحت حنكه فخلل به لحيته وقال هكذا أمرنى ربى عز وجل\". والباقون بنحوه. وذكر الهيثمى في مجمع الزوائد (١/ ٢٣٥) عن أنس بن مالك قال: وضأت رسول اللَّه -صلى الله عليه وآله وسلم- فأدخل يده تحت حنكه فخلل ليحته فقلت: ما هذا؟ فقال بهذا أمرنى ربى عز وجل. وقال الهيثمى: رواه الطبرانى في الأوسط ورجاله وثقوا. وأخرج الترمذى \"الطهارة\" باب ما جاء في تخليل اللحيه (١/ ١٣٠) حديث عمار وفيه انه رأى رسول اللَّه -صلى الله عليه وآله وسلم- يخلل لحيته. وقال الترمذى وفى الباب عن عثمان وعائشة وام سلمة وأنس وابن أبى اوفى وأبى أيوب. قلت: وحديث أنس هذا متكلم فيه فقد قال الحافظ في تلخيص الحبير (١/ ٨٦) بعد أن ذكر الحديث من رواية أبى داود: في اسناده الوليد بن زوران ="}],[3521,"٢٢٦٢ - أبو العَدَبَّس (١)، روى عن أبى خلف.","",{"fn":"العَدَبَّس: بفتح العين والدال وتشديد الباء المعجمة بواحدة، كما في الاكمال ="}],[3522,"وعن أبى مرزوق (١) روى ابن نمير عن مسعر عن أبى العنبس عن أبى العدبس عن أبى مرزوق عن أبى غالب عن أبى أمامة عن النبى عليه السلام قال: \"إذا رأيتمونى فلا تقوموا كما تفعل العجم بعضها لبعض\" (٢). وقد روى مسعر عن أبى العدبس وروى أبو خلف عن أبى مرزوق.","",{"fn":"أبو مرزوق هو المتقدم في (١٨٦٨).\nالحديث أخرجه أحمد (٥/ ٢٥٣) من طريق ابن نمير، ثنا مسعر عن أبى العنبس عن أبى العدبس عن أبى مرزوق عن أبى غالب عن أبى أمامة قال: خرج علينا رسول اللَّه -صلى الله عليه وآله وسلم- وهو متوكئ على عصا فقمنا إليه فقال: \"لا تقوموا كما تقوم الاعاجم يعظم بعضها بعضا\". قال: فكانا اشتهينا أن يدعو اللَّه لنا فقال: \"اللهم اغفر لنا وارحمنا وارض عنا وتقبل منا وادخلنا الجنة وانجنا من النار، واصلح لنا شأننا كله\" فكأنا اشتهينا أن يزيدنا فقال: \"قد جمعت لكم الامر\". وأخرجه أحمد أيضا في المسند (٥/ ٢٥٦) من طريق مسعر ثنا أبو العدبس عن رجل أظنه أبا خلف، ثنا أبو مرزوق قال: قال أبو أمامة خرج علينا رسول اللَّه -صلى الله عليه وآله وسلم- فذكر الحديث. وأخرج أبو داود \"الأدب\" باب في قيام الرجل للرجل (٤/ ٣٥٨) من طريق عبد اللَّه بن نمير عن مسعر عن أبى العنبس عن أبى العدبس عن أبى مرزوق عن أبى غالب عن أبى أمامة يرفعه مختصرا وفيه قال، \"لا تقوموا كما تقوم إلا عاجم يعظم بعضها بعضا\" وابن ماجه \"الدعاء\" باب دعاء رسول اللَّه -صلى الله عليه وآله وسلم- (٢/ ١٢٦١) من طريق على بن محمد عن وكيع عن مسعر، عن أبى مرزوق، عن أبى وائل عن أبى امامة الباهلى يرفعة به بنحوه عند أحمد. وذكر المزى طريقا آخر للحديث عند ابن ماجه عن على بن محمد عن وكيع عن مسعر عن أبى مرزوق عن أبى العدبس عن أبى أمامة به وقال: هكذا عنده وهو وهم، والصواب الأول أهـ. انظر تحفة الاشراف (٤/ ١٨٣) قلت: ويريد بالأول طريق أبى داود ="}],[3523,"٢٢٦٣ - أبو عُبَادة (١) الزرقى حجازى، روى عن خولة بنت قيس الانصارية (٢) امرأة حمزة بن عبد المطلب. روى عنه عبيد سَنُوطا (٣)."],[3524,"٢٢٦٤ - أبو عقرب الاسدى. روى عن أبى الصلت عن عبد اللَّه بن مسعود. روى عنه طلق بن حبييب وأبو عوانة (١)، يعد في البصريين.","",{"fn":"عبادة: بضم أوله والتخفيف كما في التقريب (٢/ ٤٤٤).\nخولة بنت قيس بن قهد بن قيس بن ثعلبة الانصارية، زوج حمزة بن عبد المطلب، صحابية، لها حديث: التقريب (٢/ ٥٩٦).\nعبيد سَنُوطا، بفتح المهملة وضم النون، ويقال: ابن سنوطا أبو الوليد المدنى وثقه العجلى، من الثالثة. التقريب (١/ ٥٤٦). ٢٢٦٤ - كنى البخارى (ص ٦٢)، كنى الحاكم (٢/ ٢٩/ ب)، الجرح (٤/ ٢/ ٤١٨) وقال: سمع عبد اللَّه بن مسعود. تعجيل المنفعة (ص ٣٣٢) وقال: قال الحسينى: أبو عقرب عن ابن مسعود رضي الله عنه في ليلة القدر وعنه طلق ابن حبيب، مجهول. اهـ. قال ابن حجر: قلت: وله طريق آخر عند أحمد وهو من رواية أبى يعفور عن أبى الصلت عن أبى عقرب وذكره أبو نعيم في تسمية أصحاب على وابن مسعود رضي الله عنهما، وأما ما نقله الحاكم أبو أحمد عن ابن معين انه قال: أبو عقرب يروى عن أبى الصلت عن عبد اللَّه فلعله انقلب، أو كان فيه يروى عن أبى الصلت، فوقع في السياق تغيير. ووقع في الثقات لابن خلفون أن أبا عوانة روى عنه وفيه نظر فانه في المسند من طريق أبى عوانة عن أبى يعقوب عن أبى الصلت. اهـ. قلت: وانظر الحديث بطريقيه في المسند (١/ ٤٠٦) من حديث ابن ="}],[3525,"٢٢٦٥ - أبو عتيبة بن المهلب بن أبى صفرة. روى عن يزيد بن المهلب (٢). روى عنه خالد بن نافع الاسدى."],[3526,"٢٢٦٦ - أبو عَذَبَة، عن نافع مولى ابن عمر، روى عنه الجراح بن مليح (٣) حديثه في الشاميين. قال أبو أحمد الحاكم: وخليقا أن يكون هذا هو الذى روى عن عمر. وروى عنه شريح بن عبيد (١).","",{"fn":"أبو عوانة هو وضاح اليشكرى المتقدم في (٩٩٧). ٢٢٦٥ - كنى الحاكم (٢/ ٤٢/ أ).\nيزيد بن المهلب، كان كريما ممدحا، كثير الغزو والفتوح، كان أميرا على البصرة، فلما تولى عمر بن عبد العزيز، عزله وسجنه، فلما توفى عمر أخرجه خواصه من السجن فوثب على البصرة وهرب منه عاملها عدى بن ارطاة الفزارى ونصب يزيد رايات سود وتسمى بالقحطانى وقال: أدْعُو إلى سيرة عمر بن الخطاب فوجه إليه يزيد بن عبد الملك أخاه مسلمة فحاربه وقتله في صفر سنة اثنتين ومائة، وقيل: بل حبسه الحجاج وعذبه. انظر شذرات الذهب (١/ ١٢٤). ٢٢٦٦ - الثقات (٧/ ٦٦٤) وقال \"يروى عن نافع روى عنه شريح بن عبيد وأهل الشام. الجرح (٢/ ٤/ ٤٢٠)، الميزان (٤/ ٥٥١) وقال: أبو عذَبَةَ -بالحركات- عن نافع في الغسل قال الدارقطنى: مجهول. اللسان (٧/ ٨٠)، كنى الحاكم (٢/ ٤٢/ ب) وقال: وخليقا أن يكون هذا هو الذى روى عن عمر وروى عنه شريح بن عبيد. واللَّه أعلم. اهـ.\nزاد الحاكم في الكنى \"البهرانى\".\nأبو عذبة الذى روى عن عمر وعنه شريح بن عبيد هو المتقدم في (٢٢٤٩)."}],[3527,"حرف الغين"],[3528,"باب أبى غالب"],[3529,"٢٢٦٧ - أبو غالب، سمع عبد اللَّه بن عمر، روى عنه نهشل بن مجمّع الضبى (١) (و) (٢) أبو سنان (٣). قال عباس: سمعت يحيى بن معين يقول: أبو غالب. الذى يحدث سفيان عن نهشل عنه: لا أعرفه (٤)."],[3530,"٢٢٦٨ - أبو غالب المكى، روى عن أنس، روى عنه هشام بن حسّان.","",{"fn":"كوفى صدوق، من السابعة. التقريب (٢/ ٣٠٨).\n\"و\" ليست في الأصل، والسياق يقتضيها.\nزاد في التهذيب \"ضرار بن مرة\".\nالتاريخ (٢/ ٧١٩). ٢٢٦٨ - الجرح (٤/ ٢/ ٤٢٢)."}],[3531,"باب أبى غسان"],[3532,"٢٢٦٩ - أبو غسّان، روى عن عطاء بن أبى رباح، روى عنه سفيان الثورى."],[3533,"٢٢٧٠ - أبو غسّان، روى عن الحسن، روى عنه ليث بن أبى سليم."],[3534,"٢٢٧١ - أبو غسّان، روى عن الضحاك بن مزاحم، روى عنه يحيى بن اليمان."],[3535,"باب أبى غانم"],[3536,"٢٢٧٢ - أبو غانم، روى عن (أبى غالب) (١) عن أبى أمامة. روى عنه (زيد ابن أبى موسى (٢) مولى عطاء) (٣)."],[3537,"٢٢٧٣ - أبو غانم، سمع الحسن، وبلال بن أبى بردة (٤) قاضى البصرة روى عنه سوادة (٥).","",{"fn":"غير واضح في الأصل والمثبت عن مصادر الترجمة.\nزيد بن أبى موسى مولى عطاء، ذكره ابن أبى حاتم في المجرح (١/ ٢/ ٥٧٣) وذكر روايته عن أبى غانم، عن أبى غالب عن أبى امامة. وقال: سألت أبى عنه فقال: لا أعرفه. وانظر اللسان (٢/ ٥١١).\nغير واضح في الأصل. والمثبت عن مصادر الترجمة. ٢٢٧٣ - المقتنى في سرد الكنى (١٠٩/ أ).\nبلال بن أبى بردة بن أبى موسى الاشعرى، قاضى البصرة، مقل، من الخامسة: مات سنة نيف وعشرين ومائة. التقريب (١/ ١٠٩).\nهو سوادة بن أبى العالية. ذكره ابن أبى حاتم في الجرح (٢/ ١/ ٢٩٣) ولم يذكر فيه شيئا."}],[3538,"باب كنى شتى"],[3539,"٢٢٧٤ - أبو الغصن، الشامى، سمع شداد بن أوس، روى عنه يحيى بن حسان (١)."],[3540,"٢٢٧٥ - أبو غِيَاث (٢) البصرى. روى عن الحسن. روى عنه سلام بن مسكين."],[3541,"٢٢٧٦ - أبو غَطَفَان (٣) بن طريف المرى (٤) ويقال: ابن مالك مدنى، روى عن أبى هريرة، وابن عباس، روى عنه إسماعيل بن أمية، وعمر بن حمزة بن عبد اللَّه بن عمر (١)، وداود بن الحصين، وقارظ بن شيبة الزهرى (٢)، كان لأبى غطفان دار بالمدينة عند دار عمر بن عبد العزيز (٣) قال يحيى بن معين: أبو غطفان الذى يحدث عنه داود بن الحصين مدنى ثقة حكاه عنه عباس (٤).","",{"fn":"زاد في الجرح \"البكرى\". وفى التقريب (٢/ ٣٤٥) يحيى بن حسان الفلسطينى، البكرى، ثقة، من الخامسة. ٢٢٧٥ - الجرح (٤/ ٢/ ٤٢٣)، الثقات (٧/ ٦٦٠)، اللسان (٧/ ٩٠) وقال مجهول. ثم قال أيضا: وذكر أبو أحمد الحاكم في الكنى عن البخارى أنه حدثه بالوجهين بفتح المهملة وتشديد المثناة الفوقانية آخره موحدة أو بالمعجمة المكسورة والتحتانية الخفيفة آخره مثلثه. وقال أبو القاسم البغوى في ترجمة مغفل بن سيار من معجم الصحابة في رواية أبى غياث من روايته عن سلام ابن مسكين عن الحسن عن مغفل أبو غياب مجهول. اهـ.\nفي الاكمال (٦/ ١٣١) غِيَاث، بكسر الغين المعجمة وبعدها ياء معجمة بأثنتين من تحتها وآخره ثاء معجمة بثلاث. ٢٢٧٦ - الجرح (٤/ ٢/ ٤٢٢)، الثقات (٥/ ٥٦٧)، الميزان (٤/ ٥٦١)، وقال: لا يدرى من هو، قال الدارقطنى: مجهول، والظاهر أنه أبو غطفان بن طريف المرى، وماذا بالمجهول، وثقة غير واحد. اهـ. اللسان (٧/ ٩٠)، التهذيب (١٢/ ١٩٩)، التقريب (٢/ ٤٦١) وقال: قيل: اسمه سعد، ثقة، من كبار الثالثة./ م. د. س. ق.\nغطفان. بفتحات. كما في التقريب (٢/ ٤٦١).\nفي اللسان \"المزى\" بالزاى المعجمة. وجزم ابن حجر في التقريب بأنه ="}],[3542,"٢٢٧٧ - أبو غُطَيْف الهذلى. سمع ابن عمر عن النبى عليه السلام في الوضوء لكل صلاة (٥). روى عنه عبد الرحمن بن زياد الافريقى. قال أبو زرعة: لا أعرف اسمه.","",{"fn":"مدنى، ضعيف، من السادسة. التقريب (٢/ ٥٣).\nقارظ آخره معجمة، ابن شيبة بن قارظ، الليثى، المدنى، حليف بنى زهرة، لا بأس به، من الثالثة. التقريب (٢/ ١١٥).\nفي الثقات \"كان لأبى غطفان دار بالمدينة عند دار عمر بن عبد العزيز كما هنا.\nالتاريخ (٢/ ٧٢٠). ٢٢٧٧ - الجرح (٤/ ٢/ ٤٢٢) وقال: سئل أبو زرعة عن اسمه فقال: لا أعرف اسمه، تهذيب الكمال (٣/ ١٦٣٦)، المقتنى في سرد الكنى (١٠٩/ ب)، الميزان (٤/ ٥٦١)، وقال: روى عنه الافريقى حديث الوضوء لكل صلاة. قال البخارى: لم يتابع عليه، التهذيب (١٢/ ١٩٩ - ٢٠٠)، التقريب (٢/ ٤٦١) وقال: أبو غطيف بالتصغير، الهذلى، مجهول، من الثالثة وقيل: هو غطيف أو غضيف، بالضاد المعجمة./ ت. د. ق.\nالحديث أخرجه أبو داود \"الطهارة\" باب الرجل يجدد الوضوء من غير حدث (١/ ١٦)، والترمذى \"الطهارة\" باب ما جاء في الوضوء لكل صلاة ١/ ١٩٢، وفى باب ما جاء أنه يصلى الصلوات بوضوء واحد (١/ ١٩٦)، وابن ماجه \"الطهارة\" باب الوضوء على الطهارة (١/ ١٧٠ - ١٧١)، وابن عبد البر في الاستذكار (١/ ١٩٨)، والمزى في تهذيب الكمال (٣/ ١٦٣٦) كلهم أخرجوه من طريق عبد الرحمن بن زياد عن أبى غطيف - وعند أبى ="}],[3543,"٢٢٧٨ - أبو الغازى العنسى، روى عن أبى امامة عن النبى -صلى الله عليه وآله وسلم- \"في خيار الناس\" (١). روى عنه عبد الرحمن بن زياد بن انعم الافريقى ثم الشيبانى المعافرى.","",{"fn":"الحديث ذكره ابن أبى حاتم في الجرح (٤/ ٢/ ٤٢٢) كما هنا، وذكر الحافظ المناوى في الجامع الأزهر في حديث النبى الانور (١/ ١٢٧/ أ) حديثا لأبى أمامة قال: \"خياركم من تعلم القرآن وعلمه\" وعزاه للطبرانى في الكبير وقال: فيه على بن أبى طالب البزار ضعفه ابن معين وابن عدى."}],[3544,"حرف الفاء"],[3545,"باب أبى فاطمة"],[3546,"٢٢٧٩ - أبو فاطمة بصرى، روى عن أنس عن النبى عليه السلام \"من صلى الفجر في جماعة ثم جلس في مصلاه يدعو ربه حتى تطلع الشمس كان له من الاجر مثل زبد البحر\" (١). من حديث موسى بن إسماعيل، عن القاسم بن القاسم أبى هاشم البصرى عنه.","",{"fn":"الحديث لم أقف عليه من هذا الطريق ولكن أخرجه الترمذى \"الجمعة\" باب الجلوس بعد صلاة الصبح حتى تطلع الشمس، ٣/ ١٩٣ من حديث أنس قال: قال رسول اللَّه -صلى الله عليه وآله وسلم- \"من صلى الصبح في جماعة ثم قعد يذكر اللَّه حتى تطلع الشمس ثم صلى ركعتين، كانت له كأجر حجّة وعمرة\". قال: قال رسول اللَّه -صلى الله عليه وآله وسلم- \"تامة، تامة، تامة\". وقال الترمذى: هذا حديث حسن غريب. وذكره المنذرى في الترغيب والترهيب (١/ ٢٣٤) وعزاه للترمذى، وللحديث شواهد في الصحيح منها ما أخرجه مسلم \"المساجد\" باب فضل الجلوس في مصلاه بعد الصبح وفضل المساجد (١/ ٤٦٣) من حديث سماك بن حرب قال: قلت لجابر ابن سمرة: أكنت تجالس رسول اللَّه -صلى الله عليه وآله وسلم-؟ قال: نعم. كثيرا. كان لا يقوم من مصلاه الذى يصلى فيه الصبح أو الغداة حتى تطلع الشمس فإذا طلعت الشمس قام. وأخرج مسلم أيضا (١/ ٤٦٤) من حديث جابر بن سمرة أن النبى -صلى الله عليه وآله وسلم- كان إذا صلى الفجر جلس في مصلاه حتى تطلع الشمس حسنا. وما أخرجه أحمد في المسند (٣/ ٤٣٩) من حديث سهل بن معاذ ="}],[3547,"٢٢٨٠ - أبو فاطمة، روى عن ابن سيرين قوله، روى عنه أبو نعيم."],[3548,"٢٢٨١ - أبو فاطمة، روى عن أبى معشر، روى عنه الربيع بن صبيح. قال ابن أبى حاتم: سألت عنه أبى فقال: هو شتى بابة الوصّافى (١).","",{"fn":"قلت: والوصافى، هو عبيد اللَّه بن الوليد الوصافى من ولد الوصاف بن عامر العجلى ذكره ابن أبى حاتم في الجرح (٢/ ٢/ ٣٣٦ - ٣٣٧) وقال: قال أحمد بن حنبل: ليس بمحكم الحديث، يكتب حديثه للمعرفة. سئل عنه يحيى بن معين فقال: ضعيف الحديث. . قال عمرو بن على متروك الحديث. ثم قال ابن أبى حاتم: سألت أبى عن عبيد اللَّه بن الوليد الوصافى فقال: ضعيف الحديث، وسئل عنه أبو زرعة فقال: كوفى ضعيف. اهـ."}],[3549,"باب أبى الفضل"],[3550,"٢٢٨٢ - أبو الفضل يباع الخمر (١). قال جاءنا أنس بن مالك. روى عنه الحسن بن أبى يزيد (٢)."],[3551,"٢٢٨٣ - أبو الفضل روى عن عبد اللَّه بن مسعود روى عنه جِسُر بن فرقد (٣)."],[3552,"٢٢٨٤ - أبو الفضل، قال: جاءنا كتاب عمر بن عبد العزيز إلى عدى بن أرطاة. من حديث محمد بن المثنى أبى موسى عن حماد بن بشير (٤) عنه."],[3553,"قال أبو أحمد الحاكم: قد أخرجنا أبا الفضل خلف القرشى عن كتاب عمر ابن عبد العزيز (١) فلا أدرى. وخليفا أن يكون واحدا. واللَّه أعلم.","",{"fn":"زاد في الجرح \"والبرود\".\nذكره ابن أبى حاتم في الجرح (١/ ٢/ ٤٥) فقال: الحسن بن أبى يزيد الهمدانى الكوفى روى عن الشعبى وأبى الفضل بياع الخمر. . الخ ولم يذكر فيه شيئا. ٢٢٨٣ - الميزان (٤/ ٥٦٢) وقال: مجهول. اللسان (٧/ ٩٢)، المقتنى في سرد الكنى (١١٢/ ب) وقال: أبو الفضل عن ابن مسعود وعنه جسر بن فرقد. اهـ.\nجِسْر، بكسر الجيم وبالسين المهملة، ابن فرقد، أبو جعفر القصاب، قال ابن معين: لا شئ، وقال أبو حاتم: ليس بالقوى، كان رجلا صالحا، انظر الاكمال (٢/ ١٠٠)، الجرح (١/ ١/ ٥٣٨ - ٥٣٩)، اللسان (٢/ ١٠٤) ٢٢٨٤ - الجرح (٤/ ٢/ ٤٢٤)، المقتنى في سرد الكنى (١١٢/ ب) وذكره بنحو ما ذكره ابن عبد البر هنا.\nحماد بن بشير الجهضمى أبو عبد اللَّه البصرى، لين الحديث، من العاشرة، التقريب (١/ ١٩٦)، التهذيب (٣/ ٤)."}],[3554,"٢٢٨٥ - أبو الفضل، عن سنان بن أبى منصور (٢) مولى واثلة عن واثلة بن الأسقع قال: سمعت النبى عليه السلام يقول: \"من دفن ثلاثة من الولد يحتسبهم حرمه اللَّه على النار\" (٣).","",{"fn":"أخرج ابن الجوزى في سيرة عمر بن عبد العزيز (ص ٥٥ - ٥٦) من طريق سليمان بن نفيع القرشى عن خلف أبى الفضل القرشى عن كتاب عمر بن عبد العزيز إلى نفر كتبوا بالتكذيب بالقدر: \"أما بعد فقد علمتم أن أهل السنة كانوا يقولون الاعتصام بالسنة نجاة وسينقص العلم نقصا سريعا. . إلخ وهو حديث طويل. ٢٢٨٥ - الجرح (٤/ ٢/ ٤٢٤) وقال: سمعت أبى يقول: هما مجهولان أبو الفضل وسنان بن أبى منصور. الميزان (٤/ ٥٦٢) وقال: مجهول، ديوان الضعفاء (ص ٣٦٣)، اللسان (٧/ ٩٢)، المقتنى في سرد الكنى.\nسنان بن أبى منصور ذكره ابن أبى حاتم في الجرح (٢/ ١/ ٢٥٢) وقال: سنان بن أبى منصور، ويقال: ابن أبى منصور شامى مولى واثلة بن الأسقع. وذكر رواية أبى الفضل عنه. ولم يذكر فيه شيئا، لكن تقدم في ترجمة أبى الفضل في مصادر انترجمة قول أبى حاتم بأنه مجهول كما سبق وأن عرفت. وانظر ترجمته أيضا في التاريخ الكبير (٢/ ٢/ ١٦٤).\nالحديث أخرجه الطبرانى في الكبير، عن سنان مولى واثلة قال: توفى ولد الريان وشهده واثلة فلما انصرفوا من المقبرة قعد واثلة على باب دمشق فمر به الريان فقال له واثلة: يا أبا سعيد جبر اللَّه مصيبتك وغفر لمتوفاك إنى سمعت رسول اللَّه -صلى الله عليه وآله وسلم- يقول: \"من دفن ثلاثة من الولد حرم اللَّه عليه النار\" مجمع الزوائد (٣/ ٧) وقال الهيثمى سنان مجهول. وعزاه أيضا السيوطى في الصغير (٢/ ١٧١) إلى الطبرانى في الكبير ورمز لحسنه. قلت: والحديث مخرج في الصحيحين من حديث غير واحد من الصحابة رضي الله عنهم كأبى هريرة وأبى سعيد الخدرى. انظر البخارى \"الجنائز\" باب فضل من مات له ولد فاحتسبه (٣/ ١١٨)، ومسلم \"البر ="}],[3555,"روى عنه أبو عبد الرحيم خالد بن أبى يزيد (١) قال أبو حاتم: أبو الفضل وسنان هذا مجهولان."],[3556,"٢٢٨٦ - أبو الفضل، روى عن نافع، روى عنه أبان المكتب (٢)."],[3557,"٢٢٨٧ - أبو الفضل. روى عن راشد بن سعد الحبرانى. روى عنه عنبسة ابن سعيد أخو أبى الربيع السمان."],[3558,"٢٢٨٨ - أبو الفضل، روى عن مكحول، روى عنه بقية بن الوليد هو عندهم مجهول.","",{"fn":"خالد بن أبى يزيد بن سماك بن رستم أبو عبد الرحيم الحرانى، ثقة، من السادسة (ت: ١٤٤). التقريب (١/ ٢٢١). ٢٢٨٦ - الميزان (٤/ ٥٦٣) وقال: مجهول، ديوان الضعفاء (ص ٣٦٣)، اللسان (٧/ ٩٢)، المقتنى في سرد الكنى (١١٣/ أ).\nابان بن بشير المكتب. ذكره ابن أبى حاتم في الجرح (١/ ١/ ٢٩٩)، ولم يذكر فيه شيئا. ٢٢٨٧ - الجرح (٤/ ٢/ ٤٢٥) وقال: سألت أبى عنه فقال: هو مجهول. الميزان (٤/ ٥٦٢) وقال: مجهول، اللسان (٧/ ٩٢)، المقتنى في سرد الكنى (١١٣/ أ). ٢٢٨٨ - الجرح (٤/ ٢/ ٤٢٥) وقال: سألت أبى عنه فقال: هو شيخ مجهول، الميزان (٤/ ٥٦٣) وقال: مجهول، اللسان (٧/ ٩٢)."}],[3559,"باب أبى فروة"],[3560,"٢٢٨٩ - أبو فروة، قال على بن المدينى: أبو فروة من أصحاب عبد اللَّه وهو كنانى."],[3561,"٢٢٩٠ - أبو فروة مولى أنس بن مالك، سمع أنسا، روى عنه جرير بن حازم."],[3562,"٢٢٩١ - أبو فروة وقيل: أبو قرة مولى عبد الرحمن بن الحارث بن هشام المخزومى (١). روى عن أبى بكر الصديق."],[3563,"٢٢٩٢ - أبو فروة. روى عن عائشة أنها قالت: \"من قتل وزغة فله سبع حسنات\" (٢) روى عنه معاوية بن صالح.","",{"fn":"له رؤية، وكان من كبار ثقات التابعين (ت: ١٤٣)./ خ. عـ. التقريب (١/ ٤٧٦). ٢٢٩٢ - الجرح (٤/ ٢/ ٤٢٥)، المقتنى في سرد الكنى (١١١/ أ).\nالحديث أخرجه الطبرانى في الأوسط من حديث عائشة مرفوعا قالت: سمعت رسول اللَّه -صلى الله عليه وآله وسلم- يقول: \"من قتل وزغة محا اللَّه عنه سبع خطيئات\" كما في مجمع الزوائد (٤/ ٤٧) وقال الهيثمى: فيه عبد الكريم بن أبى المخارق وهو ضعيف. وعزاه السيوطى في الجامع الصغير (٢/ ١٧٧) أيضا للطبرانى في الأوسط من حديث عائشة رضي الله عنها ورمز لحسنه. وأخرجه أحمد (٦/ ٨٣ و١٠٩ و٢٠٠ و٢١٧) وابن ماجه \"الصيد\" باب قتل الوزغ (٢/ ١٠٧٦) بلفظ \"أن سائبة مولاة الفاكه بن المغيرة ="}],[3564,"٢٢٩٣ - أبو فروة، سمع أبا ذر الغفارى، قوله، روى عنه معاوية بن صالح، قال الحاكم: أراه الذى قبله."],[3565,"باب أبى فزاوة"],[3566,"٢٢٩٤ - أبو فزارة قال: سألت ابن عباس، روى عنه أبو اسحاق الهمدانى."],[3567,"٢٢٩٥ - أبو فزارة، سمع أنس بن مالك، روى عنه يعلى بن عطاء."],[3568,"٢٢٩٦ - أبو فزارة العنزى (١) وكان شيعة لعلى رضي الله عنه روى عن على. روى عنه عاصم الأحول قال ابن أبى حاتم: سمعت أبى يقول: هو شيخ ليس بالمشهور وقد ادخله البخارى في الضعفاء (٢) وليس مثله يدخل في الضعفاء ولم (. . . .) (٣) وسمعت أبى يقول: يحول من هناك."],[3569,"٢٢٩٧ - أبو فزارة العبسى (. . . . .) (٤) روى عنه الثورى. قال أبو أحمد الحاكم: قد أخرجنا أبا فزارة راشد بن كيسان. روى عنه الثورى فلا أدرى أهما اثنان أو واحد. وقد جعلهما البخارى اثنين (١). وخليقا أن يكون واحدا. واللَّه أعلم.","",{"fn":"في اللسان \"العنبرى\".\nلم أقف عليه في الضعفاء الصغير ولعله في الضعفاء الكبير. واللَّه أعلم.\nغير واضح في الأصل، وهو بمقدار كلمة أو كلمتين. ولعل العبارة كالآتى \"ولم أر من ضعفه\" واللَّه أعلم. ٢٢٩٧ - المقتنى في سرد الكنى (١١١/ ب) وقال: أبو فزارة العبسى عن مسقلة بن مالك هو راشد. اهـ. الثقات (٧/ ٦٦١) وقال: أبو فزارة العبسى كوفى، عن رقية بن مالك روى عنه الثورى. وقال محقق الثقات في هامش نفس الورقة: إن لم يكن راشد بن كيسان العبسى أبو فزارة الكوفى فلم ندر من هو. اهـ. وقد تقدم أبو فزارة راشد بن كيسان في \"الكتاب الثانى\" (١٠٥٢).\nبياض في الأصل بمقدار ثلاث كلمات."}],[3570,"٢٢٩٨ - أبو الفيض (٢)، روى عن نافع، عن ابن عمر أن النبى عليه السلام شد على أصبعه خيطا يتذكر به (٣)، روى عنه عبد اللَّه بن ادريس، قال يحيى بن معين: ليس بشئ."],[3571,"٢٢٩٩ - أبو الفيض العقيلى، من بنى عقيل، روى عنه ابن أبى أنيسه (٤).","",{"fn":"انظر التاريخ الكبير (٢/ ١/ ٢٩٦ - ٢٩٧) في أبى فزارة العبسى راشد بن كيسان. ٢٢٩٨ - الجرح (٤/ ٢/ ٤٢٥) وقال: قال يحيى بن معين: ليس بشئ. الميزان (٤/ ٥٦٣) وقال: قال ابن معين: ليس بشئ. اللسان (٧/ ٩٤) وقال: اسمه سالم بن عبد الأعلى.\nهكذا ذكر المؤلف أبا الفيض بعد أبى فزارة مباشرة، ولم يعنون له في باب كما هى عادته. واللَّه أعلم.\nالحديث لم أقف عليه من حديث ابن عمر: وقد أخرجه الطبرانى في المعجم الكبير كما في مجمع الزوائد (١/ ١٦٦) من حديث رافع بن خديج قال: رأيت في يد رسول اللَّه -صلى الله عليه وآله وسلم- خيطا فقلت: ما هذا؟ قال استذكر به. وقال الهيثمى: في سنده غياث بن إبراهيم وهو ضعيف جدا. اهـ. ٢٢٩٩ - المقتنى في سرد الكنى (١١٣/ ب).\nفي المقتنى \"زهير بن أبى أنيسة\"."}],[3572,"باب الافراد الكنى الشتى"],[3573,"٢٣٠٠ - أبو فراس (١) النهدى قال: شهدت خطبة عمر بن الخطاب (٢). روى عنه أبو نضرة. قال الحاكم: قال اسحاق بن راهويه: أبو فراس هذا هو الربيع بن زياد الحارثى (٣) وما أظن اسحاق حفظ ذلك أن كان سمعه وربما سماه من قبل نفسه (١). وقد قال خليفه بن خياط: الربيع بن زياد الحازى كنيته أبو عبد الرحمن (٢) قال: ولا أعرف لأبى نضرة رواية عن الربيع بن زياد وإنما روى عنه أبو مجلز وقتادة وقد روى عنه الشعبى خبرا ذكره عنه، وأبو فراس هذا هو النهدى والربيع بن زياد حازى وما اظن إسحاق إلا وهم. واللَّه أعلم (٣). وقد ذكره البخارى (٤) كما ذكره إسحاق، فلم يصنع شيئا.","",{"fn":"فراس: بكسر الفاء وتخفيف الراء. الاكمال (٧/ ٥٧).\nالخطبة أخرجها أبو داود \"الديات\" باب القود من الضربة، وقص الأمير من نفسه (٤/ ١٨٣)، والنسائى \"القسامة\" باب القصاص من السلاطين (٨/ ٣٤) وأحمد في المسند (١/ ٤١) كلهم أخرجوه من طريق سعيد بن اياس الجريرى، عن أبى نضرة، عن أبى فراس قال: خطبنا عمر بن الخطاب رضي الله عنه فقال: \"انى لم ابعث عمالي ليضربوا ابشاركم. ولا ليأخذوا أموالكم، فمن فعل به ذلك فليرفعه إلى أقصه منه، قال عمرو بن العاص: لو أن رجلا ادب بعض رعيته اتقصّه منه؟ قال: اى والذى نفسى بيده، أقصّه، وقد رأيت رسول اللَّه -صلى الله عليه وآله وسلم- من نفسه\". هذا لفظ أبى داود، وأخرجه أحمد مطولا، والنسائى بنحو هذا اللفظ.\nالربيع بن زياد الحارثى أبو فراس، مخضرم من الثانية، التقريب (١/ ٢٤٤) وانظر التهذيب (٣/ ٢٤٣)."}],[3574,"٢٣٠١ - أبو فِهْر (٥). قال: صلّيت خلف الزهرى شهرا فكان يقرأ ﴿تَبَارَكَ﴾ و﴿قُلْ هُوَ اللَّهُ أَحَدٌ﴾ (٦). روى عنه جرير بن عبد الحميد وجرير بن حازم.","",{"fn":"انظر قول الحاكم في تهذيب الكمال (٣/ ١٦٣٧).\nانظر طبقات خليفة بن خياط (ص ٢٢).\nتهذيب الكمال (٣/ ١٦٣٧) حيث ذكر كلام الحاكم بتمامه.\nانظر التاريخ الكبير (٢/ ١/ ٢٦٨) حيث ذكر ترجمة ربيع بن زياد ولم يكنه. قلت: وقد فرق ابن ماكولا في الاكمال (٧/ ٥٧) بين أبى فراس عن عمر ابن الخطاب وعنه أبو نضرة. وبين أبى فراس الربيع بن زياد الحارثى. ٢٣٠١ - الجرح (٤/ ٢/ ٤٢٥)، المقتنى في سرد الكنى (١١٣/ أ)، اللسان (٧/ ٩٣) وقال: ذكره الحاكم أبو أحمد فيمن لا يعرف اسمه وذكر عن البخارى أنه قال: حدثنا جرير بن حازم عن أبى فهر صليت. . فذكره، وأخرج الخطيب في كتابه من طريق ابن غسان عن جرير عن أبى فهر قال: صليت خلف الزهرى. . مثله. وزاد \"في صلاة الفجر\" وزاد \"قيل لجرير من أبو فهر؟ قال: لعن كان يسكن الرى. فقيل له: يروى عن اللصوص؟ قال: نعم كان مع بعض السلاطين وجرير هذا هو ابن عبد الحميد فكان كلا الجريرين رويا عن أبى فهر، ولم أر له ذكرا إلا في هذا الأثر\". اهـ. وانظر أيضا الكفاية ص ١٥٣.\nفهر: بكسر الفاء وآخره راء. الاكمال (٧/ ٧٧).\nالأثر أخرجه البخارى في الكنى، والحاكم في الكنى والخطيب في التاريخ كما في اللسان (٧/ ٩٣)، وأخرجه أيضا أبو نعيم في الحلية (٣/ ٣٧٠) وابن ="}],[3575,"٢٣٠٢ - أبو فرقد (١) سمع أبا موسى الاشعرى. روى عنه مرزوق بن عمرو (٢)."],[3576,"٢٣٠٣ - أبو الفرج (٣)، مولى عمر بن عبد العزيز، روى عن عمر بن عبد العزيز حكايات كثيرة، قال ابن أبى حاتم: سمعت أبا زرعة يقول: قدم علينا الرى شيخ يقال له: أبو الفرج مولى عمر بن عبد العزيز. فكان يحدث عن عمر ابن عبد العزيز حكايات كثيرة وكان يكذب (٤)."],[3577,"٢٣٠٤ - أبو الفضة، سمع أنس بن مالك عن النبى عليه السلام قال: لعقبة ابن أبى معيط: \"لاقتلنك. قال: من بين قريش؟ قال: نعم تذكر يوم وطئت على عنقى\" (٥). روى عنه أبو سعيد مولى بنى هشام.","",{"fn":"فرقد: أوله فاء وآخره، دال مهملة، الاكمال (٧/ ٦٢).\nمرزوق بن عمرو، ذكره ابن أبى حاتم في الجرح (٤/ ١/ ٢٦٥) فقال: مرزوق ابن عمرو أبو حكيم جد ريحان بن سعيد الناجى، وذكر روايته عن أبى فرقد ولم يذكر فيه شيئا. ٢٣٠٣ - الجرح (٤/ ٢/ ٤٢٦)، ديوان الضعفاء (ص ٣٦٣)، الميزان (٤/ ٥٦١) وقال: قال أبو زرعة: كان يكذب. اللسان (٧/ ٩٢).\nفرج: بالفتحات والجيم، الاكمال (٧/ ٥٥).\nانظر الجرح (٤/ ٢/ ٤٢٦). ٢٣٠٤ - الجرح (٤/ ٢/ ٤٢٦)، المقتنى في سرد الكنى (١١٣/ أ)، اللسان (٧/ ٩٣) وقال: مجهول.\nالخبر أخرجه الواقدى في المغازى (١/ ١١٤) بنحوه وذكر ابن قتيبة في المعارف (ص ١٥٥) أن الرسول -صلى الله عليه وآله وسلم- قتل عقبة بن أبى معيط بالصفراء بعد معركة بدر. وفى طبقات ابن سعد (٢/ ١٨) أنه قتله صبرا بالصفراء. ="}],[3578,"٢٣٠٥ - أبو الفرات، روى عن عبد اللَّه بن مسعود، ما أخاف عليكم الفقر ولكنى أخاف عليكم الغنى (١)، روى عنه فضيل بن غزوان، (قال أبو أحمد الحاكم: وقد روى فضيل بن غزوان) (١)، عن شداد (بن أبى العالية أبى الفرات) (٢)، عن أبى داود الاحمرى، عن حذيفة، فلا أدرى أهما اثنان أو واحد. (. . . . . . . . .) (٣) فضيل بن غزوان، وربما ارسل أبو الفرات حديثه، عن عبد اللَّه وهما واحد. واللَّه أعلم.","",{"fn":"الحديث لم أقف عليه من حديث ابن مسعود بهذا اللفظ، لكن ذكر الهيثمى في مجمع الزوائد في كتاب \"الزكاة\" (٣/ ١٢٢) حديثا عن ابن مسعود يرفعه \"أن هذا الدينار والدرهم اهلكا من كان قبلكم ولا أراهما إلا مهلكاكم\" وقال الهيثمى: رواه الطبرانى في الكبير، وفيه يحيى بن المنذر وهو ضعيف. ثم ذكر الهيثمى أيضًا في مجمع الزوائد كتاب \"الزهد\" (١٠/ ٢٣٧) حديثا عن ابن مسعود انه كان يعطى الناس عطاءهم فجاءه رجل فأعطاه الف درهم ثم قال: خذها فافنى سمعت رسول اللَّه -صلى الله عليه وآله وسلم- يقول: \"أنما أهلك من كان قبلكم الدينار والدرهم وهما مهلكاكم\" وقال الهيثمى: رواه البزار واسناده جيد. ويشهد للحديث حديث أبى هريرة رضي الله عنه أخرجه أحمد (٢/ ٣٠٨، ٥٣٩) قال: قال -صلى الله عليه وآله وسلم- ما أخشى عليكم الفقر ولكن أخشى عليكم =\nالحق في هامش الأصل. كتب عنده \"صح أصل\".\nفي الأصل غير واضح وهو في ترجمة أبى داود الاحمرى المتقدم في (٦٦٩) وفى ترجمة أبى الفرات شداد بن أبى العالية المتقدم في (١٠٤٨) كما أثبته هنا. واللَّه أعلم.\nفي الأصل بياض بمقدار كلمة أو كلمتين."}],[3579,"حرف القاف"],[3580,"باب أبى القاسم"],[3581,"٢٣٠٦ - أبو القاسم، مولى زينب بنت جحش، روى عن زينب بنت جحش، روى عنه (١)."],[3582,"٢٣٠٧ - أبو القاسم الحمصى، روى عن عمرو بن قيس السّكونى، روى عنه سعيد بن أبى أيّوب."],[3583,"٢٣٠٨ - أبو القاسم الضرير، روى عن عبد العزيز بن (٢) الماجشون. روى عنه محمد بن حرب النَّشائى (٣).","",{"fn":"هكذا قال ابن عبد البر هنا \"روى عنه\" ولم يذكر من روى عنه وفى الجرح ذكر أنه روى عنه حدمر. وفى الجرح (١/ ٢/ ٣١٧) ذكر ابن أبى حاتم حدمر مولى بنى عبس روى عن أبى القاسم مولى زينب روى عنه ليث بن أبى سليم. وانظر التاريخ الكبير (٢/ ١/ ١٣١). والكنى لابن منده (٨/ ب). ٢٣٠٧ - الجرح (٤/ ٢/ ٤٢٦)، كنى ابن منده، المقتنى في سرد الكنى (٥/ أ). ٢٣٠٨ - الجرح (٤/ ٢/ ٤٢٧) وقال: سئل أبو زرعة عنه فقال: لا أدرى من هو منكر الحديث. الميزان (٤/ ٥٦٣)، اللسان (٧/ ٩٤)، كنى ابن منده (٨/ ب) وقال: أبو القاسم الضرير المكتب جار عبيدة بن حميد.\nزاد في اللسان \"أبى سلمة الماجشون\".\nصدوق، من العاشرة (ت: ٢٥٥). والنشائى: بفتح النون والشين وبعد الألف ياء تحتها نقطتان نسبة إلى النشا واشتهر بهذه النسبه أبو عبد اللَّه محمد بن حرب الواسطى انظر التقريب (٢/ ١٥٣) اللباب (٣/ ٣٠٩)."}],[3584,"٢٣٠٩ - أبو القاسم بن أبى الزناد، أخو عبد الرحمن بن أبى الزناد، روى عن إسحاق بن حازم (١)، وافلح بن حميد، وإبراهيم بن إسماعيل بن أبى حبيبة (٢)، روى عنه أحمد بن حنبل، وسعيد بن يحيى بن سعيد الأموى (٣). ذكر أبو بكر الأثرم (٤) قال: سمعت أحمد بن حنبل ذكر أبا القاسم ابن أبى الزناد فأثنى عليه وقال: كتبنا عنه وهو شاب (٥). وقال عباس: سئل يحيى بن معين عن أبى القاسم بن أبى الزناد فقال: ليس به بأس قد سمع منه أحمد (٦). سئل أبو زرعة عن أبى القاسم بن أبى الزناد فقال: (ليس به بأس قد سمع منه أحمد) (٧) سئل أبو زرعة عن أبى القاسم بن أبى الزناد فقال: اسمه كنيته لا يعرف له اسم.","",{"fn":"اسحاق بن حازم. وقيل: ابن أبى حازم، البزاز المدنى، صدوق، تكلم فيه للقدر، من السابعة. التقريب (١/ ٥٧).\nمدنى ضعيف من السابعة (ت: ١٦٥). التقريب (١/ ٣١).\nبغدادى، ثقة، ربما أخطأ، من العاشرة (ت: ٢٤٩)، التقريب (١/ ٣٠٨).\nأبو بكر الأثرم: واسمه أحمد بن محمد بن هانئ، من أصحاب أحمد بن حنبل، وهو من أهل اسكاف بنى جنيد، له من الكتب كتاب السنن في الفقه على مذهب أحمد وشواهده من الحديث وكتاب التاريخ، وكتاب العلل وكتاب الناسخ والمنسوخ في الحديث. انظر الفهرست لابن النديم (ص ٣٢٠ - ٣٢١).\nانظر الجرح (٤/ ٢/ ٤٢٧)، تاريخ بغداد (٤/ ١/ ٣٩٩).\nالتاريخ (٢/ ٧٢٠).\nليس في مطبوعة الجرح، والظاهر أنه سبق قلم من الناسخ، إذ الملاحط أنه ="}],[3585,"باب أبى قرة"],[3586,"٢٣١٠ - أبو قرّة (١)، روى عن سلمان، روى عنه أبو إسحاق السبيعى، حديثه في الكوفيين."],[3587,"٢٣١١ - أبو قرة، مولى بنى أبى جهل بن هشام، روى عن أبى هريرة، روى عنه أبو الأسود محمد بن عبد الرحمن يتيم عروة."],[3588,"٢٣١٢ - أبو قرة مولى عبد الرحمن بن الحارث بن هشام. قال: قسم لى أبو بكر. روى عنه (٢).","",{"fn":"في الثقات زيادة \"الكندى\". ٢٣١١ - الجرح (٤/ ٢/ ٤٢٨). ٢٣١٢ - تقدم أبو قرة هذا في أبى فروة. وقال ابن عبد البر في ترجمته هناك (٢٢٩١): أبو فروة. وقيل: أبو قرة. وذكر روايته عن أبى بكر الصديق رضي الله عنه. وانظر ترجمة أبى قرة أيضا في الجرح (٤/ ٢/ ٤٢٧)، المقتنى في سرد الكنى (١١٤/ ب). وذكره ابن عبد البر أيضا في الاستيعاب (٤/ ١٥٧) في حرف الفاء فقال: أبو فروة مولى عبد الرحمن بن هشام كان مسلما على عهد رسول اللَّه -صلى الله عليه وآله وسلم-، ذكر الواقدى عنه أنه قال: قسم أبو بكر قسما فقسم لى كما قسم لمولاى. اهـ. وذكره ابن حجر في الإصابة (٤/ ١٦٠) فقال: أبو قرة مولى عبد الرحمن بن الحارث بن هشام المخزومى. . ويقال: أبو فروة بفتح الفاء وسكون الراء بعدها واو، ثم ذكر قول ابن عبد البر في الاستيعاب وقال: أوره أبو عمر في حرف الفاء، واورده أبو أحمد الحاكم في حرف القاف وهو أولى. اهـ.\nهكذا قال ابن عبد البر هنا \"روى عنه\" ولم يسم الراوى عنه وكذا هو في الجرح لابن أبى حاتم."}],[3589,"٢٣١٣ - أبو قرة الاسدى، الصيداوى (١)، من أهل البادية، سمع سعيد بن المسيب، روى عنه النضر بن شميل."],[3590,"٢٣١٤ - أبو قرة، سمع عطاء، روى عنه المبارك بن (حسان) (٢)."],[3591,"٢٣١٥ - أبو قرة بصرى، روى عن ابن سيرين، روى عنه يزيد بن ميمون (٣)."],[3592,"٢٣١٦ - أبو قرة العبسى بصرى سمع الحسن بن أبى الحسن. وسمع عروبة العابد، روى عنه الضحاك بن مخلد أبو عاصم.","",{"fn":"الصيداوى: نسبة إلى صيدا وهى مدينة على ساحل بحر الشام. انظر اللباب (٢/ ٢٥٣). قلت: وصيداء، بالفتح ثم السكون ودال مهملة. انظر مراصد الاطلاع (٢/ ٨٥٩). ٢٣١٤ - الجرح (٤/ ٢/ ٤٢٧)، المقتنى في سرد الكنى (١٢١٤/ ب).\nفي الأصل غير واضح، وهو في الجرح، والمقتنى كما أثبته والمبارك بن حسان السلمى أبو يونس أو أبو عبد اللَّه البصرى، نزيل مكة، لين الحديث من السابعة. التقريب (٢/ ٢٢٧)، الجرح (٤/ ١/ ٣٤٠). ٢٣١٥ - الجرح (٤/ ٢/ ٤٢٨).\nذكره ابن أبى حاتم في الجرح (٤/ ٢/ ٢٩٠) فقال: يزيد بن ميمون قال: نا أبو قرة أنه سأل محمد بن سيرين عن دم البراغيث، روى عنه أبو سلمة. . . سمعت أبى يقول: هو مجهول. ٢٣١٦ - الجرح (٤/ ٢/ ٤٢٧)، المقتنى في سرد الكنى (١١٤/ ب)."}],[3593,"٢٣١٧ - أبو قرة قال: خرج عمر بن عبد العزيز، روى عنه أبو بكر النصرى (١).","",{"fn":"أبو بكر النصرى، هو المتقدم في الترجمة (١٣٧٧) وذكر ابن عبد البر في ترجمته هناك أنه روى عن أبى قرة."}],[3594,"باب أبى قبيصة"],[3595,"٢٣١٨ - أبو قَبِيصة (١)، روى عن الحسن، روى عنه الدراوردى، وسعيد بن أبى أيوب."],[3596,"٢٣١٩ - أبو قبيصة. روى عن عطاء (٢). روى عنه أُمَىَّ (٣) الصيرفى."],[3597,"٢٣٢٠ - أبو قبيصة، عن أنس بن سيرين (٤)، حدث عنه المسيب بن شريك التميمى (٥).","",{"fn":"قبيصة: بمفتوحة كسر موحدة واهمال صاد. المغنى (ص ٦٢). ٢٣١٩ - الجرح (٤/ ٢/ ٤٢٨).\nفي الجرح \"طارق\".\nأمى، الصيرفى، هو ابن ربيعة الصيرفى أبو عبد الرحمن، كوفى روى عن الشعبى وأبى قبيصة وعطاء وطاووس وأبى الهيثم صاحب القصب روى عنه جميع وأبو نعيم، وثقة أحمد، وابن معين وقال أبو حاتم: ما به بأس. الجرح (١/ ١/ ٣٤٧)، وفى التقريب (١/ ٨٣): أمى بالتصغير، وقال أيضا: ثقة، من السابعة. ٢٣٢٠ - المقتنى في سرد الكنى (١١٣/ ب).\nأنس بن سيرين. وهو أخو محمد، ثقة، من الثالثة (ت: ١١٨) وقيل (١٢٠)، التقريب (١/ ٨٤).\nالمسيب بن شريك التميمى أبو سعيد، ذكره ابن أبى حاتم في الجرح (٤/ ١/ ٢٩٤) وقال: سألت أبى عن المسيب بن شريك فقال: ضعيف الحديث كأنه متروك."}],[3598,"٢٣٢١ - أبو قبيصة العنزى بصرى، روى عن يزيد بن زريع، روى عنه عمرو ابن على الصيرفى، قال ابن أبى حاتم: نا عمرو بن على قال: سمعت أبا قبيصة العنزى وكان من الثقات."],[3599,"باب أبى قتادة"],[3600,"٢٣٢٢ - أبو قتادة، روى عن الأوزاعى، وليس هو بأبى قتادة الحرانى سكن بغداد، سمع منه يحيى بن معين، منكر الحديث."],[3601,"٢٣٢٣ - أبو قتادة الشامى، وليس بالحرانى أيضا، سمع عبد اللَّه بن جراد (١).","",{"fn":"هكذا في الأصل \"عبد اللَّه بن جراد\" وفى كنى البخارى \"حوار\" وفى الجرح (٣/ ٢/ ٢١) عبد اللَّه بن جراد، روى عن النبى -صلى الله عليه وآله وسلم-، روى عنه يعلى ابن الاشدق. . قال أبى: عبد اللَّه بن جراد لا يعرف، ولا يصح هذا الاسناد أهـ. وقال ابن عساكر: عبد اللَّه بن جراد بن المنتفق بن عامر بن عقيل العقيلى يقال: أن له صحبة. انظر تهذيب تاريخ دمشق (٧/ ٣٢٦) وذكره الذهبى في التجريد (١/ ٣٠٢) فقال: روى عنه يعلى بن الاشدق، وأبو قتادة الشامى، وقال البخارى له صحبة. وذكره البخارى في التاريخ الكبير (٣/ ١/ ٣٥) وقال: عبد اللَّه بن جراد له صحبة قال لى أحمد بن الحارث، حدثنا أبو قتادة الشامى ليس بالحرانى، مات سنة أربع وستين ومائة. وذكره ="}],[3602,"مات سنة أربع وستين ومائة، روى عنه أحمد بن الحارث الغسّانى (١)."],[3603,"٢٣٢٤ - أبو قتادة، صاحب عمرو بن على الباهلى الصيرفى، سمع عاصما الكُوْزى (٢).","",{"fn":"أحمد بن الحارث الغسانى، ذكره ابن أبى حاتم في الجرح (١/ ١/ ٤٧) وقال: سألت أبى عنه فقال: متروك. ٢٣٢٤ - المقتنى في سرد الكنى (١١٣/ ب).\nالكوزى كما في اللباب (٣/ ١١٧) بضم اولها وسكون الواو وفى آخرها الزاى - نسبة إلى الكوز وعرف بها أبو محمد ويقال: أبو شعيب عاصم بن سليمان التيمى الكوزى العبدى البصرى. وقال في الجرح (٣/ ١/ ٣٤٤) في ترجمة الكوزى هذا: سمعت أبى يقول: أبو شعيب التميمى اسمه عاصم بن سليمان الكوزى ضعيف الحديث متروك الحديث. اهـ."}],[3604,"باب أبى قدامة"],[3605,"٢٣٢٥ - أبو قدامة العمرى، سمع عائشة بنت سعد، روى عنه أبو عامر العقدى، وهشام بن عبيد اللَّه الرازى، وإسماعيل بن أبى اويس."],[3606,"٢٣٢٦ - أبو قدامة الرملى، روى عن عبد العزيز بن قرير (١)، عن الحسن حديثا منكرا. رواه عنه منصور بن عمار (٢).","",{"fn":"عبد العزيز بن قرير، بضم القاف وفتح الراء الأولى وآخره راء أيضا مصغرا، بصرى، ثقة، من السادسة. انظر التقريب (١/ ٥١١)، الجرح (٢/ ٢/ ٣٩٢)، الاكمال (٧/ ١٠٨).\nمنصور بن عمار، ذكره ابن أبى حاتم في الجرح (٤/ ١/ ١٧٦) وقال: سئل أبى عن منصور بن عمار فقال: ليس بالقوى، صاحب مواعظ."}],[3607,"باب أبى قيس"],[3608,"٢٣٢٧ - أبو قيس (١) مولى عمرو بن العاص، روى عنه بسر بن سعيد الحضرمى، وعلى بن رباح، ويزيد بن أبى حبيب، حديثه في أهل مصر."],[3609,"٢٣٢٨ - أبو قيس الدمشقى، عن عبادة بن نسى، روى عنه أبو معاوية الضرير حديثا ليس بالقائم قال الحاكم: وخليقا أن يكون محمد بن سعيد المصلوب.","",{"fn":"في التهذيب زيادة \"السهمى\". ٢٣٢٨ - كنى البخارى (ص ٦٤)، الميزان (٤/ ٥٦٤) وقال: أبو قيس الدمشقى، عن عبادة بن نسى، أظنه المصلوب، هالك، اللسان (٧/ ٩٨) وقال أيضا: أظنه المصلوب، هالك، التهذيب (١٢/ ٢٠٧) وقال: هو محمد بن سعيد المصلوب هكذا كناه أبو معاوية. اهـ."}],[3610,"باب أفراد شتى في الكنى"],[3611,"٢٣٢٩ - أبو قحذم (١)، رأى أبا بكرة صاحب رسول اللَّه -صلى الله عليه وآله وسلم- روى عنه منصور بن زاذان."],[3612,"٢٣٣٠ - أبو قابوس، مولى عبد اللَّه بن عمرو بن العاص مكى، روى عن عبد اللَّه بن عمرو بن العاص، روى عنه عمرو بن دينار."],[3613,"٢٣٣١ - أبو القعقاع الجرمى (٢). روى عن عبد اللَّه بن مسعود روى عنه سلمة بن تمَّام (٣) والحجاج بن ارطاة ذكر أبو أحمد الحاكم قال: ذكر البخارى أبا القعقاع في موضعين في التاريخ الكبير، فسماه مرة، وكناه ونسبه إلى أبيه وقبيلته ولم يبين عمن روى ولا من روى عنه (١) وأخرجه في الكنى المجردة (٢) فذكر كنيته ولم يذكر اسمه ولا قبيلته، فدل على أنه (عنده) (٣) غير الأول، وما أراه إلا رجلا واحدا. واللَّه أعلم.","",{"fn":"قحذم: بفتح القاف والذال المعجمتين. هكذا ضبطه ابن ماكولا في الاكمال (٧/ ١٠١). ٢٣٣٠ - كنى البخارى (ص ٦٤)، الجرح (٤/ ٢/ ٤٢٩)، الثقات (٥/ ٥٨٨)، الميزان (٤/ ٥٦٣) وقال: لا يعرف، تفرد عنه عمرو بن دينار، وذكر خبره \"الراحمون يرحمهم الرحمن\"، اللسان (٧/ ٤٧٩)، التهذيب (١٢/ ٢٠٣) وقال: ذكره البخارى في الضعفاء من الكبير له، ولكنه ذكره في الأسماء فقال: قابوس. أهـ. التقريب (٢/ ٤٦٣) وقال: مقبول من الرابعة./ د. ت. ٢٣٣١ - كنى البخارى (ص ٦٤)، كنى مسلم (ص ٨٣١) وقال: أبو القعقاع الجرمى عبد اللَّه بن خالد، نسبه ابن أبى شيبة منقطع.\nفي كنى البخارى \"الحرامى\".\nسلمة بن تمام، بفتح التاء المثناة من فوقها، وتشديد الميم الشَّقَرى بفتح المعجمة والقاف، ذكره ابن أبى حاتم في الجرح (٢/ ١/ ١٥٧) وذكر روايته عن أبى القعقاع الجرمى، وقال: سمعت أبى يقول: سلمة بن تمام، ثقة صدوق، لا بأس به. وانظر التقريب (١/ ٣١٦)، تبصير المنتبه (١/ ٢٠٣)."}],[3614,"٢٣٣٢ - أبو القمّاص (٤)، روى عن على رضي الله عنه أنه ذكر فتنة التنزيل (٥)، حديثه عند الثورى عن أبيه عن سلمة (شيخ للحى) (٦) عن حَرِيز (٧).","",{"fn":"الذى في التاريخ الكبير (٣/ ١/ ٧٧)، إنما هو عبد اللَّه بن خالد أبو القعقاع الجرمى، هكذا ذكره البخارى. وقال: نسبه ابن أبى شيبة منقطع.\nانظر كنى البخارى (ص ٦٤).\nالحق في هامش الأصل. ٢٣٣٢ - كنى البخارى (ص ٦٤)، الجرح (٤/ ٢/ ٤٢٩)، المقتنى في سرد الكنى (١١٤/ ب) وقال: مجهول.\nالقمّاص، في الاكمال (٧/ ٧٩): قمّاص، أوله قاف، بعده ميم وآخره صاد مهملة أهـ. وضبطه بفتح القاف وتشديد الميم.\nومثله في كنى البخارى والجرح، وزاد في البخارى قال \"نا أبو نعيم عن سفيان عن أبيه عن سلمة شيخ للحى عن جرير عن أبى القماص قال: ذكر على فتنة التنزيل حتى لو كان رجل من أهل الحق في أهل الباطل عليه كذا وكذا من حديد صار إلى أهل الحق، ولو كان رجل من أهل الباطل في أهل الحق كان عليه كذا وكذا من حديد صار إلى أهل الباطل أهـ.\nفي الأصل \"الشيخ المحق\" والمثبت عن مصادر الترجمة، وقال ابن أبى حاتم في الجرح (٢/ ١/ ١٧٨) عن أبيه \"سلمة شيخ للحى روى عن حريز وليس بابن عثمان روى عنه سعيد بن مسروق.\nحريز، أوله حاء مهملة مفتوحة وراء مكسورة وآخره زاى ذكره ابن أبى حاتم في الجرح (١/ ٢/ ٢٨٩)، والبخارى في التاريخ الكبير (٢/ ١/ ١٠٣) وابن ماكولا في الاكمال (٢/ ٨٦) وذكروا روايته عن أبى القماص وعنه سلمة شيخ للحى ولم يذكروا فيه شيئا."}],[3615,"قال الحاكم: أظنه والد غزوان بن جرير (١)."],[3616,"٢٣٣٣ - أبو قَنَان (٢)، مصرى، عن أبى فراس، روى عنه عمرو بن الحارث المصرى، يعد في أهل مصر."],[3617,"٢٣٣٤ - أبو قيلة (٣)، المعافرى. سمع عمر بن الخطاب. روى عنه عبد الرحمن بن (جبريل) (٤).","",{"fn":"غزوان بن جرير الضبى مولاهم الكوفى، مقبول، من السادسة. التقريب (٢/ ١٠٥) وذكر البخارى في التاريخ الكبير (٢/ ١/ ١٠٣) وابن أبى حاتم في الجرح (١/ ٢/ ٢٨٩) وابن ماكولا في الاكمال (٢/ ٨٦) في ترجمة حريز روى عن أبى القماص، قالوا: \"روى حديثه سعيد بن مسروف عن سلمة شيخ للحيى عنه\". ٢٣٣٣ - كنى البخارى (ص ٦٤)، المقتنى في سرد الكنى (١١٤/ ب).\nقنان: بالفتح والنون المحففة تبصير المنتبه (٣/ ١١٣٧). ٢٣٣٤ - الجرح (٤/ ٤٢٨)، الثقات (٥/ ٥٩١)، المقتنى في سرد الكنى (١١٥/ أ).\nهكذا في الأصل \"قيلة\" وفى الجرح \"قافلة\" وفى الثقات \"قتيلة\" وذكر ابن ماكولا (٧/ ١٣٠) باب قيلة بياء معجمة باثنتين من تحتها. وذكر ابن حجر في تبصير المنتبه (٣/ ١١٢٢) قتيلة، بمثناة مصغرا. جماعة ولم يذكر أبا قيلة هذا. فاللَّه أعلم بالصواب.\nهكذا في الأصل \"جبريل\" والذى في مصادر الترجمة \"حيويل\" وذكر ابن أبى حاتم في الجرح (٢/ ٢/ ٢٢٦) عبد الرحمن بن حيويل بن ناشر المعافرى، والد قرة بن عبد الرحمن، روى عن أبى قافلة المعافرى ولم يذكر فيه شيئا. فالظاهر أنه جاء الاسم في الأصل محرفا \"حيويل\" \"بجبريل\". واللَّه أعلم."}],[3618,"٢٣٣٥ - أبو قُبَيْس (١). روى عن مجاهد. روى عنه ايمن بن نابل الحبشى (٢).","",{"fn":"في كنى البخارى، والجرح، والثقات، واللسان \"أبو قبيس\"، وفى الاكمال (٦/ ٩٦) \"أبو قُبَيْس\" بضم القاف وبعدها باء معجمة بواحدة مفتوحة، وانظر تبصير المنتبه (٣/ ١١٢١).\nايمن بن نابل، بنون وموحدة، أبو عمران، ويقال: أبو عمرو الحبشى المكى، نزيل عسقلان، صدوق، يهم من الخامسة. انظر التقريب (١/ ٨٨)."}],[3619,"حرف السين"],[3620,"باب أبى سعيد"],[3621,"٢٣٣٦ - أبو سعيد، مولى أبى أسَيد (١) مالك بن ربيعة الأنصارى، ذكر قتل عثمان، روى عنه أبو نضرة المنذر بن مالك."],[3622,"٢٣٣٧ - أبو سعيد، مولى بنى أمية عن أبى الدرداء، روى عنه عبد اللَّه بن بُجَيْر (٢).","",{"fn":"أسيد، بالتصغير. كما في الإصابة (٤/ ٩٩). ٢٣٣٧ - كنى البخارى (ص ٣٤)، كنى الحاكم (١/ ١٨٣/ ب). المقتنى في سرد الكنى (٦١/ ب).\nعبد اللَّه بن بُجَيْر، بالموحدة والجيم، مصغرا بن حمران التيمى أو القيسى أبو حمران البصرى، ثقة من السادسة. التقريب (١/ ٤٠٣). وانظر الجرح (٢/ ٢/ ١٥)."}],[3623,"٢٣٣٨ - أبو سعيد مولى عبد اللَّه بن عامر بن كريز القرشى (١)، روى عن أبى هريرة، روى عنه صفوان بن سليم، ومحمد بن عجلان، وداود بن قيس، وأسامة ابن زيد، والعلاء بن عبد الرحمن."],[3624,"٢٣٣٩ - أبو سعيد، مولى ابن عبد الرحمن فيما ذكره البخارى ولم يقله غيره. روى عن ابن عباس في الصلاة. حديثه عند الثورى عن فرات القزاز عنه."],[3625,"٢٣٤٠ - أبو سعيد بن أبى المعلى، سمع عليا، وأبا هريرة، سمع منه سلمة ابن وردان."],[3626,"٢٣٤١ - أبو سعيد التيمى قال: رأيت حسين بن على يطوف (وهو القصر) (٢) روى عنه عمار الدهنى.","",{"fn":"عبد اللَّه بن عامر بن كريز صحابى توفى سنة تسع وخمسين. التجريد (١/ ٣٢٠). ٢٣٣٩ - كنى البخارى (ص ٣٤)، وقال: أبو سعيد سمع ابن عباس قال محمد بن يوسف، عن سفيان، عن فرات القزار، الجرح (٤/ ٢/ ٣٧٦)، كنى الحاكم (١/ ١٨٣/ ب) وقال: أبو سعيد مولى ابن عباس، وقال: قاله محمد بن إسماعيل. المقتنى في سرد الكنى (٦١/ ب). ٢٣٤٠ - كنى البخارى (ص ٣٤)، الجرح (٤/ ٢/ ٣٧٥)، كنى الحاكم (١/ ١٨٣/ أ) وقال: أبو سعيد بن المعلى، ويقال ابن أبى المعلى، التهذيب (١٢/ ١٠٨)، التقريب (٢/ ٤٢٧) وقال: مقبول، من الثالثة./ ت. ٢٣٤١ - لم أقف عليه عند غير المؤلف.\nهكذا في الأصل \"وهو القصر\"."}],[3627,"٢٣٤٢ - أبو سعيد (١) مولى عبد اللَّه بن مسعود، روى عن عبد اللَّه بن مسعود، روى عنه أبو يعفور."],[3628,"٢٣٤٣ - أبو سعيد المدنى، سمع ابن عمر، روى عنه بشير بن سلمان."],[3629,"٢٣٤٤ - أبو سعيد مولى المهرى، روى عن ابن عمر، وأبى سعيد الخدرى، روى عنه يحيى بن أبى كثير، وسعيد بن أبى سعيد المقبرى، ويحيى بن أبى إسحاق البصرى، وابنه يزيد (٢) بن أبى سعيد، وعبد الرحمن بن النعمان (٣).","",{"fn":"زاد الحاكم \"الهذلى\". ٢٣٤٣ - كنى البخارى (ص ٣٤)، الجرح (٤/ ٢/ ٣٧٦)، كنى الحاكم (١/ ١٨٣/ ب)، ذكره عن البخارى. وقال: قاله محمد بن إسماعيل، المقتنى في سرد الكنى (٦١/ ب). ٢٣٤٤ - كنى البخارى (ص ٣٥)، كنى مسلم (ص ٤٣٨)، المقتنى في سرد الكنى (٦١/ ب)، الجرح (٤/ ٢/ ٣٧٧)، كنى الحاكم (١/ ١٨٣/ ب)، الثقات (٥/ ٥٨٨)، التهذيب (١٢/ ١١١) وذكر أنه روى عنه ابناه سعيد ويزيد، التقريب (٢/ ٤٢٩)، وقال: مقبول، من الثالثة/ م. د. ت. س.\nفي كنى البخارى والجرح \"سعيد\" وقد ذكر ابن حجر كما تقدم في التهذيب أنه روى عنه ابناه سعيد ويزيد. ويزيد بن أبى سعيد المدنى مولى المهرى، مقبول، من السادسة. كما قال ابن حجر في التقريب (٢/ ٣٦٥).\nعبد الرحمن بن النعمان بن معبد الأنصارى، أبو النعمان الكوفى، صدوق ربما غلط، من السابعة. التقريب (١/ ٥٠١)."}],[3630,"٢٣٤٥ - أبو سعيد صاحب الفساطيط مولى سهيل بن (ذريح) (١). سمع سمرة بن جندب. روى عنه وهب بن إسماعيل (٢)."],[3631,"٢٣٤٦ - أبو سعيد الأزدى كان امامهم (٣). رأى على بن أبى طالب. روى عنه إسماعيل بن سالم."],[3632,"٢٣٤٧ - أبو سعيد التمار (٤) المازنى الأنصارى، روى عن أبى سعيد الخدرى، روى عنه زيد بن اسلم، يعد في أهل المدينة."],[3633,"٢٣٤٨ - أبو سعيد بن عوذ البراد المكى، سمع عبد اللَّه بن الزبير بن العوام، روى عنه أبو نعيم الفضل بن دكين، ويحيى بن المتوكل، ومروان بن معاوية.","",{"fn":"هكذا في الأصل \"ذريح\" ومثله في كنى البخارى، والجرح، والذى في كنى الحاكم \"ذراع\". وفى التقريب (١/ ٣٣٨) سهيل بن ذراع أبو ذراع، الكوفى مقبول، من الثالثة.\nهكذا في الأصل \"روى عنه وهب بن إسماعيل\"، وفى الجرح \"روى وهب ابن إسماعيل عن ابن أبى كبشة عنه\"، ووهب بن إسماعيل بن محمد بن قيس الاسدى، أبو محمد الكوفى، صدوق، من كبار التاسعة، كما في التقريب (٢/ ٢٣٧). وانظر الجرح (٤/ ٢/ ٢٧). ٢٣٤٦ - كنى ابن منده (١٣٥/ أ)، كنى الحاكم (١/ ١٨٤/ أ)، المقتنى في سرد الكنى (٦١/ ب).\nفي كنى الحاكم \"كان اماما من أئمة الازد\". ٢٣٤٧ - كنى البخارى (ص ٣٤)، الجرح (٤/ ٢/ ٣٧٦)، كنى الحاكم (١/ ١٨٤/ أ)، الثقات (٥/ ٥٨٦)، المقتنى في سرد الكنى (٦١/ ب).\nزاد الحاكم \"ويقال\". وفى الثقات \"أبو سعيد اليمانى\". ٢٣٤٨ - كنى الحاكم (١/ ١٨٤/ أ)، كنى ابن منده (١٣٦/ ب)، المقننى في سرد الكنى (٦١/ ب)."}],[3634,"٢٣٤٩ - أبو سعيد، رجل من أهل البصرة، حدث الشعبى عنه، عن عمر، روى عنه مجالد بن سعيد."],[3635,"٢٣٥٠ - أبو سعيد الأَعْسَم (١)، الاسدى كوفى، روى عن مصعب بن سعد ابن أبى وقاص، روى عنه الحجاج بن أرطاة."],[3636,"٢٣٥١ - أبو سعيد الازدى، الشّنوى (٢) من ازد شنؤة بصرى، روى عن أبى هريرة، روى عنه قتادة."],[3637,"٢٣٥٢ - أبو سعيد، روى عن سعيد بن جبير، روى عنه السدى."],[3638,"٢٣٥٣ - أبو سعيد الحميرى (٣)، روى عنه. حيوة بن شريح.","",{"fn":"الأعْسَم: بفتح الألف وسكون العين المهملة وفتح السين المهملة وفى آخرها الميم: هو أبو عبد اللَّه محمد بن عبد اللَّه بن يزيد الاعسم. اللباب (١/ ٧٥). ٢٣٥١ - كنى الحاكم (١/ ١٨٤/ ب) وقال: حديثه في البصريين. الثقات (٥/ ٥٦٥)، الميزان (٤/ ٥٢٩). وقال: لا يعرف إلا برواية قتادة عنه، اللسان (٧/ ٤٦٦)، التهذيب (١٢/ ١٠٨)، التقريب (٢/ ٤٢٧) وقال: مقبول، من الثالثة./ د.\nفي التهذيب \"الشنائى\"، والشنائى والشنوى. كلاهما نسبة إلى أزد شنوءة. انظر اللباب (٢/ ٢١١ - ٢١٢). ٢٣٥٢ - كنى البخارى (ص ٣٥)، الجرح (٤/ ٢/ ٣٧٦)، كنى الحاكم (١/ ١٨٤/ ب)، الثقات (٧/ ٦٥٧). ٢٣٥٣ - كنى البخارى (ص ٣٥)، الجرح (٤/ ٢/ ٣٧٦)، كنى الحاكم (١/ ١٨٤/ ب) الميزان (٤/ ٥٣٠) وقال: لا يدرى من هو، اللسان (٧/ ٤٦٦)، التهذيب (١٢/ ١٠٩) وقال: قال الحسن بن القطان: أبو سعيد هذا شامى مجهول الحال. التقريب (٢/ ٤٢٨) وقال: شامى مجهول، من الثالثة وروايته عن معاذ بن جبل مرسله./ د. ق.\nفي الميزان، واللسان، والتهذيب والتقريب زيادة \"عن معاذ مرسلا\"."}],[3639,"٢٣٥٤ - أبو سعيد (١) قاضى افريقية."],[3640,"٢٣٥٥ - أبو سعيد مولى جراد (٢)، روى عن عوف بن أبى جميلة، روى عنه إسحاق بن ادريس الاسوارى (٣). واسحاق ذاهب الحديث (٤)."],[3641,"٢٣٥٦ - أبو سعيد، مولى بنى تميم، عن رجل من بنى شيبة، روى عن ابن المبارك."],[3642,"٢٣٥٧ - أبو سعيد الجرُجَانى (٥)، صاحب بشر بن غياث (٦)، روى عنه عبيد بن عبد الواحد البزار (١).","",{"fn":"زاد البخارى في الكنى \"الرعينى\". ٢٣٥٥ - كنى الحاكم (١/ ١٨٤/ ب). المقتنى في سرد الكنى (٦١/ ب).\nجراد بن عبس من اعراب البصرة، رُوِى عنه حديث من وجه مجهول التجريد (١/ ٨١).\nإسحاق بن ادريس الاسوارى، ذكره ابن أبى حاتم في الجرح (١/ ١/ ٢١٣) وقال: تركه على بن المدينى. . سألت أبى عنه فقال: ضعيف الحديث، سئل أبو زرعة عنه فقال: واهى الحديث، ضعيف الحديث.\nوفى كنى الحاكم أيضا: \"واسحاق ذاهب الحديث\". ٢٣٥٦ - كنى البخارى (ص ٣٥)، الجرح (٤/ ٢/ ٣٧٧) وذكر أيضا أنه روى عنه الوليد بن شجاع وهشام بن عمار. وقال: سألت أبى عنه فقال: ما أرى بحديثه بأسا، كنى الحاكم (١/ ١٨٤/ ب). ٢٣٥٧ - كنى الحاكم (١/ ١٨٤/ ب) وقال: كناه لنا أبو العباس الثقفى عن عبيد بن عبد الواحد، المقتنى في سرد الكنى (٦١/ ب).\nالجرجانى: بضم الجيم وسكون الراء وبالجيم المفتوحة وبالنون بعد الألف - نسبة إلى مدينة جُرْجَان وفتحها يزيد بن المهلب أيام سليمان بن عبد الملك. انظر اللباب (١/ ٢٧٠)، وانظر جُرْجَان أيضا في مراصد الاطلاع (١/ ٣٢٣).\nبشر بن غياث المريسى، مبتدع ضال لا ينبغى أن يروى عنه ولا كرامة. انظر ترجمته في اللسان (٢/ ٢٩ - ٣١)."}],[3643,"٢٣٥٨ - أبو سعيد البجلى، شامى، عن على بن عروة (٢)، روى عنه هشام ابن عمّار."],[3644,"٢٣٥٩ - أبو سعيد بن أخى مبشّر بن عبد اللَّه بن رَزِين (٣) حكى في مولد مبشر حكاية."],[3645,"٢٣٦٠ - أبو سعيد. روى عن خالد بن يزيد (٤) عن سعيد بن أبى هلال (٥) روى عنه معاوية بن صالح."],[3646,"٢٣٦١ - أبو سعيد، قال شهدت عروة بن الزبير، وعبد اللَّه بن عمر، يتحدثان عند المقام (١). حديثه عند شعبة، عن إبراهيم بن محمد بن حاطب عنه.","",{"fn":"عبيد بن عبد الواحد بن شريك البزار، ثمة صدوق (ت: ٢٨٥)، اللسان (٤/ ١٢٠). ٢٣٥٨ - كنى الحاكم (١/ ١٨٥/ أ)، كنى ابن منده (١٣٨/ أ)، المقتنى في سرد الكنى (٦١/ ب).\nعلى بن عروة القرشى الدمشقى، متروك، من الثامنة. التقريب (٢/ ٤١) وانظر الجرح (٣/ ١/ ١٩٨). ٢٣٥٩ - كنى الحاكم (١/ ١٨٥/ أ) ذكره كما هنا تماما وقال: كناه لنا أبو العباس الثقفى.\nمُبَشّر بكسر المعجمة الثقيلة بن عبد اللَّه بن رَزِين، بفتح الراء كسر الزاى أبو بكر النيسابورى، ثقة، من كبار التاسعة. التقريب (٢/ ٢٢٨) التهذيب (١٠/ ٣٢). ٢٣٦٠ - كنى البخارى (ص ٣٥)، الجرح (٤/ ٢/ ٣٣٧)، كنى الحاكم (١/ ١٨٥/ أ).\nهو المصرى كما صرح ابن حجر في التهذيب (٤/ ٩٥) في ترجمة سعيد ابن أبى هلال الليثى.\nزاد البخارى في الكنى \"مرسل\". ٢٣٦١ - كنى البخارى (ص ٣٥)، الجرح (٤/ ٢/ ٣٧٧) وقال: قال شهدت. . إلخ. كنى الحاكم (١/ ١٨٥/ أ) وذكره عن البخارى تماما."}],[3647,"٢٣٦٢ - أبو سعيد (شهد عروة بن الزبير وعبد اللَّه بن عمر يتحدثان) (٢). عن يحيى بن أبى كثير. روى عنه محمد بن عبد الرحمن بن ثوبان."],[3648,"٢٣٦٣ - أبو سعيد عن مكحول، أن لم يكن الحبرانى فلا أدرى (٣)."],[3649,"٢٣٦٤ - أبو سعيد خادم الحسن بن أبى الحسن، روى عن الحسن، حدث عنه محمد بن مهاجر.","",{"fn":"زاد البخارى في الكنى \"فجاء أعرابى فصلى يركع ويسجد فناداه ابن عمر لا صلاة بعد طلوع الفجر إلا ركعتين فصل بعد ذلك ما بدا لك. قلت: هكذا هو في مطبوعة الكنى \"فناداه ابن عمر لا صلاة\". . إلخ. قلت: والمقام المذكور هو: بالفتح، وهو الحجر الذى قام عليه إبراهيم عليه السلام حين رفع بناء البيت. وقيل: الذى قام عليه حين غسلت زوجة إسماعيل رأسه وهو موضع بالمسجد الحرام أمر اللَّه عز وجل بالصلاة عنده وهو معروف. انظر مراصد الاطلاع (٣/ ١٢٩٥). ٢٣٦٢ - كنى ابن منده (١٣٨/ أ)، كنى الحاكم (١/ ١٨٥/ أ).\nهكذا في الأصل، وبالنظر إلى الترجمة السابقة نجد أن هذا القدر من الكلام هو جزء منها. وهو مقحم في هذه الترجمة اقحاما ولم يذكر ابن منده والحاكم في ترجمة أبى سعيد شيئا من هذا النص المقحم، ولعل ذكره في هذه الترجمة هو سبق قلم من الناسخ. واللَّه أعلم. ٢٣٦٣ - الميزان (٤/ ٥٣٠) وقال: أبو سعيد، عن مكحول، وعنه عتبة بن يقظان قال الدارقطنى: مجهول، اللسان (٧/ ٤٦٦)، التهذيب (١٢/ ١١١) التقريب (٢/ ٤٢٨) وقال: مجهول، من السابعة./ ق.\nهكذا قال ابن عبد البر هنا \"أن لم يكن الحبرانى فلا أدرى\" وقد تقدم أبو سعيد الحبرانى في الكتاب الثانى (١٠٧٥) وقد فرق الذهبى وابن حجر بين أبى سعيد عن مكحول وبين أبى سعيد الحبرانى. انظر مصادر الترجمة. ٢٣٦٤ - كنى ابن منده (١٣٦/ أ)، المقتنى في سرد الكنى (٦١/ ب)، كنى الحاكم ="}],[3650,"٢٣٦٥ - أبو سعيد بن رافع، عم عباد بن أبى صالح (١)، روى عن (٢) ابن عباس. روى عنه عمرو بن دينار."],[3651,"٢٣٦٦ - أبو سعيد، روى عن على، روى يحيى بن مسلم بن الضحاك عن أمه عنه."],[3652,"٢٣٦٧ - أبو سعيد، روى عن أبى غالب، عن أبى أمامة عن النبى عليه السلام \"في الكرات والبصل\" (٣).","",{"fn":"عباد بن أبى صالح، هو عبد اللَّه بن أبى صالح ذكوان السمان المدنى لين الحديث، من السادسة. التقريب (١/ ٤٢٣)، التهذيب (٥/ ٢٦٣).\nفي الجرح قال \"روى عن. . . \" ولم يسم أحدا. ٢٣٦٦ - الجرح (٤/ ٢/ ٣٧٧) وقال: سألت أبا زرعة عنه فقال: لا أعرفه إلا في هذا الحديث. ٢٣٦٧ - الجرح (٤/ ٢/ ٣٧٧) وذكر الحديث مرفوعا قال \"الكراث والبصل سك ابليس -يعنى طيبة\" وقال ابن أبى حاتم أيضا: سئل أبى عنه فقال: لا أعرفه.\nالحديث أخرجه الطبرانى في الكبير من طريق أبى غالب عن أبى امامة مرفوعا قال: \"الثوم والبصل والكراث من سكّ ابليس\" كما في مجمع الزوائد ="}],[3653,"روى عنه عبد العزيز بن عبد الصمد (١)."],[3654,"٢٣٦٨ - أبو سعيد، روى عن أبى هريرة، مدنى، روى عن عبد الرحمن بن يزيد بن جابر. قال ابن أبى حاتم: سألت أبى عنه فقال: هو شيخ مدنى أدركه ابن جابر بالسّاحل لا يسمّى."],[3655,"قال ابن أبى حاتم: حديثه. قال: سمعت أبا هريرة عن النبى عليه السلام \"أن المسلم أخو المسلم لا يظلمه ولا يخذله. التقوى هاهنا\" (٢) وأشار إلى صدره.","",{"fn":"عبد العزيز بن عبد الصمد العمّى، بصرى، ثقة، حافظ، من كبار التاسعة (ت: ١٨٧) ويقال: بعد ذلك. التقريب (١/ ٥١٠)، وانظر الجرح (٢/ ٢/ ٣٨٨). ٢٣٦٨ - الجرح (٤/ ٢/ ٣٧٥)، وقال: سألت أبى. . إلخ. وذكر أيضا الحديث. كنى ابن منده (١٣٥/ أ) وقال: أبو سعيد بن أبى سعيد جليس أبى هريرة فذكره.\nالحديث أخرجه مسلم \"البر\" - باب تحريم ظلم المسلم (٤/ ١٩٨٦) ="}],[3656,"٢٣٦٩ - أبو سعيد الأموى، روى عن شعبة، كان أحمد بن حنبل يرضاه."],[3657,"باب أبى سلمة"],[3658,"٢٣٧٠ - أبو سلمة، روى عن النبى عليه السلام مرسلا انه قال \"ان الشيطان قال: لا ينجو منى صاحب المال\" (١) الحديث."],[3659,"٢٣٧١ - أبو سلمة الخوّاص الواسطى، روى عن ثابت البنانى، وابان بن أبى عياش (٢)، وأيوب السختيانى، روى عنه الحسن بن خلف البزار (٣). حديثه ليس بالقائم.","",{"fn":"الحديث أخرجه الحاكم في الكنى بهذا اللفظ مرفوعا. والذهبى في المقتنى في سرد الكنى وقال: إسناده مظلم. وأخرج الطبرانى من حديث عبد الرحمن ابن عوف قال: قال رسول اللَّه -صلى الله عليه وآله وسلم- قال الشيطان -لعنه اللَّه- لن يسلم منى صاحب المال من احدى ثلاث اغدو عليه بهن واروح بهن أخذه من غير حله وانفاقه في غير حقه وأحبّبْه إليه فيمنعه من حقه\". انظر مجمع الزوائد (١٠/ ٢٤٥) وقال الهيثمى: إسناده حسن. ٢٣٧١ - كنى ابن منده (١٣٢/ أ)، كنى الحاكم (١/ ١٩١) وقال: حديثه ليس بالقائم، وذكر الحديث من طريق الحسن بن خلف البزار، عن أبى سلمه الخوّاص عن أيوب السختيانى قال: حدثنى حمزة بن أنس، عن أنس مرفوعا \"من عال أختين أو ابنتين. . \" فذكر الحديث، المقتنى في سرد الكنى (٦٤/ ب) وقال: حديثه ليس بالقائم، الميزان (٤/ ٥٣٢) وقال: قال أحمد بن حنبل: حديثه ليس بالقائم، اللسان (٧/ ٥٦).\nأبان بن أبى عياش: بصرى، متروك، من الخامسة، انظر التقريب (١/ ٣١).\nالحسن بن خلف البزار الواسطى، هو الحسن بن شاذان، كان شاذان لقب أبيه، صدوق، له أوهام، من الحادية عشرة له عند البخارى حديث واحد (ت: ٢٤٦ هـ). التقريب (١/ ١٦٦)."}],[3660,"٢٣٧٢ - أبو سلمة مولى آل (١) ربيعة. روى عن أبى هريرة عن النبى عليه السلام \"لو كان الدين معلقا بالثريا\" (٢). الحديث روى عنه إسماعيل بن جعفر.","",{"fn":"في كنى البخارى زيادة \"أبى\".\nالحديث أخرجه البخارى في الكنى (ص ٣٩) من طريق قتيبة عن إسماعيل ابن جعفر عن أبى سلمة، عن أبى هريرة يرفعه بلفظ \"لو كان الدين عند الثريا لتناوله رجال من فارس\". ومن هذا الطريق أخرجه الحاكم في الكنى وابن أبى حاتم في الجرح به. كما في مصادر الترجمة. والحديث أخرجه البخارى في \"التفسير\" باب قوله تعالى ﴿وَآخَرِينَ مِنْهُمْ لَمَّا يَلْحَقُوا بِهِمْ﴾ الجمعة: ٣ (٨/ ٦٤١)، ومسلم \"فضائل الصحابة\" باب فضل فارس (٤/ ١٩٧٢) من حديث أبى هريرة برواية ثور عن أبى الغيث عنه قال: كنا جلوسا عند النبى -صلى الله عليه وآله وسلم- فأنزلت عليه سورة الجمعة ﴿وَآخَرِينَ مِنْهُمْ لَمَّا يَلْحَقُوا بِهِمْ﴾ قال: قلت من هم يا رسول اللَّه؟ فلم يراجعه النبى -صلى الله عليه وآله وسلم- حتى سأل ثلاثا -وفينا سلمان الفارسى، وضع رسول اللَّه -صلى الله عليه وآله وسلم- يده على سلمان- ثم قال: لو كان الايمان عند الثريا لناله رجال -أو رجل من هؤلاء. هذا اللفظ للبخارى، ولفظه عند مسلم بنحو هذا وأخرجه مسلم أيضا (٤/ ١٩٧٢) من طريق يزيد بن الاصم عن أبى هريرة قال: قال رسول اللَّه -صلى الله عليه وآله وسلم- \"لو كان الدين عند الثريا لذهب به رجل من فارس -أو يقال: من أبناء فارس حتى يتناوله\". وأخرجه أيضا الطحاوى في مشكل الآثار (٣/ ٩٥) من طرق عن أبى هريرة رضي الله عنه به، والترمذى \"التفسير\" باب تفسير سورة الجمعة (٩/ ٢٠٩) من طريق عبد اللَّه بن جعفر، حدثنى ثور بن يزيد الديلى عن أبى الغيث، عن أبى هريرة به وقال: حديث غريب. ومن طريق ثور بن يزيد عن سالم أبى الغيث أخرجه ابن جرير الطبرى في التفسير (٢٨/ ٩٦)، وأخرجه السيوطى في الدر المنثور (٦/ ٢١٥) وزاد نسبته إلى سعيد بن منصور، ="}],[3661,"٢٣٧٣ - أبو سلمة الجهنى. عن القاسم بن عبد الرحمن. روى عنه الفضيل ابن مرزوق (١). في الكوفيين."],[3662,"٢٣٧٤ - أبو سلمة بن عبد اللَّه بن عبد اللَّه بن عمر بن الخطاب وقيل أبو سلمة بن عبيد اللَّه بن عبد اللَّه بن عمر بن الخطاب. روى عن القاسم ابن محمد، ووهب بن منبه، روى عنه أبو عاصم النبيل، وحماد بن سلمة والدراوردى قال (. . . . . . .) (١) بن عبيد اللَّه.","",{"fn":"الفضيل بن مرزوق الأغر الرقاشى، صدوق، يهم، ورمى بالتشيع، من السابعة. التقريب (٢/ ١١٣) ٢٣٧٤ - كنى البخارى (ص ٤٠)، وقال: أبو سلمة بن عبد اللَّه بن عبيد اللَّه بن عمر ابن الخطاب، سمع القاسم، روى عنه أبو عاصم، ثم قال: ويروى الدراوردى عن أبى سلمة بن عبيد اللَّه بن عبد اللَّه بن عمر، عن وهب بن منبه، الجرح (٤/ ٢/ ٣٨٣) وقال: أبو سلمة بن عبد اللَّه بن عبد اللَّه، وقال بعضهم: أبو سلمة بن عبيد اللَّه بن عبد اللَّه. . \" إلخ وقد فرق ابن أبى حاتم بين أبى سلمة ابن عبد اللَّه هذا وبين أبى سلمة روى عن وهب بن منبه، روى عنه حماد بن سلمة فجعلهما اثنين، وهو عند ابن عبد البر رجل واحد كما هو ملاحظ في هذه الترجمة، الثقات (٧/ ٦٦٠)، كنى ابن منده (١٣١/ ب) وقال: أبو ="}],[3663,"٢٣٧٥ - أبو سلمة الحمصى. روى عن خالد بن معدان. روى عنه الأوزاعى ولعله سليمان بن سليم (٢)."],[3664,"٢٣٧٦ - أبو سلمة الكلاعى، عن ثوبان. روى عنه الأحوص بن حكيم، حديثه في الشاميين."],[3665,"٢٣٧٧ - أبو سلمة بن أبى بكر بن عبد الرحمن بن الحارث بن هشام المخزومى، مدنى، روى عن أبيه، روى عنه شيبة بن نِصَاح (١).","",{"fn":"في الأصل بياض بمقدار كلمتين. ٢٣٧٥ - كنى ابن منده (١٣١/ ب)، كنى الحاكم (١/ ١٩١/ ب) ذكره بنحو ما هنا ثم قال: وقد أخرجت فيما تقدم أبا سلمة سليمان بن سليم الكنانى الحمصى، عن يحيى بن جابر الشامى، وأبى عبد اللَّه المثنى بن الصباح، روى عنه أبو عبد اللَّه محمد بن حرب الخولانى، وأبو عتبة إسماعيل بن عباس العنسى، فلا أدرى هما اثنان أم واحد، وخليقا أن يكونا اثنين لرواية هذا الثانى عن خالد بن معدان، ورواية الأوزاعى عنه. وأنه أعلى سماعا وراويا من الذى تقدم ذكرنا له، المقتنى في سرد الكنى (٦٤/ ب) الميزان (٤/ ٥٣٣) وقال: لا يعرف، اللسان (٧/ ٤٦٧) وقال: هو سليمان بن سليم الكلبى، مجهول، وثقه النسائى.\nسليمان بن سليم، قاضى حمصى، ثقة، عابد، من السابعة (ت: ١٤٧) انظر التقريب (١/ ٣٢٥). ٢٣٧٦ - كنى البخارى (ص ٣٩)، الجرح (٤/ ٢/ ٣٨٣)، كنى ابن منده (١٣١/ ب)، كنى الحاكم (١/ ١٩١/ ب)، المقتنى في سرد الكنى (٦٤/ ب). ٢٣٧٧ - كنى مسلم (ص ٤٥٩)، كنى ابن منده (١٣١/ ب)، كنى الحاكم (١/ ١٩٢/ أ)، المقتنى في سرد الكنى (٦٤/ ب). ="}],[3666,"٢٣٧٨ - أبو سلمة بن سفيان بن عبد الأسد المخزومى، روى عن عبد اللَّه ابن السائب (٢)، وأبى (أمية) (٣) بن الأخنس الثقفى، روى عنه محمد بن عبّاد بن جعفر (٤)، وعبد الملك بن عبد اللَّه بن أبى سفيان (٥) ويحيى بن عبد اللَّه بن محمد (٦) وعبد العزيز بن عبد اللَّه (٧)، وعمر بن عبد الرحمن بن محيصن السهمى (١).","",{"fn":"شيبة بن نِصَاح، بكسر النون بعدها مهملة وآخره مهملة، مدنى، قاضى، ثقة، من الرابعة (ت: ١٣٠). انظر التقريب (١/ ٣٥٧). ٢٣٧٨ - كنى البخارى (ص ٣٩)، كنى الحاكم (١/ ١٩٢/ أ) المقتنى في سرد الكنى (٦٤/ ب)، التهذيب (٥/ ٢٤٠) ذكره فيمن اسمه عبد اللَّه فقال: مشهور بكنيته. وذكر روايته عن عبد اللَّه بن السائب المخزومى، وأبى أمية بن الأخنس، ورواية محمد بن عباد بن جعفر وعمر بن عبد العزيز ويحيى بن عبد اللَّه بن صيفى عنه وقال في التقريب (١/ ٤٢٠) ثقة، من الرابعة./م. د. س. ق. اهـ.\nهو عبد اللَّه بن السائب بن أبى السائب المخزومى -كما صرح بذلك الحاكم في الكنى في ترجمة أبى سلمة بن سفيان- وهو مكى، له ولأبيه صحبة وكان قارئ أهل مكة مات سنة بضع وستين وهو عبد اللَّه بن السائب قائد ابن عباس رضي الله عنهما. التقريب (١/ ٤١٧).\nفي الأصل غير واضح، والمثبت عن كنى الحاكم. والتهذيب، وأبو أمية ابن الاخنس هو المتقدم في (١٢٧٤) وذكر ابن عبد البر في ترجمته هناك انه روى عنه أبو سلمة بن سفيان.\nمكى ثقة، من الثالثة. التقريب (٢/ ١٧٤).\nذكره ابن أبى حاتم في الجرح (٢/ ٢/ ٣٥٤) ولم يذكر فيه شيئا.\nيحيى بن عبد اللَّه بن محمد بن يحيى بن صيفى، المكى، ثقة، من السادسة. التقريب (٢/ ٣٥٢).\nعبد العزيز بن عبد اللَّه. ذكره ابن أبى حاتم في الجرح (٢/ ٢/ ٣٨٦) وذكر روايته عن أبى سلمة بن سفيان. ولم يذكر فيه شيئا."}],[3667,"٢٣٧٩ - أبو سلمة، رجل من أصحاب الحديث، روى عن (حفص بن سليمان الضبعى) (٢)، (روى عنه محمد بن محبوب البصرى) (٣)، (٤)."],[3668,"٢٣٨٠ - أبو سلمة الحضرمى، رأى (٥) عبد اللَّه بن عباس، روى عنه أسحاق ابن يحيى بن طلحة ولعله أبا سلمة عبد اللَّه بن رافع الحضرمى الذى روى عن عمرو بن معدى كرب الزبيدى (١) قال أبو أحمد الحاكم: لا أراهما إلا اثنين.","",{"fn":"هو قارئ أهل مكة، ويقال: اسمه محمد، مقبول، من الخامسة (ت: ١٢٣). التقريب (٢/ ٥٩). ٢٣٧٩ - كنى الحاكم (١/ ١٩٢/ أ) وقال: أبو سلمة رجل من أصحاب الحديث. . . \"إلخ، المقتنى في سرد الكنى (٦٤/ ب).\nهكذا في الأصل \"حفص بن سليمان الضبعى\" والذى في كنى ابن منده وكنى الحاكم \"جعفر بن سليمان الضبعى\" وفى الجرح (١/ ١/ ٤٨١) جعفر بن سليمان الضبعى الجرشى، البصرى أبو سليمان مولى حريش، وكان ينزل في بنى ضبيعة ولعل الصواب هو \"جعفر\" كما في مصادر الترجمة كما في الجرح. واللَّه أعلم.\nمحمد بن محبوب البنانى، بضم الموحدة وخفة النون، البصرى، ثقة، من العاشرة (ت: ٢٢٣). التقريب (٢/ ٢٠٤).\nالحق في هامش الأصل، كتب بعده \"صح أصل\". ٢٣٨٠ - كنى ابن منده (١٣٢/ أ)، كنى الحاكم (١/ ١٩٢/ أ) ذكره فيمن لا يعرف له اسم، وقال: وقد اخرجت فيما تقدم أبا سلمة عبد اللَّه بن رافع الحضرمى، سمع عمرو بن معدى كرب الصدفى، روى عنه جعفر بن ربيعة القرشى، ولا أراهما إلا اثنين. اهـ. وقد ذكر الحاكم أبو أحمد أبا سلمة عبد اللَّه بن رافع الحضرمى المذكور في الكنى (١/ ١٨٦/ أ)، المقتنى في سرد الكنى (٦٤/ ب).\nفي كنى ابن منده، كنى الحاكم زيادة \"قبر\" وأخرج الحاكم من طريق اسحاق بن يحيى نا أبو سلمة الحضرمى قال: \"رأيت قبر عبد اللَّه بن عباس وابن الحنفية قائم عليه\"."}],[3669,"٢٣٨١ - أبو سلمة، عن أبيه (٢) قال: قدم علينا عمر بن عبد العزيز مكة (٣)، روى عنه عبد الرحمن بن مهدى."],[3670,"٢٣٨٢ - أبو سلمة، شامى، روى عن أبى مسلم الجليلى، روى عنه حريز ابن عثمان."],[3671,"٢٣٨٣ - أبو سلمة الواسطى (٤). روى عن الشعبى. روى عنه شعبة أحاديث منها خطب بلال إلى قوم من أهل اليمن (١). حديث مرسل.","",{"fn":"عمرو بن معدى كرب الزبيدى، قال الذهبى في التجريد (١/ ٤١٨) وفد مع مراد لأنه كان فارق زبيدا ونزل في مراد. اسلم سنة تسع وارتد مع الأسود، ثم اسلم وشهد اليرموك. اهـ. وقال ابن الاثير في النهاية (٢/ ٦٠) \"الزبيدى: بضم الزاى وفتح الباء وسكون الياء المثناة من تحتها وفى آخرها دال مهملة - هذه النسبة إلى زبيد وهى قبيلة من مذحج، واسم زبيد منبه بن صعب بن سعد العشيرة بن مالك بن أدد، وإنما قيل له زبيد لأنه قال: من يزيد لمن رفده؟ وذكر أيضا انه ينسب إليها خلق كثير منهم عمرو بن معدى كرب الزبيدى وذكر أنه استشهد بنهاوند أيام عمر بن الخطاب رضي الله عنه. ٢٣٨١ - كنى البخارى (ص ٤٠)، الجرح (٤/ ٢/ ٣٨٣)، كنى ابن منده (١٣١/ ب)، كنى الحاكم (١/ ١٩٢/ أ).\nلم أقف عليه.\nأخرجه البخارى وأبو أحمد الحاكم وابن منده وابن أبى حاتم في الجرح كما هنا. انظر مصادر الترجمة. ٢٣٨٢ - كنى البخارى (ص ٤٠)، الجرح (٤/ ٢/ ٣٨٣)، كنى الحاكم (١/ ١٩٢/ ب). ٢٣٨٣ - كنى البخارى (ص ٤٠)، كنى ابن منده (١٣١/ ب)، الجرح (٤/ ٢/ ٣٨٤) وقال: سألت أبى عنه فقال: لا يسمى وهو شيخ مجهول، كنى الحاكم (١/ ١٩٢/ ب)، الميزان (٤/ ٥٣٣)، وقال مجهول، اللسان (٧/ ٥٦) وقال: مجهول.\nزاد في الجرح \"ويعرف بالقرادى\" وفى اللباب (٣/ ٢١) القرادى بضم القاف ="}],[3672,"٢٣٨٤ - أبو سلمة العاملى (٢)، شامى، روى عن الزهرى، روى هشام بن عمار، عن عبد الملك بن محمد الصنعانى عنه. قال أبو حاتم: كان كذابا متروك الحديث. والحديث الذى رواه باطل."],[3673,"٢٣٨٥ - أبو سلمة، روى عن شهر بن حوشب، روى عنه عبد الصمد بن عبد الوارث، ضعفه أبو حاتم."],[3674,"٢٣٨٦ - أبو سلمة اللوذانى، روى عن أنس عن النبى عليه السلام حديثا في المؤاخاة في اللَّه (١)، حديثه عند محمد بن حميد (٢) عن الحكم بن بشير (٣) عن عمرو بن قيس الملائى عن أبى سلمة عن أنس. قال أبو عبد اللَّه محمد بن حميد: ولم يسمع أبو سلمة هذا من أنس (٤).","",{"fn":"أخرجه البخارى في الكنى وقال أيضا مرسل وقال: قاله ابن أبى عدى عن شعبة. وأخرجه أبو أحمد الحاكم في الكنى أيضا وعزاه للبخارى. ٢٣٨٤ - الجرح (٤/ ٢/ ٣٨٣) وقال: سألت أبى عنه فقال: كذاب متروك الحديث. . إلخ. الميزان (٤/ ٥٣٢) وقال: اسمه الحكم بن عبد اللَّه بن خطاف، اللسان (٧/ ٤٦٧) وقال: اسمه الحكم بن عبد اللَّه بن خطاف، التقريب (٢/ ٤٣٠) وقال: متروك ورماه أبو حاتم بالكذب من السابعة./ ق.\nالعاملى: بفتح العين المهملة وبعد الألف ميم مكسورة ولام هذه النسبة إلى عاملة وهو من العماليق. كذا قال السمعانى، وتعقبه ابن الاثير فقال: الصحيح أن عاملة ولد الحارث بن عدى بن الحارث بن مرة. . ونسب ولد الحارث بن عدى إلى أمهم عاملة بنت مالك بن وديعة من قضاعة. اهـ. بتصرف. انظر اللباب (٢/ ٣٦٠). ٢٣٨٥ - الجرح (٤/ ٢/ ٣٨٤) وقال: سألت أبى عنه فقال: ضعيف الحديث، الميزان (٤/ ٥٣٢) وقال: ضعفه أبو حاتم. اللسان (٧/ ٥٦)، كنى ابن منده (١٣١/ أ) ذكره كما هنا وسماه مروان. ٢٣٨٦ - الجرح (٤/ ٢/ ٣٨٤)، وذكره بنحو ما هنا، وذكر حديثه.\nالحديث أخرجه ابن أبى حاتم في الجرح من هذا الطريق بلفظ \"من أحدث أخا في اللَّه عز وجل رفعه اللَّه عز وجل بها درجة في الجنة وماتوا رجلان في اللَّه عز وجل إلا كان افضلهما منزلة عند اللَّه عز وجل اشدهما حبا لأخيه حتى يحدث احدهما، واشرهما الذى يحدث.\nصرح ابن حجر في التهذيب (٢/ ٤٢٤) في ترجمة الحكم بن بشير بأنه روى عنه محمد بن حميد الرازى، وفى التقريب (٢/ ١٥٦) محمد بن حميد ابن حيان الرازى، حافظ ضعيف، وكان ابن معين حسن الرأى فيه، من العاشرة (ت: ٢٣٠). اهـ.\nالحكم بن بشير بن سليمان النهدى، أبو محمد بن أبى إسماعيل الكوفى، صدوق، من الثامنة، / التقريب (١/ ١٩٠).\nانظر الجرح (٤/ ٢/ ٣٨٤) في ترجمة أبى سلمة اللوذانى."}],[3675,"باب أبى سعد"],[3676,"٢٣٨٧ - أبو سعد، عن ابن عمر، كوفى، روى عنه أبو إسحاق السبيعى. عمرو بن عبد اللَّه الهمدانى."],[3677,"٢٣٨٨ - أبو سعد الازدى كوفى عن عبد اللَّه بن عمرو بن العاص، روى عنه الأعمش، وزكريا بن أبى زائدة، جعلهما الحاكم رجلين (١). وجعلهما ابن أبى حاتم رجلا واحدا، وقال: روى عنه أبو إسحاق والأعمش."],[3678,"٢٣٨٩ - أبو سعد الازدى (قاضى) (٢) الازد. روى عن أبى الكنود عبد اللَّه (٣) ابن عمران الأزدى. روى عنه إسماعيل بن عبد الرحمن السدى ويزيد بن أبى ٢٣٩٠ - أبو سعد الغفارى. روى عن أبى هريرة. روى عنه أبو هانى الخولانى - مصرى.","",{"fn":"هما صاحب هذه الترجمة والذى قبله المتقدم في (٢٣٨٧). ٢٣٨٩ - كنى البخارى (ص ٣٦) وقال روى عن زيد بن أرقم، كنى مسلم (ص ٤٧١) الثقات (٥/ ٥٦٨)، وقال: روى عن زيد بن ارقم، كنى الحاكم (١/ ٢٠٥/ أ)، التهذيب (١٢/ ١٠٦)، وقال: أبو سعد الارحبى الكوفى قارئ الازد ويقال: أبو سعيد روى عن زيد بن ارقم وأبى الكنود وقال في التقريب (٢/ ٤٢٦) مقبول، من الثالثة./ ت. ق.\nفي كنى الحاكم والتهذيب \"قارئ\".\nفي الأصل \"وعبد اللَّه بن عمران الازدى\" وبهذا يكون أبو الكنود غير عبد اللَّه ="}],[3679,"٢٣٩١ - أبو سعد. قال: \"رأيت ابن الزبير\" (١). روى عنه سيف بن ميسرة (٢).","",{"fn":"ومثله في كنى الحاكم والذى في كنى البخارى والجرح \"قال: رأيت الزبير\" فاللَّه أعلم.\nسيف بن ميسرة. ذكره ابن أبى حاتم في الجرح (٢/ ١/ ٢٧٥) ولم يذكر فيه شيئا."}],[3680,"٢٣٩٢ - أبو سعد (١)، عن مكحول الدمشقى، روى عنه (عبيد) (٢) بن يقظان حديثا لم يروه غيره مسندا، حدث عن مكحول، عن واثلة بن الأسقع قال: قال رسول اللَّه -صلى الله عليه وآله وسلم-: \"صلوا على أهل ملتكم ولا تكفروهم وإن ركبوا الكبائر، وجاهدوا مع كل إمام برّ وفاجر وصلوا خلفهم واغزوا مع امرائهم\" (٣) وهذا عندهم حديث لم يتابع عليه منكر.","",{"fn":"هكذا ذكره ابن عبد البر في باب أبى سعد والذى في أصول التخريج كسنن ابن ماجه والدارقطنى والعلل المتناهية \"أبو سعيد\" واللَّه أعلم.\nهكذا في الأصل \"عبيد\" وفى كنى الحاكم والمقتنى في سرد الكنى \"عتبة\" ولم أقف على من اسمه \"عبيد بن يقظان\" وذكر ابن أبى حاتم في الجرح (٣/ ١/ ٣٧٤) عتبة بن يقظان وقال: سمعت على بن الحسين بن الجنيد يقول: لا يساوى شيئا، وفى التهذيب (٧/ ١٠٣) عتبة بن يقظان الراسبى، روى عن قيس بن مسلم وأبى سعيد الشامى. اهـ. وفى التقريب (٢/ ٥) عتبة ابن يقظان، بصرى، ضعيف، من السادسة. وسيأتى في تخريج الحديث ما يدل على أن الراوى عن أبى سعد هذا إنما هو عتبة بن يقظان. لا عبيد بن يقظان. واللَّه أعلم.\nالحديث أخرجه ابن ماجه \"الجنائز\" باب في الصلاة على أهل القبلة (١/ ٤٨٨) مختصرا من طريق أحمد بن يوسف السّلمى، ثنا مسلم بن إبراهيم ثنا الحارث بن نبهان، ثنا عتبة بن يقظان عن أبى سعيد، عن مكحول، عن واثلة بن الأسقع، فال: قال رسول اللَّه -صلى الله عليه وآله وسلم- \"صلوا على كل ميت. وجاهدوا مع كل أمير\". وقال السندى: في الزوائد: في إسناده عتبة بن يقظان، وهو ضعيف والحارث بن نبهان مجمع على ضعفه، وأبو سعيد هو المصلوب كذاب. اهـ. وأخرجه أيضًا الدارقطنى (٢/ ٥٧) من طريق الحارث بن نبهان عن أبى سعيد الشامى، عن مكحول، عن واثلة بن الأسقع به مرفوعا. أخرجه ابن الجوزى ="}],[3681,"٢٣٩٣ - أبو سعد الأعمى، مكى عن أبى هريرة، روى عنه عطاء بن أبى رباح وابن جريج، يعد في أهل الحجاز."],[3682,"٢٣٩٤ - أبو سعد بن حفص بن عمر بن ثابت بن رواحة الأنصارى، حلبى، كان يسكن حلب. روى عن أبيه، وعن مسعر بن كدام، روى عنه هشام ابن عمار، والوليد بن شجاع، قال ابن أبى حاتم: سألت - عنه أبى فقال: ما أرى بحديثه بأسا."],[3683,"٢٣٩٥ - أبو سعد، روى عن أبى عون الأنصارى - عن أبى هريرة."],[3684,"٢٣٩٦ - أبو سعد الجعفى (١)، أو الجرمى (٢)، روى عن يونس بن عبد اللَّه (٣)، روى عنه القاسم بن يزيد الجرمى (٤)."],[3685,"٢٣٩٧ - أبو سعد السّاعدى، روى عن أنس بن مالك، روى عنه رواد بن الجراح، لم يرو عنه غيره."],[3686,"٢٣٩٨ - أبو سعد الخزاعى، روى عن ابن ابزى حديثه (٥) عند القطان عن سفيان عن منصور عنه.","",{"fn":"هكذا في الأصل \"الجعفى\" وفى كنى الحاكم \"الحنفى\".\nومثله في كنى الحاكم لكن قال \"الحنفى أو الجرمى\" وثقه أحمد وابن معين. كما ذكر.\nلعله يونس بن عبد اللَّه الجرمى، أحد الثقات وثقه أحمد وابن معين. كما ذكر ابن أبى حاتم في الجرح (٤/ ٢/ ٢٤١).\nثقة، عابد، من التاسعة (ت: ١٩٤). التقريب (٢/ ١٢١). ٢٣٩٧ - الجرح (٤/ ٢/ ٣٧٨) وقال: سألت أبى عنه فقال: هو مجهول، لم يرو عنه غير رواد. . سئل أبو زرعة عن اسم أبى سعد الساعدى فقال: لا أعرف اسمه. الميزان (٤/ ٥٢٨) وقال: مجهول. . حدث عنه رواد بن الجراح وليس بعمدة، حديثه رأى النبى -صلى الله عليه وآله وسلم- رجلا يتبع حمامة فقال: \"شيطان يتبع شيطانة\"، تهذيب الكمال (٣/ ١٦٠٨) التهذيب (١٢/ ١٠٦)، التقريب (٢/ ٤٢٧) وقال: مجهول، من الخامسة./ ق. ٢٣٩٨ - كنى البخارى (ص ٣٦)، الجرح (٤/ ٢/ ٣٧٨).\nذكر البخارى في الكنى حديثه من طريق مسدد عن يحيى عن سفيان عن منصور عن أبى سعد الخزاعى عن ابن أبزى قال: كان النبى -صلى الله عليه وآله وسلم- يشير في الصلاة بالسبابة."}],[3687,"باب أبى سليمان"],[3688,"٢٣٩٩ - أبو سليمان الليثى، عن أبى سعيد الخدرى، حديثه عند سعيد بن أبى أيّوب، عن عبد اللَّه بن الوليد (١) عنه."],[3689,"٢٤٠٠ - أبو سليمان، روى عن أبى هريرة، عن النبى عليه السلام قال (إذا وضع الميت على سريره قال: قدمونى) (٢)، (٣)، روى عنه معاوية بن صالح.","",{"fn":"في كنى الحاكم زيادة \"بن قيس\". ٢٤٠٠ - كنى البخارى (ص ٣٧)، الجرح (٤/ ٢/ ٣٧٩)، كنى الحاكم (١/ ١٦٤/ ب)، كنى ابن منده (١٤٢/ ب).\nفي الأصل غير واضح، وهو في مصادر الترجمة كما أثبته.\nالحديث أخرجه البخارى في الكنى وابن أبى حاتم في الجرح، وابن منده في الكنى، والحاكم في الكنى من هذا الطريق مرفوعًا به. وأخرجه أيضًا أحمد في المسند (٢/ ٢٩٢ و٤٧٤ و٥٠٠) والنسائى في \"الجنائز\" باب السرعة بالجنازة (٤/ ٤٠) من حديث أبى هريرة مرفوعًا لكن من رواية عبد الرحمن بن مهران عنه بلفظ \"إذا وضع الرجل الصالح على سريرة قال: قدمونى قدمونى وإذا وضع الرجل السوء على سريره قال: يا ويله أين تذهبون بى\". وأخرج البخارى \"الجنائز\" باب السرعة بالجنازة (٣/ ١٨٢) حديث أبى ="}],[3690,"٢٤٠١ - أبو سليمان الحدّانى (١)، روى عن أنس بن مالك، روى عنه شعبة، وربما قال شعبة: سليمان أو أبو سليمان (٢)."],[3691,"٢٤٠٢ - أبو سليمان المرعشى (٣) عن كعب الأحبار قوله. روى عنه قتادة."],[3692,"٢٤٠٣ - أبو سليمان بن جبير بن مطعم بن عدى بن نوفل القرشى، أخو محمد (١)، ونافع، روى عن أبيه وعن سعيد بن المسيب، روى عنه يحيى بن سعيد الأنصارى (٢)، ذكر إسحاق بن منصور عن يحيى بن معين قال: أبو سليمان بن جبير بن مطعم ثقة (٣).","",{"fn":"في كنى البخارى \"الحرانى\".\nهكذا هنا \"قال شعبة: سليمان أو أبو سليمان\" وفى كنى البخارى \"وربما قال شعبة سليمان أو أبو سليمان\". ٢٤٠٢ - كنى البخارى (ص ٣٧)، الجرح (٤/ ٢/ ٣٨٠)، كنى الحاكم (١/ ١٦٤/ ب).\nالمرعشى: بفتح الميم وسكون الراء وفتح العين المهملة وفى آخرها شين معجمة - هذه النسبة إلى مرعش وهى بلدة من بلاد الشام. اللباب (٣/ ١٩٦). ٢٤٠٣ - كنى البخارى (ص ٣٧)، كنى ابن منده (١٤٢/ ب)، الجرح (٤/ ٢/ ٣٨٠)، كنى الحاكم (١/ ١٦٤/ ب)، المقتنى في سرد الكنى (٦٦/ أ)."}],[3693,"٢٤٠٤ - أبو سليمان الأزدى، سمع أبا يحيى (٤) مولى معاذ بن عفراء، روى عن ابن عباس، روى شعبة عن أبى هارون الغنوى (٥) عنه."],[3694,"٢٤٠٥ - أبو سليمان العصرى، روى عن عقبة بن صهبان عن أبى بكرة، روى عنه سعيد بن زيد أخو حماد بن زيد ذكر إسحاق بن منصور عن يحيى بن معين قال: أبو سليمان العصرى ثقة (٦)."],[3695,"٢٤٠٦ - أبو سليمان، عن زيد بن صوحان، روى عنه سلام بن مسكين.","",{"fn":"محمد بن جبير بن مطعم بن عدى بن نوفل، النوفلى، ثقة عارف بالنسب من الثالثة. مات على رأس المائة./ التقريب (٢/ ١٥٠).\nفي كنى البخارى \"الأموى\".\nقال ابن أبى حاتم في الجرح (٤/ ٢/ ٣٨٠) ذكره أبى عن إسحاق بن منصور عن يحيى بن معين قال: أبو سليمان بن جبير بن مطعم، ثقة. ٢٤٠٤ - كنى البخارى (ص ٣٧)، كنى مسلم (ص ٤٤٩)، الجرح (٤/ ٢/ ٣٨٠)، كنى الحاكم (١/ ١٦٤/ ب)، كنى ابن منده (١٤٢/ ب).\nهو الأعرج المتقدم في (١٢٢٢).\nفي كنى البخارى \"إبراهيم بن العلاء\" وهو اسم أبى هارون الغنوى وهو المتقدم في الكتاب الثانى. انظر الترجمة (١١٩٣). ٢٤٠٥ - كنى البخارى (ص ٣٧)، الجرح (٤/ ٢/ ٣٨٠)، كنى الدولابى (١/ ١٩٤)، كنى الحاكم (١/ ١٦٤/ ب)، المقتنى في سرد الكنى (٦٦/ أ)، التهذيب (٣/ ١٥٩)، التقريب (١/ ٢٢٧) وقال: صدوق يرسل من الرابعة.\nقال ابن أبى حاتم في الجرح (٤/ ٢/ ٣٨٠) ذكره أبى عن إسحاق بن منصور عن يحيى بن معين أنه قال: أبو سليمان العصرى ثقة. ٢٤٠٦ - كنى البخارى (ص ٣٧)، الجرح (٤/ ٢/ ٣٨٠)، الثقات (٧/ ٦٥٩)، كنى الحاكم (١/ ١٦٥/ أ)، كنى ابن منده (١٤٢/ ب)."}],[3696,"٢٤٠٧ - أبو سليمان التيمى من تيم اللَّه (١). روى عن عمر بن حبيب. روى عنه المحاربى (٢)."],[3697,"٢٤٠٨ - أبو سليمان. روى عن محمد بن إسحاق. روى عنه حفص بن ميسرة لم يعرفه أبو حاتم (٣)."],[3698,"٢٤٠٩ - أبو سليمان الفلسطينى، عن القاسم بن محمد بن أبى بكر، عن أبى إدريس الخولانى، عن أبى ذر الغفارى حديثا منكرًا طويلا في قصة الأنبياء (٤).","",{"fn":"في اللباب (١/ ٢٣٣) \"من تيم اللَّه بن ثعلبة\".\nالمحاربى: هو عبد الرحمن بن زياد، أبو محمد الكوفى، لا بأس به، وكان يدلس قاله أحمد، من التاسعة (ت: ١٩٥). انظر التقريب (١/ ٤٩٧). ٢٤٠٨ - الجرح (٤/ ٢/ ٣٨١).\nهكذا قال ابن عبد البر هنا: لم يعرفه أبو حاتم. والذى في الجرح (٤/ ٢/ ٣٨١) قال ابن أبى حاتم: سئل أبو زرعة عنه فقال: لا أعرفه. ٢٤٠٩ - كنى ابن منده (١٤٣/ أ)، كنى الحاكم (١/ ١٦٤/ ب)، المقتنى في سرد الكنى (٦٦/ أ)، الميزان (٤/ ٥٣٣)، اللسان (٧/ ٥٧).\nالحديث أخرجه أحمد في المسند (٥/ ١٧٨ و١٧٩ و٢٦٦)، وابن حبان كما في موارد الظمآن (ص ٥٢ - ٥٤)، والبخارى في خلق أفعال العباد (ص ٤١)، وأبو داود الطيالسى في المسند (٢/ ٣١) ومحمد بن أبى عمر في مسنده كما في المطالب العالية (٣/ ١١٤) والخطابى في غريب الحديث (٢/ ١٥٧)، والبزار في صحيحه، والطبرانى في الأوسط كما في مجمع الزوائد (١/ ١٦٠ و٨/ ٢١٠) كلهم أخرجوه من طريق أبى إدريس الخولانى عن أبى ذر رضي الله عنه قال: أتيت رسول اللَّه -صلى الله عليه وآله وسلم- وهو في المسجد فجلست فقال: \"يا أبا ذر هل صليت؟ قلت: لا. قال: قم ="}],[3699,"٢٤١٠ - أبو سليمان اليشكرى، مولى يحيى بن يعمر، سمع عبد اللَّه بن عباس، روى عنه أيوب السختيانى."],[3700,"٢٤١١ - أبو سليمان الخراسانى، سمع أنسا."],[3701,"٢٤١٢ - أبو سليمان الهمدانى، كوفى، روى عن أبيه (١)، عن على بن أبى طالب رضي الله عنه، روى عنه أبو جناب يحيى بن أبى حية - وقد قيل: أنه أبو سليمان أيوب بن دينار المكتب (٢). الذى روى عن أبيه عن على أنه كان لا يقبل هدّيّة النّيروز (٣)، الذى روى عنه أبو نعيم وحفص بن غياث. وقال الحاكم: خليقا أن يكونا اثنين.","",{"fn":"لم أقف على من سماه.\nأبو سليمان أيوب بن دينار المكتب. انظر ترجمته في الجرح (١/ ١/ ٢٤٦).\nأخرجه الحاكم في الكنى (١/ ١٦٥/ أ)، وابن تيمية في اقتضاء الصراط المستقيم مخالفة أصحاب الجحيم (ص ٢٠٠) و(ص ٢٥٠)، والذهبى في سير أعلام النبلاء في ترجمة أبى حنيفة النعمان بن ثابت (٦/ ٣٩٥) قلت: ="}],[3702,"٢٤١٣ - أبو سليمان، عن عبد اللَّه بن عمرو بن العاص شامى، روى عنه خالد بن معدان."],[3703,"باب أبى سهل"],[3704,"٢٤١٤ - أبو سهل الأنصارى، سمع أبا سعيد الخدرى (يقول: حق) (١) على كل مسلم الاغتسال يوم الجمعة (٢). (رواه أبو معاوية) (٣) عن الأشعث عنه.","",{"fn":"غير واضح في الأصل والمثبت عن كنى الحاكم.\nالحديث أخرجه الحاكم في الكنى من طريق أبى معاوية عن الأشعث عن أبى سهل به وقال: قاله محمد بن إسماعيل. وأخرج البخارى \"الجمعة\" باب فضل الغسل يوم الجمعة (٢/ ٣٥٧) وفى باب هل على من لم يشهد الجمعة غسل من النساء والصبيان وغيرهم (١/ ٣٨٢) ومسلم \"الجمعة\" باب وجوب غسل الجمعة على كل بالغ من الرجال (٢/ ٥٨٠) حديث أبى سعيد الخدرى برواية عطاء بن السائب عنه مرفوعا بلفظ \"الغسل يوم الجمعة واجب على كل محتلم\". وهو عند البخارى أيضًا بلفظ \"حق على كل مسلم أن يغتسل في كل سبعة أيام يومًا يغسل فيه رأسه وجسده\". وانظر البخارى (٢/ ٣٨٢ و٦/ ٥١٥). وأخرجه أيضًا مالك \"الجمعة\" باب العمل في غسل الجمعة (١/ ١٠٢) وابن ماجه \"إقامة الصلاة والسنة فيها\" باب غسل الجمعة (١/ ٣٤٦) وأبو داود \"الطهارة\" باب غسل الجمعة (١/ ٩٤ - ٩٥). والدارمى (١/ ٣٦١) والبيهقى (١/ ٢٩٤) كلهم أخرجوه من طريق عطاء بن يسار عن أبى سعيد به.\nغير واضح في الأصل، والمثبت عن كنى الحاكم."}],[3705,"٢٤١٥ - أبو سهل الدّمشقى، عن سعيد بن عبد العزيز (١). روى عنه عبد اللَّه بن خبيق بن سابق."],[3706,"٢٤١٦ - أبو سهل، كوفى، روى عن محمد بن زيد بن الخطاب (٢). روى عنه حبيب بن أبى ثابت.","",{"fn":"في كنى الحاكم زيادة \"التنوخى\". ٢٤١٦ - كنى الحاكم (١/ ١٩٨/ ب)، المقتنى في سرد الكنى (٦٨/ أ).\nمحمد بن زيد بن عبد اللَّه بن عمر بن الخطاب، مدنى ثقة، من الثالثة التقريب (٢/ ١٦٢)."}],[3707,"باب أبى سنان"],[3708,"٢٤١٧ - أبو سِنَان (١) القسملى، سمع وهب بن منبه، قوله. روى عنه جعفر ابن سليمان، قال أبو أحمد الحاكم: وليس هو عيسى بن سنان (٢)."],[3709,"٢٤١٨ - أبو سنان الغنوى، روى عن أبيه (٣)، روى عنه موسى بن إسماعيل المنقرى."],[3710,"٢٤١٩ - أبو سنان الأسلمى."],[3711,"٢٤٢٠ - أبو سنان العجلى، سمع أنس بن مالك، حدث عنه ربيعة (٤) أراه ابن كلثوم بصرى.","",{"fn":"سنان: بكسر السين المهملة وبنونين، الاكمال (٤/ ٤٣٩).\nعيسى بن سنان، ويكنى أبا سنان، وهو القسملى أيضًا وهو المتقدم في الكتاب الثانى في الترجمة (١١٠٥). ٢٤١٨ - كنى الحاكم (١/ ٢٠٧/ ب)، كنى ابن منده (١٥٠/ أ)، المقتنى في سرد الكنى (٦٧/ أ).\nلم أقف على من سماه. ٢٤١٩ - كنى الحاكم (١/ ٢٠٧/ ب)، المقتنى في سرد الكنى (٦/ أ)، كنى ابن منده (١٥٠/ أ)، وقال: أبو سنان الأسلمى حدث عن على بن أبى طالب. روى عنه محمود بن لبيد. قاله البخارى. ٢٤٢٠ - كنى الحاكم (١/ ٢٠٧/ ب)، الميزان (٤/ ٥٣٤) وقال عن أنس في السحور مجهول، كنى ابن منده (١٥٠/ أ)، المقتنى في سرد الكنى (٦٧/ أ).\nربيعة بن كلثوم بن جبر، بجيم وموحدة ساكنة، بصرى، صدوق، يهم من ="}],[3712,"٢٤٢١ - أبو سنان البكرى، روى عن عمر، روى عنه حجاج بن أرطاة."],[3713,"باب أبى السوار"],[3714,"٢٤٢٢ - أبو السّوّار (١). عن خاله (٢)، (٣). روى عنه سميط بن عمير السدوسى (٤)."],[3715,"٢٤٢٣ - أبو السّوّار، السلمى، سمع أبا حاضر، روى عنه عباد بن العوام.","",{"fn":"السوّار: بتشديد الواو. الاكمال (٤/ ٣٨٧)، تبصير المنتبه (٢/ ٦٩٩).\nهكذا في الأصل عن خاله وكذا في مصادر الترجمة. ولم أقف على من سمى خاله.\nفي كنى الحاكم زيادة \"قال: رأيت النبى -صلى الله عليه وآله وسلم-\".\nسميط بن عمير، ويقال: ابن سمير، السدوسى البصرى، أبو عبد اللَّه، صدوق، من الثالثة. انظر التقريب (١/ ٣٣٤). ٢٤٢٣ - الجرح (٤/ ٢/ ٣٨٨)، كنى الحاكم (١/ ٢٠٨/ ب) ذكره كما هنا وقال: قاله محمد بن إسماعيل. قلت: ولم أقف عليه في الكنى المجردة للبخارى، تعجيل المنفعة (ص ٣٢٣)، المقتنى في سرد الكنى (٦٨/ أ)."}],[3716,"باب أبى سفيان"],[3717,"٢٤٢٤ - أبو سفيان بن سعد (١) بن الأخنس بن شريق الثقفى ابن أخت أم حبيبة، زوج النبى عليه السلام، روى عن خالته أم حبيبة، روى عنه أبو سلمة بن عبد الرحمن بن عوف."],[3718,"٢٤٢٥ - أبو سفيان مولى ابن - أحمد بن جحش (٢) والصواب مولى ابن أبى أحمد الأسدى (١). لا يصح له اسم غير كنيته. واللَّه أعلم. وقيل: إنه مولى لبنى عبد الأشهل والأول أكثر. كان له انقطاع إلى ابن أبى أحمد بن جحش فنسب إلى ولائه، روى عن أبى هريرة، وأبى سعيد الخدرى، روى عنه داود بن الحصين، وابنه عبد اللَّه بن أبى سفيان (٢)، وقيل: عبد الرحمن بن أبى سفيان وخالد بن رباح الهذلى.","",{"fn":"في التهذيب \"سعيد بن المغيرة\". ٢٤٢٥ - كنى البخارى (ص ٣٩)، الطبقات الكبرى (٥/ ٣٠٧) وقال: كان ثقة قليل الحديث، كنى مسلم (ص ٤٦٥)، الجرح (٤/ ٢/ ٣٨١)، الثقات (٥/ ٥٦١)، كنى ابن منده (١٤٨/ ب)، التهذيب (١٢/ ١١٣) وقال: قال الدارقطنى: اسمه وهب، وقال غيره: اسمه قزمان، وقال ابن حجر أيضًا: قال ابن عبد البر: قيل: اسمه قزمان، ولا يصح له اسم غير كنيته، التقريب (٢/ ٤٢٩) وقال: ثقة من الثالثة./ ع. قلت: ومن الجدير بالذكر أنه تقدم في الصحابة (٢٩٣) أبو سفيان والد عبد اللَّه بن أبى سفيان، روى عنه ابنه عبد اللَّه، وقال ابن عبد البر في ترجمته هناك، أخشى أن يكون حديثه مرسلا، وقد تقدم أبو سفيان صاحب هذه الترجمة أيضًا في الكتاب الثانى (١٠٨٩) وقال ابن عبد البر في ترجمته هناك: \"قيل: اسمه قزمان، ولا يصح\".\nهكذا قال ابن عبد البر هنا مولى ابن جحش، والصواب مولى ابن أبى أحمد الأسدى والذى في كنى مسلم، كنى ابن منده مولى أبى أحمد أو ابن أبى ="}],[3719,"٢٤٢٦ - أبو سفيان، سمع عليا رضي الله عنه، روى عمران بن سليمان (٣)."],[3720,"٢٤٢٧ - أبو سفيان الفلسطينى - شامى، روى عن بجير بن ريسان (٤)، روى عنه يحيى بن أبى كثير.","",{"fn":"ابن أبى أحمد الأسدى: ذكره ابن حجر في التقريب (١/ ٤٠١) فقال: عبد اللَّه بن أبى أحمد بن جحش الأسدى، ولد في حياة النبى -صلى الله عليه وآله وسلم-، روى عن عمر وغيره، وذكره جماعة في ثقات التابعين. اهـ.\nعبد اللَّه بن أبى سفيان، ذكره ابن أبى حاتم في الجرح (٢/ ٢/ ٦٧) وذكر روايته عن أبيه، ولم يذكر فيه شيئًا. ٢٤٢٦ - كنى البخارى (ص ٣٨)، الجرح (٤/ ٢/ ٣٨١).\nعمران بن سليمان المرادى، كوفى، ذكره ابن أبى حاتم (٣/ ١/ ٢٩٩) ولم يذكر فيه شيئًا. ٢٤٢٧ - كنى البخارى (ص ٣٩) وقال: روى عنه بقية، الجرح (٤/ ٢/ ٣٨١)، كنى ابن منده (١٤٨/ ب)، المقتنى في سرد الكنى (٦٢/ ب).\nذكره ابن أبى حاتم في الجرح (١/ ١/ ٤١١) فقال: بجير بن ريسان من أهل اليمن روى عن عبادة بن الصامت، روى عنه أبو سفيان الشامى. اهـ. ولم يذكر فيه جرحا."}],[3721,"٢٤٢٨ - أبو سفيان الأنمارى شامى. روى عن حبيب بن عبد اللَّه ابن أبى كبشة، ويحيى بن سعيد الأنصارى. روى عنه بقية بن الوليد. حديثه ليس بالقائم."],[3722,"٢٤٢٩ - أبو سفيان بن (. . . . .) (١) بن عبد المطلب بن أبى وداعة السهمى، روى عن أبيه عن (. . . . .) (٢) حديثه ليس بالقائم."],[3723,"٢٤٣٠ - أبو سفيان بن عبد الرحمن بن المطلب بن أبى وداعة السهمى. روى عن أبيه، عن جده. حديثه عند أبى عامر العقدى، عن عبد ربه بن عطاء اللَّه (٣) عنه."],[3724,"٢٤٣١ - أبو سفيان بن العلاء بن عمار بن العريان بن خزاعى بن مازن بن مالك بن عمرو بن تميم، بصرى أخو أبى عمرو بن العلاء، ومعاذ بن العلاء، روى عن الحسن بن أبى الحسن، وابن أبى عتيق، روى عنه شعبة بن الحجاج، وإسماعيل بن علية، ووكيع، وقال يحيى القطان: \"كنت اشتهى أن أسمع من أبى سفيان بن العلاء حديث الحسن (عن) (١) عبد اللَّه بن مغفل. كان يقول فيه: حدثنى ابن مغفل\" (٢).","",{"fn":"في الأصل بياض بمقدار كلمة.\nفي الأصل بياض بمقدار كلمة أيضًا. ٢٤٣٠ - كنى البخارى (ص ٣٩)، الجرح (٤/ ٢/ ٣٨١)، كنى ابن منده (١٤٨/ ب).\nعبد ربه بن عطاء اللَّه، القرشى، المكى، مجهول الحال، من الثامنة التقريب (١/ ٤٧١)، الجرح (٣/ ١/ ٤٣). ٢٤٣١ - كنى البخارى (ص ٣٩)، الجرح (٤/ ٢/ ٣٨٢)، كنى ابن منده (١٤٨/ ب)، المقتنى في سرد الكنى (٦٢/ ب)."}],[3725,"٢٤٣٢ - أبو سفيان بن جابر بن عتيك. قد نسبنا أباه في بابه من كتاب الصحابة (٣)، روى عن أبيه، روى عنه نافع بن يزيد، وسعيد بن أبى أيوب."],[3726,"٢٤٣٣ - أبو سفيان عن معروف السلمى لقيه بالموصل. روى عنه عبد الرحمن بن ثابت بن ثوبان.","",{"fn":"في الأصل \"بن\" وهو تصحيف. والصحيح \"عن\" كما هو مثبت وكما هو في مصادر الترجمة. والحسن هذا هو الحسن البصرى، وعبد اللَّه بن مغفل هو الصحابى المعروف، روى عنه الحسن البصرى. وانظر التهذيب (١/ ٤٢).\nانظر قول القطان هذا في كنى البخارى (ص ٣٩) والجرح (٤/ ٢/ ٣٨٢). ٢٤٣٢ - كنى البخارى (ص ٣٩) وقال: وكان قدم مصر، الجرح (٤/ ٢/ ٣٨١)، كنى ابن منده (١٤٨/ ب)، المقتنى في سرد الكنى (٦٢/ ب).\nالاستيعاب (١/ ٢٢٣) وقال: جابر بن عتيك الأنصارى العامرى من بنى عمرو بن عوف بن مالك بن الأوس ويقال: جبر بن عتيك. . وذكر أيضًا أنه شهد بدرًا وجميع المشاهد بعدها وتوفى سنة إحدى وستين وهو ابن إحدى وتسعين سنة يكنى أبا عبد اللَّه وكانت معه راية بنى معاوية عام الفتح. اهـ. ٢٤٣٣ - كنى ابن منده (١٤٨/ ب) وقال: أبو سفيان حدث عن معروف عن الحسن روى عنه عبد الرحمن بن ثابت بن ثوبان الشامى. المقتنى في سرد الكنى (٦٢/ ب) وقال: أبو سفيان عن معروف وعنه ابن ثوبان. اهـ."}],[3727,"٢٤٣٤ - أبو سفيان مدنى (١)، سمع أبا هريرة. روى عنه واصل بن سيف. قال أبو حاتم: هو مجهول."],[3728,"٢٤٣٥ - أبو سفيان، روى عن سالم الخياط (٢) عن الحسن، روى عنه إسماعيل بن إبراهيم الصائغ (٣)، مجهولان."],[3729,"٢٤٣٦ - أبو سفيان الصواف، بصرى، روى عن ابن عون قال عباس عن ابن معين: كان كذابا (١).","",{"fn":"في كنى البخارى \"المقرنى\" وفى الثقات \"المزنى\". ٢٤٣٥ - الجرح (٤/ ٢/ ٣٨٢) وقال: سألت أبى عنه فقال: هو مجهول. الميزان (٤/ ٥٣٢) وقال: هو مجهول، اللسان (٧/ ٥٥) وقال: مجهول.\nسالم بن عبد اللَّه الخياط، بصرى، نزل مكة، وهو سالم مولى عكاشة، وقيل: هما اثنان صدوق، سئ الحفظ، من السادسة. التقريب (١/ ٢٨٠).\nإسماعيل بن إبراهيم بن ميمون الصائغ خراسانى نزل مكة قال أبو حاتم: هو شيخ. انظر الجرح (١/ ١/ ١٥٢). ٢٤٣٦ - الجرح (٢/ ٢/ ٣١٨) و(٤/ ٢/ ٣٨٢)، الميزان (٣/ ٩) و(٤/ ٥٣١) اللسان (٤/ ١٠٤ و٧/ ٥٤). ذكره ابن أبى حاتم أولا في عبيد اللَّه بن سفيان بن رواحة أبو سفيان الصواف وقال: سألت أبى عنه فقال: هو شيخ ليس بالقوى وذكره ابن أبى حاتم مرة ثانية في الكنى من الجرح (٤/ ٢/ ٣٨٢) وذكر قول ابن معين فيه، وذكره الذهبى في الميزان (٣/ ٩) فقال: عبيد اللَّه بن سفيان أبو سفيان عن ابن عون وقال: كذبه ابن معين ووهى ابن حبان حديثه وهو غدانى بصرى، روى عنه أحمد بن سنان القطان وغيره والكديمى وعبد الرحمن بن بشر ويعرف بابن رواحة، وذكره الذهبى مرة ثانية في الكنى فقال أبو سفيان الصيرفى عن ابن عون قال الأزدى: يكذب وكذا كذبه ابن معين وقيل فيه: الصواف. وقيل: هما اثنان، والصواف اسمه عبيد اللَّه والصيرفى يقال له: ابن رواحة هو صاحب ابن عون."}],[3730,"٢٤٣٧ - أبو سفيان بن عبد ربه، روى عن عمر بن نبهان (٢)، روى عنه عمرو بن أبى قيس (٣). هو عندهم مجهول."],[3731,"٢٤٣٨ - أبو سفيان، عن عبد اللَّه بن دينار، روى عنه منصور (٤) بن دينار (٥)، لم يعرفه أبو زرعة.","",{"fn":"انظر تاريخ ابن معين (٢/ ٣٨٢) وقال: عبيد اللَّه بن سفيان بن عبد اللَّه بن رواحة، أبو سفيان الصواف، كان كذابا، وكان يقال له: ابن رواحة وقد قدم علينا، وهو بصرى، وكان يروى عن ابن عون. وانظر قول ابن معين أيضًا في مصادر الترجمة كما تقدم. ٢٤٣٧ - الجرح (٤/ ٢/ ٣٨٢) وقال: سألت أبى عنه فقال: هو شيخ مجهول، الميزان (٤/ ٥٣٢) وقال: مجهول، اللسان (٧/ ٤٦٧) وقال: قال أبو حاتم شيخ. وذكره ابن أبى حاتم أيضًا في الجرح (٢/ ٢/ ٢٥٦) فقال: عبد الرحمن بن عبد ربه الشيبانى قاضى نيسابور، قدم الرى، ويعرف بأبى سفيان بن عبد ربه، وذكر روايته عن عمر بن نبهان وآخرين ورواية عمر بن أبى قيس وآخرون عنه. وقال أيضًا: سألت أبى عنه فقال: شيخ. اهـ.\nعمر بن نبهان بفتح النون وسكون الموحدة العبدى، ويقال: الغبرى بضم المعجمة وفتح الموحدة الخفيفة، بصرى خال محمد بن بكر، ضعيف من السابعة. التقريب (٢/ ٦٤) وذكره ابن أبى حاتم في الجرح (٣/ ١/ ١٣٨) وذكر رواية أبى سفيان عبد الرحمن بن عبد ربه بن تميم عنه. وقال: سألت أبى عنه فقال: ضعيف الحديث. اهـ.\nعمرو بن أبى قيس الكوفى، نزيل الرى، ذكره ابن أبى حاتم في الجرح (٣/ ١/ ٢٥٥) ولم يذكر فيه شيئًا. ٢٤٣٨ - كنى مسلم (ص ٤٦٥)، الجرح (٤/ ٢/ ٣٨٢) وقال: سئل أبو زرعة عنه فقال: لا أعرفه.\nفي كنى مسلم \"معتمر\".\nمنصور بن دينار التميمى، ذكره ابن أبى حاتم في الجرح (٤/ ١/ ١٧١) ="}],[3732,"٢٤٣٩ - أبو سفيان. روى عن مسلم بن كثير (١). عن عمرو بن حَرِيش (٢) عن عبد اللَّه بن عمرو بن العاص. روى عنه محمد بن إسحاق بن يسار. قال عثمان بن سعيد الدارمى: قلت ليحيى بن معين: محمد بن إسحاق روى عن أبى سفيان ما حال أبى سفيان؟ فقال: ثقة مشهور (قلت) (٣) عن مسلم بن كثير عن عمرو بن حريش الزّبيدى؟ قال: هذا حديث مشهور (٤).","",{"fn":"مسلم بن كثير. ذكره ابن أبى حاتم في الجرح (٤/ ١/ ١٩٣) فقال: مسلم ابن كثير. روى عن عمرو بن حريش الزبيدى، عن عبد اللَّه بن عمرو بن العاص روى عنه أبو سفيان. قلت: وقد قيل فيه مسلم بن جبير، بل ذكره الكثيرون في مسلم بن جبير وسيأتى ذكره أيضًا عند تخريج الحديث.\nعمرو بن حَرِيش، بفتح أوله، وآخره معجمة، الزبيدى، بضم أوله له حديث مشهور، وهو مجهول الحال، من الرابعة، وزعم ابن حبان أنه عمرو بن حبشى فوهم، انظر تهذيب الكمال (٢/ ١٠٢٩ - ١٠٣٠) التقريب (٢/ ٦٨).\nالحق في هامش الأصل، كتب عنده \"صح\".\nانظر قول عثمان بن سعيد الدارمى عن يحيى في تاريخ ابن معين رواية الدارمى (ص ١٩٩) قلت: والحديث المشار إليه في هذه الترجمة هو ما رواه محمد بن إسحاق عن أبى سفيان عن مسلم، عن عمرو بن حريش الزبيدى قال: قلت لعبد اللَّه بن عمرو إنا بأرض ليس بها ذهب ولا فضة نبيع البقرة بالبقرتين والبعير بالبعيرين، والشاة بالشاتين. فقال: أمرنى رسول اللَّه -صلى الله عليه وآله وسلم- أن ="}],[3733,". . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . ."],[3734,". . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . ."],[3735,"باب أبى سبرة"],[3736,"٢٤٤٠ - أبو سَبْرة (١)، روى عن محمد بن كعب القرظى، روى عنه الأعمش قال ابن معين: لا أعرفه."],[3737,"٢٤٤١ - أبو سبرة النخعى (٢) كوفى روى عن فروة بن مُسَيك (٣)، (٤). روى عنه الحسن بن الحكم النخعى (٥).","",{"fn":"سبرة: بفتح السين المهملة، وسكون الموحدة. كما في التقريب (٢/ ٤٢٦) وتبصير المنتبه (٢/ ٦٧٣). ٢٤٤١ - كنى البخارى (ص ٤٠)، الجرح (٤/ ٢/ ٣٨٥)، الثقات (٥/ ٥٦٩) تهذيب الكمال (٣/ ١٦٠٧)، التهذيب (١٢/ ١٠٥) وجعله هو والذى قبله واحدًا ثم قال: وقد قيل: أن الراوى عن فروة بن مسيك غير الراوى عن محمد بن كعب القرظى. فاللَّه أعلم. التقريب (٢/ ٤٢٦) وقال: أبو سبرة، بسكون الموحدة. النخعى، الكوفى، يقال: اسمه عبد اللَّه بن عابس، مقبول، من الثالثة./ د. ت. ق.\nفي الثقات \"البجلى\".\nفروة بن مسيك: بمهملة مصغرا، المرادى، ثم الغُطَيْفى بمعجمة مصغرا، صحابى سكن الكوفة، يكنى أبا عمير، واستعمله عمر. قال ابن حبان في الثقات (٥/ ٥٦٩): له صحبة. وانظر التجريد (٢/ ٧).\nزاد في الثقات \"وله صحبة\".\nالحسن بن الحكم النخعى، أبو الحكم الكوفى، صدوق يخطئ، من السادسة. مات قبيل الخمسين. التقريب (١/ ١٦٥)."}],[3738,"٢٤٤٢ - أبو سبرة عن شريح في الرهن (١). روى عنه سيار. قال ابن أبى حاتم: سمعت أبى وأبا زرعة يقولان ذلك.","",{"fn":"لم أقف على هذا الخبر من هذا الطريق وقد رويت أخبار عن شريخ في الرهن انظر مصنف ابن أبى شبية (٦/ ٢١) مصنف عبد الرزاق (٢/ ٢٣٨ و٢٣٩ و٢٤٧). وأخرج وكيع في أخبار القضاة (٢/ ٢٩٩) من طريق هشيم عن سيار عن أبى سبرة سمع شريحا يقول: \"ذهبت الرهان بما فيها\" وأخرجه أيضًا وكيع في أخبار القضاة (٣/ ٢٣٠ و٢٤١ و٢٤٢ و٢٦٥ و٢٨٧ و٢٩٩ و٣٧٣ و٣٨٧) من طرق عن شريح به وبنحوه وفى أحد ألفاظه أنه سئل وإن كان أقل أو أكثر قال: نعم وفى لفظ آخر عن شريح قال إذا كان الرهن بأقل ممن رهن قال: أنت رضيت به من حقك وإذا كان أكثر قال: أنت أغلقته."}],[3739,"باب أبى السائب"],[3740,"٢٤٤٣ - أبو السائب الأنصارى المدنى، مولى هشام بن زهرة، وقيل: مولى عبد اللَّه بن هشام بن زهرة (١)، وقيل: مولى بنى عبد اللَّه بن هشام بن زهرة. وقيل: مولى بنى زهرة وأصح ما في ذلك قول من قال مولى هشام بن زهرة وهو قول الحفاظ من أصحاب العلاء بن عبد الرحمن، كان من جلساء أبى هريرة. روى عن أبى هريرة وسعد بن أبى وقاص وأبى سعيد الخدرى. روى عنه العلاء بن عبد الرحمن، وشريك بن عبد اللَّه بن أبى نمر وبكير بن الأشج وصيفى (٢) بن أفلح، ومحمد بن عمرو بن عطاء، وعبيد اللَّه بن عمر، وقد روى عن ابن شهاب الزهرى، وصفوان بن سليمان عنه من طرق ليست بالقوية، أجمعوا على أن أبا السائب هذا ثقة مقبول النقل (١).","",{"fn":"عبد اللَّه بن هشام بن زهرة بن عثمان التيمى، صحابى، صغير مات في خلافة معاوية. انظر التقريب (١/ ٤٥٨).\nهكذا في الأصل \"صيفى بن أفلح\" وفى التهذيب \"صيفى مولى أفلح\" وذكره البخارى في التاريخ الكبير (٢/ ٢/ ٣٢٣) فقال: صيفى أبو زياد مولى أفلح مولى أبى أيوب عن أبى السائب ولم يذكر فيه شيئًا. وذكره ابن أبى حاتم في الجرح (٢/ ١/ ٤٤٨) ولم يذكر فيه شيئًا. وذكره ابن حبان في الثقات (٤/ ٣٨٤) وقال: عداده في أهل المدينة."}],[3741,"٢٤٤٤ - أبو السائب المخزومى. روى عن جدته آمنة بنت الأرقم (٢) روى عنه الحسين (٣) بن زيد بن على بن حسين بن على رضي الله عنهم.","",{"fn":"يذكر ابن حجر في التهذيب (١٢/ ١٠٤) قال: \"قال ابن عبد البر أجمعوا على أنه ثقة مقبول النقل\". ٢٤٤٤ - كنى ابن منده (١٥٢/ أ)، الميزان (٤/ ٥٢٧) وقال: مجهول، اللسان (٧/ ٥٠).\nآمنة بنت الأرقم. ذكرها ابن حجر في الإصابة (٤/ ٢٢٤) وقال: روى أبو السائب المخزومى عن جدته آمنة بنت الأرقم أن النبى -صلى الله عليه وآله وسلم- أقطعها بئرا ببطن العقيق فكانت تسمى بئر آمنه وبرك لها فيها، وكانت من المهاجرات ذكرها ابن الدباغ مستدركا على الاستيعاب. اهـ.\nالحسين بن زيد بن على بن الحسين بن على، صدوق، ربما أخطأ من الثامنة مات وله ثمانون سنة. انظر التقريب (١/ ١٧٦)."}],[3742,"باب أبى سلامة"],[3743,"٢٤٤٥ - أبو سلامة الشيبانى. سمع عمر بن الخطاب. روى عنه سماك بن حرب."],[3744,"٢٤٤٦ - أبو سلامة مولى الفهريين هكذا قال الحاكم في الكنى وقال ابن أبى حاتم: أبو سلام. روى عن على بن عبد اللَّه بن عباس. قال: سمعت على ابن عبد اللَّه بن عباس يقول: \"إذا جامعت فاستتر من السماء\". روى عنه معن بن عيسى."],[3745,". . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . ."],[3746,"باب أبى سويد"],[3747,"٢٤٤٧ - أبو سويد - القضاعى (١) سمع تبيعا (٢). روى عنه عبد اللَّه بن أبى رفيق الأزدى (٣)."],[3748,"٢٤٤٨ - أبو سويد العبدى يقال: أبو سويد بن المغيرة. روى عن الحسن عن الأحنف أنه قدم على عمر (١). روى عنه حماد بن زيد وبركة بن يعلى التميمى (٢).","",{"fn":"القضاعى: بضم القاف وفتح الضاد المعجمة وفى آخرها عين مهملة - هذه النسبة إلى قضاعة، شعب عظيم يشتمل على قبائل كثيرة. اللباب (٣/ ٤٣).\nزاد البخارى في الكنى \"مرسل\".\nعبد اللَّه بن أبى رُفَيْق، بضم الراء وبعدها فاء مفتوحة. ذكره ابن أبى حاتم في الجرح (٢/ ٢/ ٥٥) وذكر روايته عن أبى سويد القضاعى عن تبيع ولم يذكر فيه شيئا. وانظر الاكمال (٤/ ٨٢). ٢٤٤٨ - كنى ابن منده (١٥٣/ ب)، الجرح (٤/ ٢/ ٣٨٥)، الثقات (٧/ ٦٦٢) تعجيل المنفعة (ص ٣٢٣) وقال: أورده الحاكم أبو أحمد فيمن لا يعرف اسمه ونقل عن البخارى من طريق وكيع عن بركة عنه. قال: كنا بباب عمر رضي الله عنه فذكر قصته. اهـ. ومن الجدير بالذكر أن البخارى جعله هو والذى قبله واحدا فقال: أبو سويد القضاعى سمع تبيعا مرسل، قاله سعيد بن أبى أيوب عن عبد اللَّه بن أبى رفيق قال سليمان بن حرب: نا حماد بن زيد قال: نا أبو سويد وهو ابن المغيرة عن الحسن أن الأحنف بن قيس قدم على عمر في وفد أهل البصرة فسرحهم واحتبس الأحنف حولا ثم دعاه فقال: إن النبى -صلى الله عليه وآله وسلم- حذرنا كل منافق عالم اللسان وأنى تخوفت أن تكون منهم وأنا أرجو أن لا تكون فالحق بأهلك. اهـ.\nانظر كنى البخارى (ص ٤١)، الجرح (٤/ ٢/ ٣٨٥)، تعجيل المنفعة (ص ٣٢٣) في هذا الخبر.\nبركة بن يعلى التميمى، قال الذهبى: وتبعه ابن حجر: لا يعرف. انظر الميزان (١/ ٣٠٤)، اللسان (٢/ ٨)."}],[3749,"باب أبى سيف"],[3750,"٢٤٤٩ - أبو سيف مولى عبد الرحمن بن سمرة القرشى (١)، روى عنه ثابت ابن أسلم البنانى قوله."],[3751,"٢٤٥٠ - أبو سيف. روى عن الحسن قوله. روى عنه يعقوب بن القعقاع (٢)."],[3752,"٢٤٥١ - أبو سيف. روى عن الأعمش. روى عنه يعقوب القمىّ.","",{"fn":"زاد في الثقات \"يروى عن عبد الرحمن بن سمرة\". ٢٤٥٠ - كنى البخارى (ص ٤١)، الجرح (٤/ ٢/ ٣٨٥)، كنى ابن منده (١٥٣/ ب)، المقتنى في سرد الكنى (٦٨/ ب).\nيعقوب بن القعقاع بن الأعلم الأزدى أبو الحسن الخراسانى، ثقة من السادسة، التقريب (٢/ ٣٧٦)، الجرح (٤/ ٢/ ٢١٣). ٢٤٥١ - الجرح (٤/ ٢/ ٣٨٥) وقال: سألت أبى عنه فقال: لا أعرفه. كنى ابن منده (١٥٣/ ب)."}],[3753,"باب أبى سهلة"],[3754,"٢٤٥٢ - أبو سهلة، مولى عثمان بن عفان. وقيل: أبو سهيلة - كوفى روى عن عائشة زوج النبى عليه السلام وعن عثمان بن عفان. روى عنه قيس بن أبى حازم."],[3755,"٢٤٥٣ - أبو سهلة البصرى، روى عن أبى هريرة. روى عنه سليمان التيمى."],[3756,"باب أفراد في الكنى"],[3757,"٢٤٥٤ - أبو سلام. روى عن أبى محذورة في الأذان (١). قال أبو حاتم: لا أعلمه يسمى."],[3758,"٢٤٥٥ - أبو سارية، سمع أنس بن مالك. روى عنه هشام بن سعد."],[3759,"٢٤٥٦ - أبو سُمَيَّة مذكور في حديث (٢) جابر لا نعرفه بغير ذلك. سئل أبو زرعة عن اسمه فقال: لا أعرف اسمه.","",{"fn":"تقدم حديث أبى محذورة في الأذان في (١٦٨). ٢٤٥٥ - كنى ابن منده (٥٤/ أ)، الجرح (٤/ ٢/ ٣٨٧)، كنى الحاكم (١/ ٢١٦/ ب) وقال: قاله محمد بن إسماعيل. اهـ. قلت: ولم أقف عليه في الكنى المجردة للبخارى وذلك لوجود سقط في باب السين فيه. واللَّه أعلم. ٢٤٥٦ - كنى ابن منده (٥٤/ ب)، تهذيب الكمال (٣/ ١٦١٢)، الجرح (٤/ ٢/ ٣٨٨)، الثقات (٥/ ٥٦٩)، كنى الحاكم (١/ ٢١٦/ ب) الميزان (٤/ ٥٣٤)، وقال: مجهول، اللسان (٧/ ٥٨)، التهذيب (١٢/ ١٢٠)، التقريب (٢/ ٤٣١) وقال: أبو سمية بالتصغير، عن جابر، مقبول، من الرابعة./ ق.\nالحديث أخرجه أبو أحمد الحاكم في الكنى (١/ ٢١٦/ ب) من طريق كثير ابن زياد عن أبى سمية قال: سألت جابرًا فقلت سمعت النبى -صلى الله عليه وآله وسلم- يقول: الورود الدخول \"ثم ننجى الذين اتقوا\" اهـ. يشير بذلك إلى الآيتين ٧١، ٧٢ من سورة مريم وهو قوله تعالى ﴿وَإِنْ مِنْكُمْ إِلَّا وَارِدُهَا كَانَ عَلَى رَبِّكَ حَتْمًا مَقْضِيًّا. ثُمَّ نُنَجِّي الَّذِينَ اتَّقَوْا وَنَذَرُ الظَّالِمِينَ فِيهَا جِثِيًّا﴾. . وأخرجه أحمد في المسند (٣/ ٣٢٨) من طريق كثير بن زياد البرسانى عن أبى سمية قال: اختلفنا ههنا في الورود فقال بعضنا: لا يدخلها مؤمن وقال بعضنا ="}],[3760,"٢٤٥٧ - أبو السّكن (١) الهجرى. روى عن جابر عن النبى عليه السلام. روى الصمد بن عبد الوارث عن صدقة (٢) عنه.","",{"fn":"سكن: بسين مهملة مفتوحة وآخره نون. الاكمال (٤/ ٣٢١).\nصدقة بن موسى، الدَّقِيقى، أبو المغيرة أو أبو محمد، السّلمى البصرى صدوق، له أوهام، من السابعة. التقريب (١/ ٣٦٦)، التهذيب (٤/ ٤١٨)."}],[3761,"٢٤٥٨ - أبو سُخَيْلة (١) روى عن على. روى عنه الخضر بن القوّاس (٢) سئل أبو زرعة عن اسم أبى سخيلة فقال: لا أعرف اسمه."],[3762,"٢٤٥٩ - أبو سيّار (٣) الغنوى. روى عن أبيه (٤) عن عمر بن عبد العزيز روى عنه أبو سلمة موسى بن إسماعيل."],[3763,"٢٤٦٠ - أبو سيّارة (٥) روى عن محمد بن كعب القرظى. روى عنه ابن زَحْر (٦) أظنه الغنوى.","",{"fn":"سخيلة: بضم السين المهملة وفتح الخاء المعجمة، مصغرًا، انظر التقريب (٢/ ٤٢٦) والخلاصة (ص ٤٥٠).\nالخضر بن القوّاس، مجهول، من السادسة. التقريب (١/ ٢٢٤). ٢٤٥٩ - لم أقف له على ترجمة عند غير المؤلف.\nسيّار: أوله سين مهملة ثم ياء معجمة باثنتين من تحتها وآخره راء. الاكمال (٤/ ٤٢٣).\nلم أقف عليه. ٢٤٦٠ - لم أقف له ترجمة عند غير المؤلف.\nسيّارة: كالذى قبله، وبزيادة التاء المربوطة في آخره. تبصير المنتبه (٢/ ٧٠٤).\nزحر: أوله زاى بعدها حاء مهملة كما في الاكمال (٤/ ١٧٨) وقال في التقريب (١/ ٥٣٣) عبيد اللَّه بن زحر: بفتح الزاى وسكون المهملة، الضمرى، مولاهم الإفريقى، صدوق، يخطئ، من السادسة وانظر الجرح (٢/ ٢/ ٣١٥)."}],[3764,"٢٤٦١ - أبو سَوْرة (١)، ابن أخى أيوب الأنصارى، روى عن أبى أيوب روى عنه واصل بن السائب (٢)."],[3765,"٢٤٦٢ - أبو سهيل بن مسلم، روى عن أنس بن مالك، عن النبى عليه السلام أنه قال: \"طلب العلم فريضة على كل مسلم\" (٣). روى عنه إسماعيل بن عيّاش.","",{"fn":"سَوْرة: بفتح أوله وسكون الواو بعدها راء. كما في التقريب (٢/ ٤٣٢).\nواصل بن السائب الرقاشى، أبو يحيى البصرى، ضعيف، من السادسة (ت: ١٤٤). انظر التقريب (٢/ ٣٢٨). ٢٤٦٢ - الجرح (٤/ ٢/ ٣٨٨).\nالحديث أخرجه ابن ماجه \"المقدمة\" باب فضل العلماء والحث على طلب ="}],[3766,". . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . ."],[3767,"حرف الشين"],[3768,"باب أبى شعيب"],[3769,"٢٤٦٣ - أبو شعيب الحضرمى، شامى، روى عن أبى أيوب الأنصارى، روى عنه عثمان بن أبى سودة، من حديث - الأوزاعى، عن عثمان بن أبى سودة."],[3770,"٢٤٦٤ - أبو شعيب، رأى عبد اللَّه بن عمر يحلق عنه الشعر من حديث وكيع عن عبيد بن عبد الملك (١)."],[3771,"٢٤٦٥ - أبو شعيب سمع الحسن وقتادة ويونس بن عبيد. روى عنه يزيد بن هارون."],[3772,"٢٤٦٦ - أبو شعيب (٢) روى عن طاوس عن ابن عمر في الركعتين قبل المغرب (١). (ذكر إسحاق بن) (٢) منصور عن يحيى بن معين أنه قال: أبو شعيب الذى روى عن طاوس عن ابن عمر مشهور بصرى (٣).","",{"fn":"عبيد بن عبد الملك أبو عبد الملك الأسدى ذكره ابن أبى حاتم في الجرح (٢/ ٢/ ٤١١) وذكر رواية وكيع عنه. وقال: سألت أبى عنه فقال: ما به بأس. ٢٤٦٥ - الجرح (٤/ ٢/ ٣٨٩)، كنى الحاكم (١/ ٢٢٤/ أ) وقال: أبو شعيب شيخ من بنانه. ثم ذكره وقال: قاله محمد بن إسماعيل. ٢٤٦٦ - كنى ابن منده (١٥٧/ أ)، الجرح (٤/ ٢/ ٣٨٩)، الثقات (٦/ ٤٤٠) التهذيب (٤/ ٣٥٨)، التقريب (١/ ٣٥٣) وقال: بصرى، لا بأس به يقال: اسم أبيه بيان، من السابعة./ د.\nفي الثقات، والتهذيب والتقريب \"شعيب\" من غير ذكر الكنية وقال ابن حجر في التهذيب (٤/ ٣٥٨) قال أبو داود عن ابن معين وهم شعبة إنما هو شعيب\"."}],[3773,"٢٤٦٧ - أبو شعيب روى عن جده (٤) عن ابن مسعود، روى عنه عبد اللَّه ابن عون بصرى.","",{"fn":"الحديث أخرجه أبو داود \"الصلاة\" باب الصلاة قبل المغرب (٢/ ٢٦) من طريق ابن بشارتنا محمد بن جعفر، ثنا شعبة، عن أبى شعيب، عن طاووس، قال: سئل ابن عمر عن الركعتين قبل المغرب فقال: ما رأيت أحدًا على عهد رسول اللَّه -صلى الله عليه وآله وسلم- يصليهما ورخص في الركعتين بعد العصر، قال أبو داود: سمعت يحيى بن معين يقول: هو شعيب -يعنى وهم شعبة في اسمه- اهـ. ومن طريق أبى داود أخرجه البيهقى (٢/ ٤٧٦ - ٤٧٧) به.\nغير واضح في الأصل والمثبت عن الجرح.\nانظر الجرح (٤/ ٢/ ٣٨٩). ٢٤٦٧ - الجرح (٤/ ٢/ ٣٨٩)، كنى الحاكم (١/ ٢٢٤/ أ) وذكره كما هنا وقال قاله محمد بن إسماعيل، كنى ابن منده (١٥٧/ أ)، المقتنى في سرد الكنى (١٧٠/ أ).\nلم أقف على من سمى جده هذا."}],[3774,"باب أبى شيبة"],[3775,"٢٤٦٨ - أبو شيبة. روى عن عمرو بن عبسة (١)، روى عنه جنادة بن أبى خالد (٢). هكذا قال أبو أحمد الحاكم. وقال أبو شيبة المهرى. روى عن ثوبان. روى عنه بلج (٣) المهرى - جعلهما رجلين. وقال ابن أبى حاتم: عن أبيه أبو شيبة المهرى. روى عن ثوبان وعمرو بن عبسة. روى عنه (بلج وجنادة بن أبى خالد) (٤) جعله رجلًا واحدًا. وقال: سئل أبو زرعة عن أبى شيبة المهرى فقال: هو من التابعين لا أعرف اسمه.","",{"fn":"هو أبو نجيح تقدم في الصحابة (١٩٩).\nجنادة بن أبى خالد الدمشقى، ذكره ابن أبى حاتم في الجرح (١/ ١/ ٥١٥) وذكر روايته عن أبى شيبة المهرى ولم يذكر فيه شيئًا.\nبلج: بفتح الباء وسكون اللام. كما في الاكمال (١/ ٣٥٠) وقال: بلج المهرى عن أبى شيبة المهرى عن ثوبان. وقال ابن حجر في اللسان (٢/ ٦٣): بلج المهرى، عن أبى شيبة المهرى عن ثوبان قاء فأفطر لا يدرى من ذا ولا من شيخه. رواه شعبة عن أبى الجودى عنه قال البخارى إسناده ليس بمعروف. اهـ. وذكره ابن حبان في الثقات (٦/ ١١٨) فقال بلج بن عبد اللَّه المهرى. وذكر روايته عن أبى شيبة المهرى عن ثوبان. فاللَّه أعلم.\nفي الأصل \"بلج بن أبى جنادة\" ولم أقف على من اسمه بلج بن أبى جنادة والمثبت في الجرح وفى تعجيل المنفعة وفى المراجع الأخرى \"بلج وجنادة ابن أبى خالد\" كما أثبته وهو الصواب واللَّه أعلم."}],[3776,"٢٤٦٩ - أبو شيبة (١)، روى عن عيسى بن الحارث (٢)، روى عنه شعبة بن الحجاج."],[3777,"٢٤٧٠ - أبو شيبة المكى، روى عن عكرمة، عن ابن عباس أنه كان ينام بين جاريتين (٣). روى عنه عباد بن العوام وابن أبى زائدة.","",{"fn":"ذكر ابن أبى حاتم في ترجمة شيخه عيسى بن الحارث كما سيأتى أنه أبو شيبة جد بنى أبى شيبة.\nعيسى بن الحارث ذكره ابن أبى حاتم في الجرح (٣/ ١/ ٢٧٤) وذكر رواية أبى شيبة جد بنى شيبة عنه. وقال: سألت أبا زرعة عنه فقال: لا بأس به. ٢٤٧٠ - الجرح (٤/ ٢/ ٣٩٠) وقال: سئل أبو زرعة عن أبى شيبة المكى فقال: روى عنه ابن أبى زائدة وعباد بن العوام، ولا يعرف اسمه. كنى الحاكم (١/ ٢١٩/ أ).\nأخرجه الحاكم في الكنى وابن أبى حاتم في الجرح. انظر مصادر الترجمة وأخرجه أيضًا ابن أبى شيبه (٤/ ٣٨٩) من طريق عباد بن العوام عن أبى شيبة قال: سمعت عكرمة يحدث عن ابن عباس قال: كان ينام بين جاريتين. وأخرج ابن أبى شيبة عن عطاء أيضًا أنه كان لا يرى بأسا أن ينام الرجل بين الامتين."}],[3778,"باب أبى شداد"],[3779,"٢٤٧١ - أبو شداد عقل متوفى رسول اللَّه -صلى الله عليه وآله وسلم- ولم يره ولم يسمع منه ودخل على أبى أمامة الباهلى. روى عنه معاوية بن صالح."],[3780,"باب أبى شعبة"],[3781,"٢٤٧٢ - أبو شعبة (١) مولى سويد بن مُقَرِّن (٢)، روى عنه محمد بن المنكدر، يعد في أهل الحجاز."],[3782,"٢٤٧٣ - أبو شعبة الأشجعى، رجل من أهل البصرة، روى عن - عبد اللَّه ابن عمر، روى هلال بن يساف."],[3783,"٢٤٧٤ - أبو شعبة الدُّهْنِى (٣)، وقيل التميمى، رأى الحسن والحسين وروى عن أبى ذر، روى عنه ليث بن أبى سليم، وعمار بن معاوية الدهنى، وسفيان بن عيينة.","",{"fn":"زاد في التهذيب \"المدنى\".\nسويد بن مُقَرِّن، بضم ففتح فكسر مع التشديد، المزنى، صحابى مشهور، نزل الكوفة. التقريب (١/ ٢٤١). ٢٤٧٣ - الجرح (٤/ ٢/ ٣٩٠)، كنى الحاكم (١/ ٢١٩/ ب)، كنى ابن منده (١٥٦/ ب)، المقتنى في سرد الكنى (٦٩/ ب). ٢٤٧٤ - كنى مسلم (ص ٥٠٠)، كنى الحاكم (١/ ٢١٩/ ب)، كنى ابن منده (١٥٦/ ب).\nالدُّهْنِى: بضم الدال المهملة وسكون الهاء وفى آخرها نون نسبة إلى دُهْن ابن معاوية بن أسلم بن أحمس بن الغوث بن انمار وهو بطن من بَجِيْلة. اهـ. اللباب (١/ ٥٢٠)."}],[3784,"٢٤٧٥ - أبو شعبة عن عبد الرحمن بن فارس الغفارى وقيل: ابن الفارس بن الأبلق روى عنه عبد الملك بن ميسرة، يعد في الكوفيين."],[3785,"٢٤٧٦ - أبو شعبة الحنفى ويقال: الحنظلى روى عنه ابنه الربيع أو أبو الربيع (١).","",{"fn":"لم أقف له على ترجمة."}],[3786,"باب أبى الشعثاء"],[3787,"٢٤٧٧ - أبو الشّعثاء الكوفى، روى عن ابن عمر، وابن عباس اختلف فيه، روى عنه أبو سنان (١) وسعيد بن سعيد التغلبى (٢) وقد قيل: (أن الذى) (٣) روى عنه سعيد بن سعيد التغلبى غير الكندى الذى روى عنه أبو سنان (وأن الذى روى عنه سعيد بن سعيد التغلبى غير الكندى الذى روى عنه أبو سنان) (٤) وإن الذى روى عنه سعيد بن سعيد لم يرو عنه ابن عباس."],[3788,"وقال على بن المدينى. أبو الشعثاء الذى روى عنه أبو إسحاق الهمدانى، ويونس بن أبى إسحاق، وأبو العنبس (٥)، وأبو سنان هو الكندى، وليس هو أبو الشعثاء سليم والد أشعث (٦)، (٧) وقال ابن أبى حاتم: خالف أبى عليا في ذلك فقال: أبو الشعثاء الكندى اسمه يزيد بن مهاصر (١)، (٢).","",{"fn":"زاد في الجرح \"الشيبانى\" ولعله أبو سنان سعيد بن سنان الشيبانى الكوفى. المتقدم في الكتاب الثانى (١١٠٤).\nسعيد بن سعيد التغلبى: بمثناة ومعجمة، الكوفى أبو الصباح مقبول، من السادسة./ س. التقريب (١/ ٢٩٧) وذكره ابن أبى حاتم في الجرح (٢/ ١/ ٢٥) وذكر روايته عن أبى الشعثاء ولم يذكر فيه شيئًا.\nغير واضح في الأصل. والسياق يقتضى إثباته فأثبت.\nهكذا مكرر في الأصل. وهو كما يبدو سهو من الناسخ.\nهو الأكبر تقدم في (٢٢٤٥) وذكر ابن أبى حاتم في الجرح (٤/ ٢/ ٤١٩) في ترجمة أبى العنبس أنه روى عن أبى الشعثاء عن ابن عباس.\nهو أبو الشعثاء المحاربى سليم بن أسود تقدم في الكتاب الثانى (١١٤٣).\nانظر قول ابن المدينى هذا في كنى الحاكم (١/ ٢٢١/ أ) في ترجمة أبى الشعثاء يزيد بن مهاصر الكندى. وفى الجرح (٤/ ٢/ ٣٩١) في ترجمة أبى الشعثاء الكوفى وهى الترجمة التى نحن بصددها."}],[3789,"٢٤٧٨ - أبو الشعثاء، قنبر مولى عمر بن عبيد اللَّه معمر، سمع عبد اللَّه بن عباس، وعبد اللَّه بن عمر، روى عنه (صالح بن عبيد) (٣) والمثنى بن سعيد (٤)، يعد في البصريين."],[3790,"٢٤٧٩ - أبو الشعثاء، عن عبد اللَّه بن بريدة (وعنه) (٥) عبد الملك بن أبى سليمان إن صح عنه.","",{"fn":"ذكره ابن أبى حاتم في الجرح (٤/ ٢/ ٢٨٧) فقال: أبو يزيد بن مهاصر أبو الشعثاء الكندى كوفى، روى عنه أبو إسحاق الهمدانى وأبو العنبس بن أبى إسحاق وأبو سنان الشيبانى. ولم يذكر فيه شيئا.\nذكره في ترجمة أبى الشعثاء الكوفى بعد قول ابن المدينى. انظر الجرح (٤/ ٢/ ٣٩١). ٢٤٧٨ - تقدم في الكتاب الثانى (١١٤٤) أبو الشعثاء قنبر مولى ابن عمر سمع ابن عمر وابن عباس روى عنه صالح السلمى وأبو غفار. والظاهر أن الترجمتين لرجل واحد. واللَّه أعلم.\nهكذا هنا \"صالح بن عبيد\" وفى ترجمة أبى الشعثاء المتقدمة في (١١٤٤) صالح السلمى. وقد تقدمت ترجمته هناك.\nهو أبو غفار تقدم في الكتاب الثانى (١٠٣٦). ٢٤٧٩ - كنى ابن منده (١٥٦/ ب)، كنى الحاكم (١/ ١٢١/ ب) وقال: أبو الشعثاء عن أبى سهل عن عبد اللَّه بن بريدة الأسلمى، روى عن أبى عبد اللَّه عبد الملك بن أبى سليمان الفزارى عنه إن كان ذلك محفوظًا ثم ذكر إسناد حديثه من طريق صالح بن أبى الأسود عن عبد الملك بن أبى سليمان عن أبى الشعثاء عن عبد اللَّه بن بريدة عن أبيه فذكر حديثًا مسندًا، المقتنى في سرد الكنى (٦٩/ ب).\nفي الأصل \"وعن\" والمثبت عن مصادر الترجمة."}],[3791,"باب أبى شمر"],[3792,"٢٤٨٠ - أبو شمر (١) الضبعى. سمع عائذ بن عمرو المزنى (٢) وأبا عثمان النهدى. روى عنه شعبة."],[3793,"٢٤٨١ - أبو شِمْر عن ابن أبى ملكيه. روى عنه الصلت بن طريف (٣).","",{"fn":"شِمرْ، بكسر أوله، وسكون الميم. كما في التقريب (٢/ ٤٣٤).\nعائذ بن عمرو المزنى، أبو هبيرة البصرى، صحابى. شهد الحديبية مات في ولاية عبيد اللَّه بن زياد، سنة إحدى وستين. انظر التقريب (١/ ٣٩٠). ٢٤٨١ - كنى ابن منده (٥٦/ أ) وقال: أراه الأول. اهـ. قلت: والأول عنده هو أبو شمر الأدمرى، شامى عن كعب روى عنه شريح بن عبيد، كنى الحاكم (١/ ٢٢٧/ ب)، المقتنى في سرد الكنى (٧٠/ أ).\nصلت بن طريف، ذكره ابن أبى حاتم في الجرح (٢/ ١/ ٤٤٠) وذكر روايته عن أبى شمر ولم يذكر فيه شيئًا. اهـ."}],[3794,"باب الإفراد في الكنى من الشين"],[3795,"٢٤٨٢ - أبو الشِّمَال (١) بن ضِبَاب (٢). روى عن أبى أيوب الأنصارى عن النبى -صلى الله عليه وآله وسلم- أنه قال: \"أربع من سنن المرسلين، الحياء والسواك والتعطر والنكاح\" (٣). روى عنه مكحول.","",{"fn":"الشمال: بكسر أوله وتخفيف الميم، اللسان (٧/ ٤٦٨).\nضِبَاب: بكسر المعجمة، وبموحدتين، اللسان (٧/ ٤٦٨).\nالحديث أخرجه أبو أحمد الحاكم في الكنى (١/ ٢٢٩/ ب)، والمزى في تهذيب الكمال (٢/ ١٦١٤)، والترمذى \"النكاح\" باب ما جاء في فضل التزويج (٤/ ١٩٦)، وقال: حسن غريب من طريق حفص بن غياث عن الحجاج، عن مكحول، عن أبى الشمال، عن أبى أيوب مرفوعًا به، وروى الترمذى أيضًا في نفس الباب (٤/ ١٩٨) الحديث من طريق عباد بن العوام، عن الحجاج، عن مكحول، عن أبى الشمال، عن أبى أيوب مرفوعًا به نحو حديث حفص بن غياث، وقال الترمذى: روى هذا الحديث هشيم ومحمد ابن يزيد الواسطى، وأبو معاوية وغير واحد، عن الحجاج، عن مكحول، عن أبى أيوب قلت: ولم يذكروا فيه \"عن أبى الشمال\" قال: وحديث حفص بن غياث وعباد بن العوام أصح. اهـ. وأخرجه أحمد (٥/ ٤٢١) من طريق يزيد ومحمد بن يزيد كلاهما عن الحجاج عن مكحول، عن أبى أيوب به، ولم يذكر في سنده \"أبو الشمال\" والحديث ذكره السيوطى في الجامع الصغير (١/ ٣٧) وعزاه إلى أحمد ="}],[3796,"٢٤٨٣ - أبو شيخ، روى عن شريح قوله، روى عنه أبو يعفور العبدى."],[3797,"٢٤٨٤ - أبو شريح. روى عن أبى مسلم (١)، روى عنه محمد بن زيد."],[3798,"٢٤٨٥ - أبو شرقى (٢)، روى عن أبى عثمان النهدى، روى عنه شعبة."],[3799,"٢٤٨٦ - أبو شهدة، حديثه عند حكيم (٣) بن محمد بن طلحة عن طلحة (١) (عنه قوله) (٢).","",{"fn":"زاد في التهذيب \"مولى زيد بن صوحان\" وقد تقدم أبو مسلم العبدى مولى زيد بن صوحان في (١٨٠٣) وذكر ابن عبد البر في ترجمته هناك أنه روى عنه أبو شريح. ٢٤٨٥ - كنى مسلم (ص ٥١١)، الجرح (٤/ ٢/ ٣٩١)، الثقات (٧/ ٦٥٩)، المقتنى في سرد الكنى (٦٩/ أ)، كنى الحاكم (١/ ٢٢٩/ ب). الاكمال (٥/ ٥١)، وقال: أبو شرقى الضبى عن أبى عثمان النهدى روى عنه شعبة.\nشَرْقِىَّ بالقاف وتشديد الياء. كما في الاكمال (٥/ ٥١). ٢٤٨٦ - الجرح (٤/ ٢/ ٣٩١)، كنى ابن منده (٥٨/ ب)، كنى الحاكم (١/ ٢٣٠/ أ)، المقتنى في سرد الكنى (٧٠/ أ) وقال: أبو شهدة حكى عنه طلحة.\nهكذا في الأصل \"حكيم\" وكذا في الجرح. والذى في كنى الحاكم كنى ابن منده \"الحكم\" وذكر ابن أبى حاتم في الجرح (١/ ٢/ ١٢٧) الحكم ابن محمد أبو مضر مصرى. روى عن الحسن بن غالب وعقبة بن سنان وأبى الهيثم الضمرى، والقاسم بن عبد الرحمن، وطلحة، روى عنه سعيد بن أبى أيوب، ولم يذكر فيه شيئًا. فاللَّه أعلم."}],[3800,"٢٤٨٧ - أبو شهاب، روى عن زيد بن اسلم، روى عنه يحيى بن سعيد العطار.","",{"fn":"طلحة، ذكر ابن أبى حاتم في الجرح (٢/ ١/ ٤٨١) طلحة بن سمرة روى عن. . روى عنه الحكم بن محمد وقال ابن أبى حاتم: سمعت أبى يقول: هما مجهولان -يعنى طلحة والحكم- أهـ. وقال الذهبى في الميزان (٢/ ٣٤٤) طلحة عن أبى شهدة، شيخ للحكم ابن محمد مجهولان. اهـ.\nغير واضح في الأصل، وهو في مصادر الترجمة كما أثبته. ٢٤٨٧ - الجرح (٤/ ٢/ ٣٩١ - ٣٩٢) وقال: سألت أبى عنه فقال: هو مجهول، الميزان (٤/ ٥٣٦) وقال: مجهول، اللسان (٧/ ٦٣) وقال: أيضا مجهول."}],[3801,"حرف الهاء"],[3802,"باب أبى الهيثم"],[3803,"٢٤٨٨ - أبو الهيثم بن نصر بن دهر الاسلمى. روى عنه أبيه (١) مدنى روى عنه محمد بن إبراهيم بن الحارث التيمى."],[3804,"٢٤٨٩ - أبو الهيثم الضمرى (٢). روى عن سعيد بن أبى عمرة (٣). روى عنه الحكم بن محمد."],[3805,"٢٤٩٠ - أبو الهيثم، روى عن الحسن بن أبى الحسن، روى عنه أبو معاوية محمد بن خازم الضرير.","",{"fn":"نصر بن دهر بن الاخرم، الاسلمى، صحابى، نزل المدينة، تفرد ابنه أبو الهيثم بالرواية عنه. التقريب (٢/ ٢٩٩) وانظر التجريد (٢/ ١٠٥). ٢٤٨٩ - كنى البخارى (ص ٧٩)، الجرح (٤/ ٢/ ٤٥٣) وقال: سمعت أبى يقول: هو مجهول، الميزان (٤/ ٥٨٤) وقال: لا يعرف، اللسان (٧/ ١١٩) وقال: لا يعرف، المقتنى في سرد الكنى (١٤٣/ ب).\nفي الميزان \"البصرى\".\nسعيد بن أبى عمرة الأنصارى، ذكره ابن أبى حاتم في الجرح (٢/ ١/ ٥٣) وقال: روى الحكم بن محمد عن أبى الهيثم عنه. . سمعت أبى يقول: هم مجهولون. ٢٤٩٠ - كنى البخارى (ص ٧٩)، الثقات (٧/ ٦٦٧). المقتنى في سرد الكنى (١٤٣/ ب)."}],[3806,"٢٤٩١ - أبو الهيثم شامى، روى عن ابن شهاب، روى عنه بقية بن الوليد الكلاعى حديثا لم يتابع عليه."],[3807,"٢٤٩٢ - أبو الهيثم (١) صاحب القصب كوفى، روى عن سعيد بن المسيب وسعيد بن جبير، وإبراهيم النخعى، روى عنه سفيان الثورى، واسرائيل بن يونس، وعلى بن صالح بن حى، قيل: ان اسمه عمار. وقيل: ان عمارا إنما هو اسم أبى الهيثم العطار كذاك قال البخارى (٢).","",{"fn":"زاد ابن معين في التاريخ، وابن حبان في الثقات وابن حجر في التهذيب \"المرادى\".\nسبقت الاشارة قبل قليل عند ذكر مصادر الترجمة إلى كلام البخارى، ولم يذكر البخارى في الكنى المجردة اسمه وإنما قال: أبو الهيثم العطار، ويقال: الهيثم. فاللَّه أعلم."}],[3808,"باب أبى هلال"],[3809,"٢٤٩٣ - أبو هلال العتكى. روى عن على رضي الله عنه. روى عنه أبو بردة ابن أبى موسى الاشعرى. قال على بن المدينى: \"كان أبو هلال العتكى يقدم عثمان وينال من على وكان رجل سوء متهما في دينه\" (١)."],[3810,"٢٤٩٤ - أبو هلال الليثى، روى عن أبى هريرة، روى عنه عمر مولى غُفْرة (٢).","",{"fn":"لم أقف عليه من كلام على بن المدينى. ٢٤٩٤ - كنى البخارى (ص ٨٠). الجرح (٤/ ٢/ ٤٥٥)، المقتنى في سرد الكنى (١٤٢/ ب).\nعمر مولى غُفْرة: بضم المعجمة وسكون الفاء، هو عمر بن عبد اللَّه المدنى، مولى غفرة. ضعيف، وكان، كثير الإرسال من الخامسة، (ت: ١٤٥) أو (١٤٦). التقريب (٢/ ٥٩)."}],[3811,"باب أبى هارون"],[3812,"٢٤٩٥ - أبو هارون (١) الواسطى. روى عن شريح في الدية أخماسا (٢) روى عنه شريك القاضى.","",{"fn":"زاد في كنى البخارى (بن كعب).\nأخرجه البخارى في الكنى من طريق شريك عن أبى هارون الواسطى قال: وقعت ثنية ابن لعمر بن سعد فقضى شريح بخمس من الإبل وجعله أخماسا\". وأخرجه أيضا ابن أبى حاتم في الجرح من هذا الطريق به وفيه عنده وقعت ثنيتى ابن يعمر بن سعد فقضى شريح بخمس من الإبل وجعله أخماسا. وأخرج أبو داود \"الديات\" باب ديات الاعضاء (٤/ ١٨٩) والنسائى \"القسامة\" باب عقل الاسنان (٨/ ٥٥)، البيهقى \"الديات\" باب دية الاسنان (٨/ ٨٩) وابن أبى شيبة (٩/ ١٨٦) وعبد الرزاق (٩/ ٣٤٦) كلهم أخرجوه من حديث عمرو بن شعيب عن أبيه عن جده. قال: قال رسول اللَّه -صلى الله عليه وآله وسلم- \"في الاسنان خمس من الإبل\" وقال الألبانى في إرواء الغيل (٧/ ٣٢٠) هذا اسناد حسن. وأخرج ابن ماجه أيضا \"الديات\" باب دية الاسنان (٢/ ٨٨٥) حديث ابن عباس يرفعه \"أنه قضى في السن خمسا من الإبل\" وقال السندى \"في الزوائد: إسناده صحيح. وفى مسند أحمد (١/ ٣٨٤) من حديث ابن مسعود يرفعه \"ان رسول اللَّه -صلى الله عليه وآله وسلم- جعل الدية في الخطأ أخماسا\". وأخرج ابن أبى شيبة (٩/ ١٨٨)، وعبد الرزاق (٩/ ٣٤٦) عن سليمان بن موسى قال: في كتاب عمر بن عبد العزيز إلى أمراء الاجناد وفى السن خمس من الإبل."}],[3813,"٢٤٩٦ - أبو هارون الحجام مولى حماد بن عمران التيمى (١). قال: حجمت أبا بكر بن محمد بن عمرو بن حزم يوم السبت (٢) و(. . .) (٣) موضع محاجمة روى عنه معن بن عيسى."],[3814,"٢٤٩٧ - أبو هارون الفلسطينى. روى عن عثمان بن عطاء (٤)، روى عنه سعيد بن كثير بن دينار (٥).","",{"fn":"حماد بن عمران التيمى. ذكره ابن أبى حاتم في الجرح (١/ ٢/ ١٤٥) ولم يذكر فيه شيئا.\nأخرجه البخارى في الكنى وابن أبى حاتم في الجرح وفيه \"حجمت أبا بكر ابن محمد بن عمرو بن حزم يوم السبت\".\nكلمة غير واضحة في الأصل. ٢٤٩٧ - الجرح (٤/ ٢/ ٤٥٤) وقال: سألت أبى عنه فقال: مجهول.\nعثمان بن عطاء بن أبى مسلم الخراسانى أبو مسعود المقدسى، ضعيفين السابعة (ت: ١٥٥) وقيل (١٥١). التقريب (٢/ ١٢).\nعثمان بن سعيد بن كثير بن دينار، القرشى، مولاهم أبو عمرو الحمصى ثقة عابد، من التاسعة (ت: / ٢٠٩). التقريب (٢/ ٩)."}],[3815,"باب أبى هند"],[3816,"٢٤٩٨ - أبو هند البجلى شامى. روى عن معاوية بن أبى سفيان روى عنه عبد الرحمن بن أبى عوف (١)."],[3817,"٢٤٩٩ - أبو هند الدالانى ويقال له الهمدانى (٢). روى عن أبى (ظبيان روى عنه محمد بن قيس) (٣)، (٤).","",{"fn":"في كنى مسلم، واللسان زيادة \"الجرشى\". وعبد الرحمن بن أبى عوف الجرشى. بضم الجيم وفتح الراء بعدها معجمة، الحمصى القاضى، ثقة، من الثانية، يقال: أدرك النبى -صلى الله عليه وآله وسلم-. التقريب (١/ ٤٩٤). ٢٤٩٩ - كنى البخارى (ص ٨٠)، الجرح (٤/ ٢/ ٤٥٣)، الثقات (٧/ ٦٦٦) تهذيب الكمال (٣/ ١٦٥٧)، التهذيب (١٢/ ٢٦٨)، التقريب (٢/ ٤٨٤) وقال: مقبول، من السابعة./ بخ. عس، تعجيل المنفعة (ص ٣٤٤).\nفي تهذيب الكمال، والتهذيب، وتعجيل المنفعة، والتقريب زيادة \"اسمه الحارث بن عبد الرحمن\" وقد فرق ابن أبى حاتم في الجرح وابن حبان في الثقات بين أبى هند الحارث بن عبد الرحمن روى عن أبى الجلاس، وبين أبى هند الدلانى، الهمدانى صاحب هذه الترجمة.\nزاد في تهذيب الكمال، والثقات \"الاسدى\" وفى التقريب (٢/ ٢٠٢) محمد ابن قيس الاسدى الوالبى، بالموحدة، الكوفى، ثقة، من كبار السابعة. اهـ.\nغير واضح في الأصل والمثبت عن كنى البخارى، والجرح، والثقات، وتهذيب الكمال."}],[3818,"٢٥٠٠ - أبو هند المرهبى. روى عن الضحاك. روى عنه شريك (١).","",{"fn":"في كنى البخارى زيادة لفظ \"مرسل\"."}],[3819,"باب أبى الهندى"],[3820,"٢٥٠١ - أبو الهندى. روى عن أنس بن مالك. روى عنه أبو عاصم النبيل الضحاك بن مخلد."],[3821,"٢٥٠٢ - أبو الهندى سمع أبا طالوت (١). روى عنه معتمر بن سليمان التيمى.","",{"fn":"تقدم في (١٦٩١) ذكر ابن عبد البر في ترجمته هناك أنه روى عنه أبو الهندى."}],[3822,"باب أبى هشام"],[3823,"٢٥٠٣ - أبو هشام. روى عن أبى سعيد الخدرى. روى عنه عمرو بن دينار."],[3824,"٢٥٠٤ - أبو هشام. روى عن أبى معاذ. روى عنه سهل (١) العسكرى. قال أبو حاتم: أبو هشام وأبو معاذ مجهولان.","",{"fn":"زاد في الميزان \"بن عثمان\"."}],[3825,"باب أبى همام"],[3826,"٢٥٠٥ - أبو همام الشعبانى. روى عن أبى هريرة. روى عنه يحيى بن أبى كثير."],[3827,"٢٥٠٦ - أبو همام البصرى. روى عنه الأوزاعى قوله. لم يعرفه أبو زرعة."],[3828,"باب الافراد في الهاء من الكنى"],[3829,"٢٥٠٧ - أبو هاشم الدوسى، ابن عم أبى هريرة. روى عن أبى هريرة. حديثه عند النضر بن محمد الجرشى (١) عن عكرمة بن عمار عن رجل (٢) من آل حاطب بن أبى بلتعة (٣) عنه."],[3830,"٢٥٠٨ - أبو هُرْمُز (٤) روى عن أنس. روى عنه سعيد بن سليمان الواسطى وأحمد بن يونس (٥). قال عباس عن يحيى بن معين أنه قال: أبو هرمز الذى يروى عن أنس ضعيف (٦).","",{"fn":"في كنى البخارى \"النضر بن شميل\".\nلم أقف على من سماه.\nحاطب بن أبى بلتعة عمرو بن عمير بن سلمة اللخمى، حليف بنى أسد بن عبد العزيز صحابى، شهد بدرا وكان رسول النبى -صلى الله عليه وآله وسلم- إلى المقوقس (ت: ٣٠) انظر التجريد (١/ ١١٣ - ١١٤). ٢٥٠٨ - الجرح (٤/ ٢/ ٤٥٦) وقال: قرئ على العباس بن محمد الدورى عن يحيى ابن معين أنه قال: أبو هرمز الذى يروى عن أنس ضعيف، الميزان (٤/ ٥٨٢) وقال: أبو هرمز. عن أنس. هو نافع، لينه ابن معين. الضعفاء والمتروكين (ص ١١٤) وقال: ليس بثقة. اللسان (٦/ ١٤٦) وقال: نافع بن هرمز أبو هرمز، وذكر روايته عن الحسن وعن أنس بن مالك: ورواية أحمد بن يونس عنه، الاكمال (٧/ ٤١٠).\nهرمز: بضم الهاء واخره زاى. الاكمال (٧/ ٤٠٩).\nأحمد بن يونس بن المسيب الضبى البغدادى، نزيل أصبهان، صدوق، انظر الجرح (١/ ١/ ٨١).\nتاريخ ابن معين (٢/ ٦٢)."}],[3831,"٢٥٠٩ - أبو هبيرة (١) الضبى. روى عن (. . .) (٢) روى عنه حنش بن الحارث (٣)."],[3832,"٢٥١٠ - أبو الهَدَّاج (٤) التُّجَيْبِى (٥). سمع سعيد بن المسيب قوله. روى عنه حرملة بن عمران."],[3833,"٢٥١١ - أبو هنيدة. روى عن أبى أمامة الباهلى (٦). روى عنه داود بن أبى هند.","",{"fn":"هبيرة: بضم هاء وفتح موحدة تبصيرة المنتبة (٤/ ١٤٤٩).\nهكذا بياض في الأصل، وكذا في الجرح أيضا.\nحنش: بفتح أوله والنون الخفيفة بعدها معجمة، ابن الحارث بن لقيط النخعى، الكوفى لا بأس به، من السادسة، انظر التقريب (١/ ٢٠٥) وذكره ابن أبى حاتم في الجرح (١/ ٢/ ٢٩١) وذكر روايته عن أبى هبيرة الأنصارى وقال: سمعت أبى يقول: حنش بن الحارث صالح الحديث ما به بأس وانظر أيضا التهذيب (٣/ ٥٧). ٢٥١٠ - كنى البخارى (ص ٨١)، الجرح (٤/ ٢/ ٤٥٥)، الثقات (٧/ ٦٦٧)، الاكمال (٧/ ٤١٦)، المقتنى (١٤١/ أ).\nالهدَّاج: هكذا ضبط في الأصل بتشديد الدال المهملة، وضبط أيضا في الاكمال (٧/ ٤١٦) بفتح الهاء وتشديد الدال المهملة.\nالتجيبى: هنا نسبة إلى محلة تجيب بمصر، وهى بضم التاء المعجمة باثنتين من فوقها كسر الجيم وتسكين الياء وفى آخرها باء موحدة. انظر اللباب (١/ ٢٠٧)، الاكمال (٧/ ٤١٦). ٢٥١١ - كنى البخارى (ص ٨١)، الجرح (٤/ ٢/ ٤٥٥)، الثقات (٧/ ٦٦٨) الميزان (٤/ ٥٨٣) وقال: لا يعرف. اللسان (٧/ ١١٩) وقال: لا يعرف.\nهكذا في الأصل \"أبو امامة الباهلى\" والذى في الميزان \"معاوية\" وفى بقية المراجع \"أبى ماوية\"."}],[3834,"٢٥١٢ - أبو هَمْدَان (١) بن هارون. قال عباس عن ابن معين: أبو همدان كذاب (٢).","",{"fn":"همدان: بمفتوحة وسكون ميم وبدال مهملة ونون. المغنى (ص ٨٤).\nالتاريخ (٢/ ٧٣٠) وزاد \"قال أبو الفضل أبو همدان من أهل هيت\"."}],[3835,"حرف الواو"],[3836,"باب أبى الوليد"],[3837,"٢٥١٣ - أبو الوليد مولى عمرو بن خداش (١). سمع أبا هريرة. روى عنه ابن أبى ذئب. قال ابن أبى حاتم: سمعت أبى وسئل عن أبى الوليد الذى روى عنه ابن أبى ذئب. فقال: شيخ لابن أبى ذئب. لا أعلم روى عنه غيره، وهو شيخ مستقيم الحديث.","",{"fn":"هكذا في الأصل \"خداش\" بالدال المهملة. وكذا هو في كنى مسلم \"خداش\" والذى في كنى البخارى والجرح \"خراش\" بالراء المهملة."}],[3838,"الخاتمة"],[3839,"الحمد للَّه رب العالمين، والصلاة والسلام على أشرف الأنبياء والمرسلين وعلى آله وأصحابه الطبين الطاهرين وبعد،"],[3840,"فاننى سأذكر في هذه الخاتمة أهم النتائج التى توصلت إليها من خلال عملى في هذا الكتاب، وتتلخص هذه النتائج بما يلى:"],[3841,"أولا: أهمية كتب التراث الإسلامى وذلك بما تضمنه هذا التراث من علوم غزيرة نافعة كانت ثمرة لجهود عظيمة مشكورة لسلفنا الصالح رحمهم اللَّه تعالى."],[3842,"ثانيا: كان للدراسة التى قدمتها بين يدى هذا الكتاب وما استهدفته هذه الدراسة من إبراز لبعض الجوانب المتعلقة بالكتاب ومصنفه بعض النتائج المثمرة منها."],[3843,"(أ) التعرف على شخصية الحافظ ابن عبد البر مصنف هذا الكتاب وإبراز الجوانب المختلفة في شخصيته، وما قدمه للمكتبة الإسلامية من مؤلفات جليلة متنوعة الفنون."],[3844,"(ب) إبراز أهمية هذا العلم \"علم الكنى والأسماء\" والغاية التى يخدمها مع ذكر بعض الذين شاركوا في التأليف فيه عبر هذه القرون الطويلة، مع ذكر مؤلفاتهم ومعرفة المخطوط منها من المطبوع، وقد تم ذكر ستة وخمسين مؤلفا في هذا المجال (١)."],[3845,"(جـ) لقد كان لوضع منهج التحقيق والالتزام به أثناء العمل نتائج طيبة منها خروج العمل متناسقا ومنضبطا بخطوات محددة واضحة الأهداف."],[3846,"(د) وقد كان لترقيم التراجم \"الكنى\" ترقيما تسلسليا فوائد كبيرة منها:"],[3847,"١ - معرفة عدد الكنى الواردة في الكتاب، وقد بلغ عددها حوالى الفين وخمسمائة وثلاث عشرة (٢٥١٣) كنية، وقفت على أكثرها في المصادر الأخرى وبقى منها حوالى ثلاثين (٣٠) كنية لم أقف عليها عند مخير الحافظ ابن عبد البر."],[3848,"٢ - عمل الفهارس المتنوعة على هذه الأرقام، وبهذا تكون الإحالة على الأرقام أكثر دقة من الإحالة على أرقام الصفحات، وذلك لأن الصفحة الواحدة قد تشتمل على عدد من الكنى."],[3849,"٣ - ساعد الترقيم على ترتيب مادة الكتاب على حروف المعجم كما هو ملاحظ من الفهرس الثالث (فهرس الكنى)، وقد أغنى هذا الفهرس عن عمل فهرس للكتاب على الأبواب."],[3850,"ثالثا: أهمية هذا الكتاب، وتبرز أهمية هذا الكتاب بما يلى: -"],[3851,"(أ) اشتماله على عدد كبير من الأسماء والكنى بالإضافة إلى اشماله على آلاف التراجم الهامشية كما هو ملاحظ من الفهرسين الثالث والرابع.","",{"fn":"انظر الدراسة (ص ٩) وما بعدها."}],[3852,"(ب) لم يقتصر فيه مصنفه على الأسماء والكنى فحسب بل ضمنه كثيرا من الأقوال في الجرح والعدالة سواء أكانت هذه الأقوال للحافظ ابن عبد البر نفسه أو لأئمة الجرح والتعديل المتقدمين على عصرة."],[3853,"فمثلا اشتمل على حوالى مائة وعشرين (١٢٠) قولا للامام أحمد، ومائة وثمانين قولا (١٨٠) لأبى حاتم الرازى، ومائة قولا لأبى زرعة، ومائتين وخمسين قولا (٢٥٠) لابن معين. وهكذا."],[3854,"(ب) اشتماله على مجموعة كبيرة من الأحاديث والاثار التى ذكرها المصنف اثناء ايراده للكنى."],[3855,"رابعا: وأخيرا أود التنبيه على أنه ينبغى عدم الاعتماد كثيرا في تحقيق التراث ونشره على المصورات، وخاصة في الكتب التى لا يوجد منها أكثر من نسخة، والاولى في مثل هذا الرجوع إلى النسخة الأصلية للكتاب ان وجدت، وذلك لأنه قد يسقط أحيانا بعض الأوراق من الكتاب أثناء عملية التصوير وقد يكون التصوير غير واضح فيتعذر معه قراءة بعض الكلمات، وهذا ما كنت أعانى منه كثيرا وخاصة قبل الوقوف على المخطوط الأصلى للكتاب."],[3856,"هذا ما أردت أن أذكره في هذه الخاتمة، وأسأل اللَّه عز وجل أن يختم بالصالحات أعمالنا، وأن يوفقنا لمرضاته، وهو حسبنا ونعم الوكيل."],[3857,"المراجع"],[3858,"- الاتحافات السنية بالأحاديث القدسية: - عبد الرؤوف المناوى (ت: ١٠٣١) دار المعرفة - بيروت."],[3859,"- أخبار القضاة: - وكيع/ محمد بن خلف بن حيان (ت: ٣٠٦)، عالم الكتب بيروت."],[3860,"- أخبار مكة: محمد بن عبد اللَّه بن أحمد الازرقى تحقيق رشدى صالح ملحس دار الثقافة - مكة المكرمة، ط ٢ - ١٣٩٨ هـ."],[3861,"- الأدب المفرد: - محمد بن إسماعيل البخارى (ت: ٢٥٦)، تحقيق: فؤاد عبد الباقى، المطبعة العربية، باكستان."],[3862,"- الأذكار: - يحيى بن شرف النووى (ت: ٦٧٦)، مكتبة الرياض الحديثة - الرياض."],[3863,"- إرواء الغليل في تخريج أحاديث منار السبيل: - محمد ناصر الدين الألبانى، المكتب الاسلامى، ط ٢، ١٣٩٩ هـ."],[3864,"- الأزهار المتناثرة في الأخبار المتواترة: - جلال الدين السيوطى (ت: ٩١١)، مطبعة صاحب دكن - ١٣٢٤ هـ."],[3865,"- الاستبصار في نسب الصحابة من الأنصار: - عبد اللَّه بن قدامة المقدسى (ت: ٦٢٠)، تحقيق الاستاذ على نويهض - دار الفكر."],[3866,"- الاستذكار لمذاهب فقهاء الأمصار وعلماء الأقطار فيما تضمنه الموطأ من معانى الرأى والآثار: - أبو عمر يوسف بن عبد اللَّه بن عبد البر (ت: ٤٦٣)، تحقيق الاستاذ/ على النجدى ناصف."],[3867,"- الاستيعاب في معرفة الأصحاب: - يوسف بن عبد اللَّه بن محمد بن عبد البر النمرى (ت: ٤٦٣)، مطبعة السعادة - مصر، ط ١ - ١٣٢٨ هـ."],[3868,"- أسد الغابة في معرفة الصحابة: - أبو الحسن على بن محمد بن الاثير الجزرى (ت: ٦٣٠)، مطبعة الشعب."],[3869,"- الأسماء والصفات: أبو بكر أحمد بن الحسين بن على البيهقى (ت: ٤٥٨)، دار احياء التراث العربى - بيروت."],[3870,"- الإصابة في تمييز الصحابة: - أحمد بن على بن حجر العسقلانى (ت: ٨٥٢)، مطبعة السعادة - مصر، ط ١ - ١٣٢٨ هـ."],[3871,"- الاعتبار في الناسخ والمنسوخ من الآثار: - محمد بن موسى بن عثمان الحازمى (ت: ٥٨٤)، مطبعة الاندلس - حمص، ط ١ - ١٣٨٦ هـ - ١٩٦٦ م."],[3872,"- الاعتقاد: - أبو بكر أحمد بن الحسين البيهقى (ت: ٤٥٨)، تصحيح العلامة أحمد محمد مرسى، المطبعة العربية - باكستان."],[3873,"- اعجاز القرآن: - أبو بكر محمد بن الطيب الباقلانى (ت: ٤٠٣)، تحقيق السيد أحمد صقر، دار المعارف - مصر."],[3874,"- اعجاز القرآن والبلاغة النبوية: - مصطفى صادق الرافعى، دار الكتاب العربى بيروت."],[3875,"- الاعلام: - خير الدين الزركلى - دار العلم للملايين - بيروت، ط ٥."],[3876,"- اعلام النبوة: - على بن محمد الماوردى الشافعى (ت: ٤٥٠) دار الكتب العلمية - بيروت، ط ٢ - ١٤٠١ هـ."],[3877,"- اقتضاء الصراط المستقيم مخالفة أصحاب الجحيم: شيخ الاسلام أحمد ابن تيمية (٦٦١ - ٧٢٨)، تحقيق أحمد حامد الفقى، ط ٢ - ١٣٦٩ هـ، مطبعة السنة المحمدية."],[3878,"- الاكمال في رفع الارتياب عن المؤتلف والمختلف في الأسماء والكنى والانساب: - الامير الحافظ ابن ماكولا (ت: ٤٧٥)، نشر/ محمد أمين دمج، بيروت - لبنان."],[3879,"- الأموال: حميد بن مخلد المعروف بابن زنجويه (ت ٢٤٧)، رسالة دكتوراه بجامعة أم القرى بمكة المكرمة، تحقيق الدكتور شاكر ذيب فياض."],[3880,"- الأموال: - أبو عبيد القاسم بن سلام (ت ٢٢٤)، تحقيق محمد خليل هراس، دار الفكر، ط ٢، ١٣٩٥ - ١٩٧٥."],[3881,"- الأنساب: - عبد الكريم بن محمد السمعانى (ت ٥٦٢)، نشر المستشرق: د. سى - مرجليون."],[3882,"- الانساب المتفقه: - أبو الفضل محمد طاهر المعروف بابن القيسرانى (٥٠٧)."],[3883,"- الباعث الحثيث شرح اختصار علوم الحديث: - أحمد محمد شاكر، مكتبة على صبيح وأولاده - مصر، ط ٣ - سنة ١٣٩٧ هـ."],[3884,"- بحوث في تاريخ السنة: - د. أكرم العمرى، مؤسسة الرسالة، ط ٣ - ١٣٩٥ هـ."],[3885,"- البداية والنهاية: - أبو الفداء إسماعيل بن كثير (ت: ٧٧٤)، مكتبة المعارف، بيروت، ط ٢ - ١٩٧٧."],[3886,"- برنامج ابن جابر الوادى آشى: شمس الدين محمد بن جابر الوادى آشى (ت: ٧٤٩)، تحقيق د. محمد الحبيب الهيله، تونس ١٤٠١ هـ."],[3887,"- بغية الملتمس تاريخ رجال أهل الاندلس: - أحمد بن يحيى الضبى (ت: ٥٩٩)، دار الكتاب العربى، سنة ١٩٦٧ م."],[3888,"- بغية الوعاة في طبقات اللغويين والنحاة: - جلال الدين عبد الرحمن السيوطى (ت: ٩١١)، تحقيق: محمد أبو الفضل إبراهيم، دار الفكر، ط ٢ - ١٣٩٩ هـ."],[3889,"- بيان خطأ محمد بن إسماعيل البخارى في تاريخه. رواية ابن أبى حاتم وأبى زرعة، المكتبة الإسلامية - تركيا."],[3890,"- البيان والتبيين: - أبو عثمان عمرو بن بحر الجاحظ (ت: ٢٥٥)، تحقيق عبد السلام هارون، ط/ ٣."],[3891,"- تاج العروس من جواهر القاموس: - محمد مرتضى الزبيدى، مكتبة الحياة - بيروت."],[3892,"- التاريخ: - يحيى بن معين (ت: ٢٣٣)، رواية الدورى، تحقيق: د. أحمد محمد نور سيف، نشر مركز البحث العلمى بجامعة أم القرى، ط ١ - ١٣٩٩ هـ - ١٩٧٩ م."],[3893,"- التاريخ: يحيى بن معين رواية عثمان بن سعيد الدرامى (ت: ٢٨٠) تحقيق: د/ أحمد نور سيف، نشر مركز البحث العلمى - بجامعة أم القرى."],[3894,"- التاريخ: - يحيى بن معين، رواية يزيد بن الهيثم بن طهمان البادى الدقاق، تحقيق: د/ أحمد محمد نور سيف، نشر: مركز البحث العلمى - بجامعة أم القرى."],[3895,"- تاريخ ابن كثير - انظر البداية والنهاية."],[3896,"- تاريخ الامم والملوك: محمد بن جرير الطبرى (ت: ٣١٠)، تحقيق: محمد أبو الفضل ط ٤. دار المعارف - مصر."],[3897,"- تاريخ بغداد: - أبو بكر أحمد بن على بن ثابت المعروف بالخطيب البغدادى (ت ٤٦٣)، المكتبة السلفية - المدينة المنورة."],[3898,"- تاريخ جرجان: - حمزة بن يوسف السهمى (ت ٤٢٧)، دائرة المعارف العثمانية الهند، ط ٢ - ١٣٨٧ - ١٩٦٧."],[3899,"- تاريخ التراث العربى: فؤاد سزكين، الهيئة المصرية - القاهرة، سنة ١٩٧١ م."],[3900,"- تاريخ الخلفاء: - عبد الرحمن بن أبى بكر السيوطى (ت ٩١١)، تحقيق محمد محيى الدين عبد الحميد، مطبعة السعادة - مصر، ط ١، سنة ١٣٧١ - ١٩٥٢."],[3901,"- تاريخ خليفة بن خياط: - خليفة بن خياط (شباب) (ت: ٢٣٠)، تحقيق: أكرم العمرى، مطبعة محمد هاشم الكتبى، ط ٢ - سنة ١٣٩٧ هـ."],[3902,"- تاريخ دمشق: - أبو القاسم على بن عساكر (ت ٥٧١)، مصور بالمكتبة المركزية بجامعة أم القرى."],[3903,"- التاريخ الصغير: - محمد بن إسماعيل البخارى (ت ٢٥٦)، المكتبة الاثرية - باكستان."],[3904,"- التاريخ الكبير: محمد بن إسماعيل البخارى (ت ٢٥٦)، المكتبة الاسلامية - تركيا."],[3905,"- تبصير المنتبه بتحرير المشتبه، أحمد بن على بن حجر العسقلانى (ت: ٨٥٢) تحقيق: محمد على النجار. وعلى محمد البجاوى، المؤسسة المصرية العامة للطباعة والنشر."],[3906,"- تبيين كذب المفترى فيما نسب إلى الإمام أبى الحسن الاشعرى: - على ابن الحسن بن هبة اللَّه بن عساكر (ت: ٥٧١)، دار الكتاب العربى - بيروت، ١٣٩٩ هـ."],[3907,"- تجريد أسماء الصحابة: - محمد بن أحمد الذهبى (ت: ٧٤٨)، دار المعرفة، بيروت."],[3908,"- تحفة الاحوذى شرح جامع الترمذى: - محمد بن عبد الرحمن المباركفورى (ت: ١٣٥٣)، نشر المكتبة السلفية بالمدينة المنورة، ط ٢ - سنة ١٣٨٣ هـ."],[3909,"- تحفة الاشراف بمعرفة الاطراف: - أبو الحجاج يوسف بن عبد الرحمن المزى (ت: ٧٤٢)، المطبعة القيمة - الهند ١٣٩٦ - ١٩٧٦."],[3910,"- تدريب الراوى في شرح تقريب النواوى: - جلال الدين السيوطى - تحقيق عبد الوهاب عبد اللطيف."],[3911,"- تذكرة الحفاظ: محمد بن أحمد بن عثمان الذهبى (ت: ٧٤٨)، دار احياء التراث العربى، ط ٢ - ١٣٨٥ هـ."],[3912,"- ترتيب المدارك: تقريب المسالك لمعرفة اعلام مذهب مالك: - القاضى عياض بن موسى السبتى (ت: ٥٤٤)، مطبوعات وزارة الاوقاف الرباط."],[3913,"- الترغيب والترهيب: - عبد العظيم بن عبد القوى المنذرى (ت ٦٥٦)، تحقيق محمد محيى الدين عبد الحميد، دار الفكر بيروت، ط ٢ - ١٣٩٣ هـ."],[3914,"- تصحيفات المحدثين: - أبو أحمد الحسن بن عبد اللَّه بن سعيد العسكرى (ت: ٣٨٢)، تحقيق: محمود أحمد ميره، المطبعة العربية الحديثة - القاهرة. ط ١."],[3915,"- تعجيل المنفعة: - أحمد بن على بن حجر العسقلانى (ت ٨٥٢)، دار المحاسن (١٣٨٦ - ١٩٦٦)."],[3916,"- التعليق المغنى على سنن الدارقطنى: - محمد شمس الحق آبادى، دار المحاسن القاهرة، ١٣٨٦ - ١٩٦٦."],[3917,"- تفسير القرآن العظيم: - إسماعيل بن كثير (ت ٧٧٤)، دار إحياء الكتب العربية - مصر."],[3918,"- تفسير أبى السعود: - أبو السعود بن محمد العمادى (ت: ٩٨٢)، تحقيق: عبد القادر أحمد عطا - مطبعة السعادة."],[3919,"- تقريب التهذيب: - أحمد بن على بن حجر العسقلانى (ت: ٨٥٢)، تحقيق: عبد الوهاب عبد اللطيف، دار المعرفة - بيروت، ط ٢ - ١٣٩٥ هـ."],[3920,"- التقييد والايضاح شرح مقدمة ابن الصلاح: - زين الدين عبد الرحيم بن الحسين العراقى (ت ٨٠٦)، تحقيق: عبد الرحمن محمد عثمان، المكتبة السلفية - المدينة المنورة، ط ١ - ١٣٨٩ - ١٩٦٩."],[3921,"- تلخيص الحبير تخريج أحاديث الرافعى الكبير: - ابن حجر، تحقيق عبد اللَّه هاشم اليمانى، شركة الطباعة الفنية المتحدة، القاهرة، ١٣٨٤ هـ."],[3922,"- تلخيص المستدرك بهامش مستدرك الحاكم: - محمد بن أحمد الذهبى (ت ٧٤٨) دار الفكر - بيروت ١٣٩٨ - ١٩٧٨."],[3923,"- التمهيد لما في الموطأ من المعانى والاسانيد: - أبو عمر يوسف بن عبد اللَّه بن عبد البر النمرى (ت ٤٦٣)، تحقيق سعيد أحمد اعراب، نشر وزارة الأوقاف بالمغرب."],[3924,"- تنزيه الشريعة المرفوعة عن الاخبار الشنيعة الموضوعة: - على بن محمد ابن عراقى (ت ٩٦٣)، دار الكتب العلمية - بيروت، ط ١ - ١٣٩٩ - ١٩٧٩."],[3925,"- تهذيب الاثار: - محمد بن جرير الطبرى (ت ٣١٠)، تحقيق د. ناصر الرشيد وعبد القيوم عبد رب النبى، مطابع الصفا - مكة المكرمة، ١٤٠٢ هـ."],[3926,"- تهذيب الأسماء واللغات: - محيى الدين بن شرف النووى، دار الكتب العلمية - بيروت."],[3927,"- تهذيب تاريخ دمشق: عبد القادر بدران (ت ١٣٤٦ هـ)، دار المسيرة - بيروت."],[3928,"- تهذيب التهذيب: - أحمد بن على بن حجر العسقلانى (ت ٨٥٢ هـ)، دائرة المعارف - الهند، ط ١ - ١٣٢٥ هـ."],[3929,"- تهذيب سنن أبى داود: - أبو عبد اللَّه محمد بن أبى بكر الشهير بابن القيم (ت ٧٥٢)، تحقيق: محمد حامد الفقى، مكتبة السنة المحمدية - القاهرة."],[3930,"- تهذيب الكمال: أبو الحجاج يوسف بن عبد الرحمن المزى (ت ٧٤٢ هـ)، مصورة دار المأمون للتراث، دمشق."],[3931,"- التوحيد وإثبات صفات الرب عز وجل: - محمد بن اسحاق بن خزيمة (ت: ٣١١) راجعه وعلق عليه خليل الهراس، توزيع دار الباز - مكة المكرمة، سنة ١٣٩٨ هـ - ١٩٧٨ م."],[3932,"- الثقات: - أبو حاتم محمد بن حبان البستى (ت ٣٥٤)، دائرة المعارف العثمانية - الهند، ط ١ - ١٣٩٣ هـ."],[3933,"- الجامع الأزهر في حديث النبى الانور: - المناوى، المركز العربى للبحث والنشر، القاهرة - ١٩٨٠ م."],[3934,"- الجامع الصحيح: - أبو عيسى محمد بن سورة الترمذى (ت: ٢٧٩)، مع شرح تحفة الاحوذى - مطبعة المدنى، سنة ١٣٨٣ هـ."],[3935,"- جامع بيان العلم وفضله: - عمر يوسف بن عبد اللَّه بن عبد البر (ت: ٤٦٣ هـ)، ادارة الطباعة المنيرية، ١٣٩٨ هـ."],[3936,"- جامع البيان عن تأويل آى القرآن: - محمد بن جرير الطبرى (ت ٣١٠)، تحقيق محمود شاكر، دار المعارف - مصر."],[3937,"- جامع البيان عن تأويل آى القرآن: - الطبرى، مطبعة مصطفى البابى الحلبى - مصر، ط ٣، ١٣٨٨ - ١٩٦٨."],[3938,"- جامع التحصيل في أحكام المراسيل: - صلاح الدين خليل بن كيكلدى العلائى (ت ٧٦١)، تحقيق حمدى عبد المجيد السلفى، الدار العربية - بغداد، ط ١ - ١٣٩٨ - ١٩٧٨."],[3939,"- الجامع الصغير: - جلال الدين عبد الرحمن بن أبى بكر السيوطى (ت ٩١١)، دار الكتب العلمية - ط ٤."],[3940,"- الجامع الكبير: جلال الدين عبد الرحمن بن أبى بكر السيوطى (ت ٩١١)، مصورة عن مخطوطة دار الكتب المصرية - الهيئة المصرية العامة للكتاب."],[3941,"- جذوة المقتبس في ذكر ولاة الاندلس الحميدى: أبو عبد اللَّه محمد بن أبى نصر فتوح بن عبد اللَّه الازدى (ت: ٤٨٨)، الدار المصرية للتأليف والترجمة، ١٩٦٦."],[3942,"- الجرح والتعديل: - عبد الرحمن بن أبى حاتم محمد بن ادريس الرازى (ت ٣٢٧) دائرة المعارف العثمانية - الهند، ١٣٧١ هـ."],[3943,"- جمهرة أنساب العرب: - أبو محمد على بن أحمد بن سعيد بن حزم الاندلسى (ت: ٤٥٦)، تحقيق/ عبد السلام هارون، دار المعارف - مصر، ١٣٨٢ هـ."],[3944,"- جمهرة نسب قريش وأخبارها: - الزبير بن بكار (ت: ٢٥٦)، شرح وتحقيق محمود محمد شاكر طبع مكتبة دار العروبة، سنة ١٣٨١ هـ."],[3945,"- الجوهر النقى على سنن البيهقى: علاء الدين بن على بن عثمان بن التركمانى (ت ٧٤٥)، دار الفكر - بيروت."],[3946,"- حلية الأولياء: أبو نعيم أحمد بن عبد اللَّه الاصبهانى (ت ٤٣٠)، دار الكتاب العربى - بيروت، ط ٢ - ١٣٨٧ - ١٩٦٧."],[3947,"- الخراج: - يحيى بن آدم القرشى (ت ٢٠٣)، دار المعرفة - بيروت."],[3948,"- الخراج: يعقوب بن إبراهيم أبو يوسف (ت ١٨٣)، دار المعرفة - بيروت، ١٣٩٩ - ١٩٧٩."],[3949,"- خزانة الأدب ولب لباب لسان العرب: - الشيخ عبد القادر عمر البغدادى (ت: ١٠٩٣)، دار الثقافة - بيروت."],[3950,"- خلق أفعال العباد: - محمد بن إسماعيل البخارى (ت ٢٥٦)، تحقيق د. عبد الرحمن عميرة، دار عكاظ - جده، ط ٢."],[3951,"- خلاصة تهذيب الكمال في أسماء الرجال: أحمد بن عبد اللَّه الخزرجى (ت: ٩٢٣)، مكتبة المطبوعات الاسلامية - بيروت، ١٩٧١ م."],[3952,"- الدراية في تخريج أحاديث الهداية لابن حجر العسقلانى، مطبعة الفجالة الجديدة - القاهرة، ١٣٨٤ هـ."],[3953,"- الدر المنثور في التفسير بالمأثور: جلال الدين السيوطى، دار المعرفة - بيروت."],[3954,"- دلائل النبوة: - أحمد بن السحين البيهقى (ت: ٤٥٨) المكتبة السلفية/ - المدينة المنورة ط ١، ١٣٨٩ هـ."],[3955,"- دلائل النبوة: - أبو نعيم أحمد بن عبد اللَّه الاصبهانى (ت ٤٣٠)، توزيع دار الباز - مكة المكرمة."],[3956,"- الديباج المذهب في معرفة أعيان علماء المذهب: - ابن فرحون المالكى، تحقيق د/ محمد الاحمدى، دار التراث - القاهرة."],[3957,"- ديوان الضعفاء والمتروكين: - شمس الدين بن عثمان الذهبى (ت: ٧٤٨)، تحقيق حماد الأنصارى، مطبعة النهضة - مكة المكرمة، ١٣٨٧ هـ."],[3958,"- ذكر أخبار أصبهان: أبو نعيم أحمد بن عبد اللَّه الاصبهانى (ت: ٣٤٠)، مطبعة بريل في مدينة ليدن، ١٩٣٤ م."],[3959,"- الذهبى ومنهجه في كتابه تاريخ الاسلام: - الدكتور/ بشّار عواد معروف، مطبعة عيسى البابى الحلبى وشركاه، القاهرة، ط ١، سنة ١٩٧٦ م."],[3960,"- رجال السند والهند: - القاضى أبو المعالى أطهر المباركبورى، دار الأنصار ط ١ - ١٣٩٨ هـ."],[3961,"- الرسالة: - محمد بن ادريس الشافعى (ت: ٢٠٤)، تحقيق: أحمد شاكر ١٣٥٨ هـ."],[3962,"- الرسالة المستطرفة: محمد بن جعفر الكتانى (ت ١٣٤٥ هـ)، دار الفكر - دمشق، ط ٣، ١٣٨٣ - ١٩٦٤ م."],[3963,"- الرواة الذين كنوا بأبى زرعة: - الدكتور سعدى الهاشمى، بحث في مجلة الجامعة الاسلامية بالمدينة المنورة، سنة ١٥ - عدد ٥٨."],[3964,"- الروض الانف في شرح السيرة النبوية لابن هشام: - عبد الرحمن السهيلى (٥٠٨ - ٥٨١)، تحقيق وتعليق/ عبد الرحمن الوكيل، دار الكتب الحديثة/ القاهرة."],[3965,"- الزهد: أحمد بن محمد بن حنبل (ت ٢٤١)، دار الكتب العلمية - بيروت، ١٣٩٨ - ١٩٧٨ م."],[3966,"- الزهد: عبد اللَّه بن المبارك (ت ١٨١)، تحقيق عبد الرحمن الاعظمى، دار الكتب العلمية - بيروت."],[3967,"- سبل السلام شرح بلوغ المرام: محمد بن إسماعيل الصنعانى (ت ١١٨٢)، مطبعة مصطفى البابى الحلبى - مصر، ط ٤، سنة ١٣٧٩ هـ - ١٩٦٠ م."],[3968,"- سلسلة الأحاديث الصحيحة: محمد ناصر الدين الألبانى، المكتب الاسلامى ط ٢، ١٣٩٩ هـ - ١٩٧٩ م."],[3969,"- سلسلة الأحاديث الضعيفة: محمد ناصر الدين الألبانى - المكتب الاسلامى ط ٤، ١٣٩٨ هـ."],[3970,"- السنن: سعيد بن منصور (ت ٢٢٧)، تحقيق حبيب الرحمن الاعظمى، مطبعة علمى بريس، ١٣٨٧ هـ - ١٩٦٧ م."],[3971,"- سنن أبى داود: - أبو داود سليمان بن الأشعث السجستانى (ت: ٢٧٥)، دار إحياء السنة النبوية."],[3972,"- سنن الدارقطنى: - أبو الحسن على بن عمر الدارقطنى (ت ٣٨٥)، شركة الطباعة الفنية، ١٣٨٦ هـ."],[3973,"- سنن الدارمى: عبد اللَّه بن عبد الرحمن الدارمى (ت ٢٥٥)، دار إحياء السنة النبوية."],[3974,"- السنن الكبرى: - أحمد بن الحسين البيهقى (ت ٤٥٨)، دار الفكر بيروت."],[3975,"- سنن ابن ماجه: محمد بن يزيد بن ماجه (ت ٢٧٥)، دار إحياء التراث العربى بيروت - ١٣٩٥ - ١٩٧٥."],[3976,"- سنن النسائى: - أحمد بن شعيب النسائى (ت ٣٠٣)، دار إحياء التراث العربى - بيروت."],[3977,"- السنة: عمرو بر أبى عاصم الضحاك بن مخلد (ت ٢٨٧)، المكتب الاسلامى، ط ١ - ١٤٠٠ - ١٩٨٠."],[3978,"- سير أعلام النبلاء: - محمد بن أحمد بن عثمان الذهبى (ت ٧٤٨)، مصور بالمكتبة المركزية بجامعة أم القرى."],[3979,"- سير أعلام النبلاء: - الإمام شمس الدين محمد بن أحمد بن عثمان الذهبى (ت: ٧٤٨)، تحقيق: شعيب الارناؤوط وحسين الاسد، مؤسسة الرسالة، ط ٢ - ١٤٠٢ هـ."],[3980,"- سيرة عمر بن عبد العزيز: - الحافظ أبو الفرج عبد الرحمن بن الجوزى."],[3981,"- السيرة النبوية: - أبو الفداء إسماعيل بن كثير (ت: ٧٧٤)، تحقيق مصطفى عبد الواحد، دار المعرفة - بيروت ١٣٩٦ هـ."],[3982,"- السيرة النبوية: أبو محمد بن عبد الملك بن هشام بن أيوب الحميرى (ت: ٢١٨) تحقيق: مصطفى السّقّا وآخرين، مطبعة مصطفى البابى الحلبى وأولاده ط ٢ - ١٣٧٥ هـ."],[3983,"- السيرة النبوية: محمد بن أحمد بن عثمان الذهبى (ت ٧٤٨)، تحقيق حسام الدين القدسى، دار الكتب العلمية - بيروت، ط ١ - ١٤٠١ - ١٩٨١."],[3984,"- السيرة والمغازى: - محمد بن اسحاق المطلبى (ت: ١٥١) تحقيق سهيل زكار - دار الفكر، ط ١، ١٣٩٨ هـ."],[3985,"- شجرة النور الزكية في طبقات المالكية: - محمد بن محمد مخلوف، دار الكتاب العربى - بيروت."],[3986,"- شذرات الذهب في أخبار من ذهب: عبد الحى بن العماد الحنبلى (ت ١٠٨٩) المكتب التجارى - بيروت."],[3987,"- شذور الذهب في معرفة كلام العرب: - أبو محمد عبد اللَّه جمال الدين ابن يوسف بن أحمد بن عبد اللَّه بن هشام الأنصارى المصرى (٧٠٨ - ٧٦١)، مطبعة السعادة - مصر: ط ٥ - ١٣٧١ هـ."],[3988,"- شرح أشعار الهذليين: تحقيق عبد الستار أحمد فراج ومحمود شاكر، ط ١، القاهرة، ١٣٨٤ هـ."],[3989,"- شرح اصول اعتقاد أهل السنة: هبة اللَّه بن الحسن اللالكائى - تحقيق د. أحمد بن سعد، رسالة دكتوراة، بجامعة أم القرى بمكة المكرمة."],[3990,"- شرح السنة: الحسين بن مسعود البغوى (ت ٥١٦)، تحقيق شعيب الارناؤط، زهير الشاويش، المكتب الاسلامى - بيروت."],[3991,"- شرح علل الترمذى: - عبد الرحمن أحمد بن رجب الحنبلى: تحقيق نور الدين العتر، دار الملاح - دمشق، ط ١، ١٣٩٨ هـ."],[3992,"- شرح الفية العراقى (التبصرة والتذكرة): - الحافظ زين الدين عبد الرحيم بن الحسين بن عبد الرحمن بن أبى بكر بن إبراهيم العراقى (ت: ٨٠٦) المطبعة الجديدة - فاس، ١٣٥٤ هـ."],[3993,"- شرح ابن عقيل على الفية ابن مالك: - بهاء الدين عبد اللَّه بن عقيل العقيلى الهمدانى المصرى (٦٩٨ - ٧٦٩)، المكتبة التجارية الكبرى - القاهرة، ط ١٤ - ١٣٨٥ هـ."],[3994,"- شرح كتاب السير الكبير: - محمد بن الحسن الشيبانى (ت: ١٨٩)، تحقيق: د/ صلاح الدين المنجد، مطبعة شركة الاعلانات الشرقية، ١٩٧١ م."],[3995,"- شرح معانى الآثار: - أبو جعفر أحمد بن محمد الطحاوى (ت: ٣٢١) تحقيق: محمد سيد جاد الحق - مطبعة الأنوار المحمدية."],[3996,"- شرح النووى على مسلم: - محيى الدين يحيى بن شرف النووى (ت ٦٧٦)، المطبعة المصرية ومكتبتها."],[3997,"- الشعر والشعراء أو طبقات الشعراء: - أبو محمد عبد اللَّه بن مسلم بن قتيبة الدينورى (ت: ٢٧٦)، تحقيق الدكتور/ مفيد قميحة، دار الكتب العلمية/ بيروت، ط ١ سنة ١٩٨١ م."],[3998,"- الشمائل: محمد بن عيسى الترمذى (ت ٢٧٩)، مطبعة مصطفى البابى الحلبى، ط ٣، ١٣٧٥ هـ."],[3999,"- شمائل الرسول: أبو الفداء إسماعيل بن كثير (ت: ٧٧٤)، تحقيق مصطفى عبد الواحد، دار المعرفة - بيروت."],[4000,"- الصحاح للجوهرى: - إسماعيل بن حماد الجوهرى، تحقيق: أحمد عبد الغفور عطّار، ط ٢ - ١٤٠٢ هـ."],[4001,"- صحيح البخارى: - محمد بن إسماعيل البخارى (ت ٢٥٦) مع شرح فتح البارى المطبعة السلفية - القاهرة، ١٣٨٠ هـ."],[4002,"- صحيح ابن خزيمة: - أبو بكر محمد بن اسحاق بن خزيمة (ت: ٣١١)، تحقيق د/ محمد مصطفى الاعظمى - المكتب الاسلامى."],[4003,"- صحيح مسلم: مسلم بن الحجاج النيسابورى (ت ٢٦١)، ترتيب محمد فؤاد عبد الباقى."],[4004,"- الصفات: على بن عمر الدارقطنى (ت ٣٨٥)، تحقيق: عبد اللَّه الغنيمان، مكتبة الدار: المدينة المنورة، ط ١، ١٤٠٢ هـ."],[4005,"- صفة الجنة: أبو نعيم أحمد بن عبد اللَّه الاصبهانى (ت ٤٣٠)، مصور بالمكتبة المركزية بجامعة أم القرى بمكة المكرمة."],[4006,"- الصلة: - ابن بشكوال أبو القاسم خلف بن عبد الملك (ت: ٥٧٨)، الدار المصرية للتأليف والترجمة، ١٩٦٦ م."],[4007,"- الضعفاء: محمد بن عمر بن موسى العقيلى (ت: ٣٢٢)، رسالة جامعية بمكتبة الدكتور أحمد محمد نور سيف، إعداد الدكتور عبد اللَّه على حافظ."],[4008,"- الضعفاء أو أسامى الضعفاء ومن تكلم فيهم من المحدثين: - أبو زرعة الرازى. تحقيق الدكتور سعدى الهاشمى، مطبوعات الجامعة الاسلامية بالمدينة المنورة، ط ١ - ١٤٠٢ هـ."],[4009,"- الضعفاء الصغير: - محمد بن إسماعيل البخارى (ت: ٢٥٦)، تحقيق: محمود إبراهيم زايد - دار الوعى - حلب، ط ١، ١٣٩٦ هـ."],[4010,"- الضعفاء والمتروكون: أحمد بن شعيب النسائى (ت ٣٠٣)، مطبوع بذيل الضعفاء الصغير للبخارى - السابق الذكر."],[4011,"- طبقات الحفاظ: - جلال الدين عبد الرحمن بن أبى بكر السيوطى (ت ٩١١)، مطبعة الاستقلال الكبرى، ط ١ - ١٣٩٣ - ١٩٧٣."],[4012,"- طبقات خليفة بن خياط: - خليفة بن خياط شباب العصفرى (ت: ٢٤٠)، تحقيق أكرم العمرى، دار طيبة - الرياض."],[4013,"- طبقات الشافعية الكبرى: - عبد الوهاب بن تقى الدين السبكى (ت:"],[4014,"٧٧١)، دار المعرفة - بيروت، ط ٢."],[4015,"- طبقات الشعراء، محمد بن سلام الجمحى (ت: ٣٣١)، دار النهضة العربية - بيروت."],[4016,"- طبقات الفقهاء: - أبو اسحاق الشيرازى الشافعى (ت: ٤٧٦)، تحقيق د/ احسان عباس، دار الرائد العربى - بيروت، ١٤٠١ هـ."],[4017,"- الطبقات الكبرى: - محمد بن سعد (ت: ٢٣٠)، دار صادر - بيروت."],[4018,"- طبقات المدلسين: - ابن حجر - المطبعة المحمودية، مصر."],[4019,"- طبقات المفسرين: - محمد بن على الداودى (ت ٩٤٥)، تحقيق: - محمد على عمر، مطبعة الاستقلال الكبرى، ط ١ - ١٣٩٢ هـ."],[4020,"- ظلال الجنة في تخريج السنة: محمد ناصر الدين الألبانى، المكتب الاسلامى، ط ١، ١٤٠٠ - ١٩٨٠."],[4021,"- العبر في خبر من غبر: - أبو عبد اللَّه شمس الدين محمد الذهبى (ت: ٧٤٨) تحقيق: فؤاد سيد، الكويت، ١٩٦١."],[4022,"- العقد الثمين في تاريخ البلد الامين: - محمد بن أحمد الحسينى الفاسى (ت ٨٣٢)، تحقيق فؤاد سيد، مطبعة السنة المحمدية، ١٣٨٥ هـ."],[4023,"- العلل: - على بن عبد اللَّه بن المدينى (ت ٢٣٤)، المكتب الاسلامى - بيروت، ١٣٩٢ هـ."],[4024,"- العلل: أبو الحسن على بن عمر الدارقطنى (ت ٣٨٥)، مصورة بمكتبة الدكتور أحمد محمد نور سيف."],[4025,"- علل الترمذى الكبير: - ترتيب أبى طالب القاضى، تحقيق الاستاذ حمزة ذيب مصطفى، رسالة ماجستير في جامعة أم القرى بمكة المكرمة."],[4026,"- علل الحديث: - عبد الرحمن بن أبى حاتم الرازى (ت: ٣٢٧)، المطبعة السلفية - القاهرة، ١٣٤٣ هـ."],[4027,"- العلل المتناهية في الأحاديث الواهية: أبو الفرج عبد الرحمن بن على بن الجوزى (ت: ٥٩٧)، تحقيق ارشاد الحق الاثرى، إدارة ترجمان السنة - لاهور."],[4028,"- العلل ومعرفة الرجال: - أحمد بن محمد بن حنبل (ت: ٢٤١)، نشر: الدكتور طلعت فوج بيكيت والدكتور إسماعيل جراح أو على، انقره، ١٩٦٣."],[4029,"- عمل اليوم والليلة: أبو بكر بن السنى (ت ٣٦٤)، تحقيق عبد القادر عطا، مكتبة الكليات الازهرية، ط ١، ١٣٨٩ هـ."],[4030,"- عمل اليوم والليلة: - أحمد بن شعيب النسائى (ت: ٣٠٣)، تحقيق/ الدكتور فاروق حمادة، مكتبة المعارف - الرباط، ط ١ سنة ١٤٠١ هـ."],[4031,"- غاية النهاية في طبقات القراء: - محمد بن محمد بن الجزرى (ت: ٨٣٣)، دار الكتب العلمية - بيروت، ١٤٠٠ هـ."],[4032,"- غريب الحديث: حمد بن محمد بن إبراهيم الخطابى (ت ٣٨٨)، تحقيق عبد الكريم العزباوى، مطبوعات: مركز البحث العلمى - جامعة أم القرى."],[4033,"- غريب الحديث: - أبو عبيد القاسم بن سلّام الهروى (ت: ٢٢٤ هـ)، دائرة المعارف العثمانية - الهند، ط ١ - ١٣٨٤ هـ."],[4034,"- الفائق في غريب الحديث: - جار اللَّه محمود الزمخشرى (ت: ٥٣٨)، تحقيق: محمد أبى الفضل إبراهيم، مطبعة عيسى البابى الحلبى، ط ٢."],[4035,"- فتح البارى شرح صحيح البخارى: - أحمد بن على بن حجر (ت: ٨٥٢)، المكتبة السلفية - القاهرة ١٣٨٠ هـ."],[4036,"- الفتح الكبير في ضم الزيادة إلى الجامع الصغير: - جلال الدين السيوطى (ت: ٩١١)، وضع الشيخ يوسف النبهانى، دار الكتاب العربى - بيروت."],[4037,"- فتح المغيث شرح الفية الحديث للعراقى للامام شمس الدين محمد بن عبد الرحمن السخاوى (ت: ٩٠٢)، المكتبة العلمية - بيروت، ط ١ سنة ١٤٠٣ هـ."],[4038,"- فتوح البلدان: - أبو الحسن البلاذرى (ت: ٢٧٩)، مراجعة رضوان محمد رضوان، دار الكتب العلمية - بيروت."],[4039,"- فتوح الشام: - محمد بن عمر الواقدى (ت: ٢٠٧)، دار الجيل - بيروت."],[4040,"- فتوح مصر وأخبارها: - أبو القاسم عبد الرحمن بن عبد اللَّه بن عبد الحكم، مكتبة المثنى ببغداد."],[4041,"- الفرق بين الفرق: - عبد القاهر البغدادى الاسفرائينى (ت: ٤٢٩)، تحقيق: محمد محيى الدين عبد الحميد، مطبعة المدنى - القاهرة."],[4042,"- فضائل الصحابة: أحمد بن محمد حنبل (ت ٢٤١)، تحقيق: وصى اللَّه ابن محمد عباس، رسالة دكتوراة بجامعة أم القرى بمكة."],[4043,"- الفقيه والمتفقه: - أبو بكر أحمد بن على الخطيب، دار الكتب العلمية - بيروت ط ٢ - ١٤٠٠ هـ."],[4044,"- فهرس الفهارس والاثبات ومعجم المعاجم والمشيخات والمسلسلات: - الحافظ عبد الحى بن شمس الافاق أبو المكارم عبد الكبير بن القطب الشهير الشيخ محمد الحسنى الادريسى الكتانى الفاسى، المطبعة الجديدة بالطالعة، سنة ١٣٤٦ هـ."],[4045,"- الفهرست: - محمد بن اسحاق بن النديم (ت: ٢٧٨)، نشر: دار المعرفة - بيروت."],[4046,"- فهرسة ابن خير الاشبيلى: - محمد بن خير بن عمر الاشبيلى (ت: ٥٧٥)، دار الافاق الجديدة - بيروت، ط ٢ - ١٣٩٩ هـ."],[4047,"- فوائد تمام: - تمام بن عبد اللَّه الرازى (ت ٤١٤)، تحقيق الدكتور عبد الغنى أحمد جبر، رسالة دكتوراة بجامعة أم القرى بمكة المكرمة."],[4048,"- الفوائد (الغيلانيات): - أبو بكر محمد بن عبد اللَّه الشافعى (ت: ٣٥٤)، تحقيق الدكتور حلمى كامل اسعد عبد الهادى، رسالة دكتوراه بجامعة أم القرى بمكة."],[4049,"- فيض القدير شرح الجامع الصغير: محمد عبد الرؤوف المناوى، دار المعرفة - بيروت، ط ٢ - ١٣٩١ هـ."],[4050,"- القاموس المحيط: مجد الدين محمد بن يعقوب الفيروزآبادى (ت:"],[4051,"٨١٧)، المطبعة الحسينية المصرية - ط ٢ - سنة ١٣٤٤ هـ."],[4052,"- الكامل في أسماء الرجال: الحافظ أبو أحمد بن عدى الجرجانى (ت ٣٦٥)، مصورة بالمكتبة المركزية بجامعة أم القرى."],[4053,"- الكامل في التاريخ: - عز الدين على بن محمد بن الاثير (ت ٦٣٠)، دار صادر بيروت، ١٣٨٦ هـ."],[4054,"- كشف الاستار عن زوائد البزار: - نور الدين على بن أبى بكر الهيثمى (ت ٨٠٧)، تحقيق حبيب الرحمن الاعظمى، مؤسسة الرسالة - بيروت، ط ١، ١٣٩٩ هـ."],[4055,"- كشف الخفا ومزيل الالباس: - إسماعيل بن محمد العجلونى (ت ١١٦٢)، دار إحياء التراث العربى - بيروت. ط ٣ - ١٣٥١ هـ."],[4056,"- كشف الظنون عن أسامى الكتب والفنون: - مصطفى بن عبد اللَّه الشهير بحاجى خليفة (ت: ١٠٦٧)، منشورات مكتبة المثنى - بغداد."],[4057,"- الكفاية في علم الرواية للخطيب البغدادى (ت: ٤٦٣) ط ١."],[4058,"- كنز العمال في سنن الأقوال والأفعال: - علاء الدين على المتقى الهندى - مكتبة التراث - حلب، ط ١ - ١٣٩٠ هـ."],[4059,"- الكنى: أبو أحمد الحاكم محمد بن محمد (ت: ٣٧٨)، مصورة مركز البحث العلمى بجامعة أم القرى."],[4060,"- كنى البخارى: - محمد بن إسماعيل البخارى (ت: ٢٥٦)، المكتبة الاسلامية - تركيا."],[4061,"- الكنى والأسماء: - أبو بشر محمد بن أحمد الدولابى (ت ٣١٠)، دائرة المعارف العثمانية - الهند، ط ١."],[4062,"- الكنى والأسماء: - مسلم بن الحجاج النيسابورى (ت: ٢٦١)، تحقيق الاستاذ عبد الرحيم محمد أحمد القشقرى، رسالة ماجستير في الجامعة الاسلامية بالمدينة المنورة."],[4063,"- الكواكب النيرات في معرفة من اختلط من الرواة الثقات: - محمد بن أحمد بن الكيّال (ت: ٩٣٩)، تحقيق: عبد القيوم عبد رب النبى، دار المأمون للتراث."],[4064,"- اللآلئ المصنوعة في الأحاديث الموضوعة: - جلال الدين عبد الرحمن ابن أبى بكر السيوطى (ت: ٩١١)، دار المعرفة - بيروت، ط ٢، ١٣٩٥ هـ."],[4065,"- اللباب شرح الشهاب: أبو الوفا مصطفى المراغى، المجلس الأعلى للشئون الإسلامية - القاهرة، ١٣٩٠ هـ."],[4066,"- اللباب في تهذيب الانساب: - عز الدين على بن محمد المعروف بابن الاثير (ت: ٦٣٠)، دار صادر - بيروت."],[4067,"- لسان العرب: جمال الدين محمد بن مكرم بن منظور المصرى، دار صادر - بيروت."],[4068,"- لسان الميزان: - أحمد بن على بن حجر العسقلانى (ت: ٨٥٢)، دائرة المعارف العثمانية - الهند، ط ٢، ١٩٧١ - ١٣٩٠."],[4069,"- المجروحون من المحدثين: - أبو حاتم محمد بن حبان البستى (ت: ٣٥٤)، تحقيق: محمود إبراهيم - دار الوعى - حلب."],[4070,"- مجمع الزوائد ومنبع الفوائد: نور الدين على بن أبى بكر الهيثمى (ت: ٨٠٧) دار الكتاب العربى - بيروت، ط ٢ - ١٣٨٧ هـ."],[4071,"- محاسن الاصطلاح: - للحافظ سراج الدين عمر البلقينى (ت: ٨٠٥)، تحقيق: د/ عائشة عبد الرحمن، مطبعة دار الكتب - ١٩٧٤ م."],[4072,"- المحبّر: - أبو جعفر محمد بن حبيب البغدادى (ت: ٢٤٥)، دار الافاق الجديدة - بيروت."],[4073,"- المحلى: على بن أحمد بن حزم (ت ٤٥٦)، دار الاتحاد العربى - القاهرة، ١٣٨٧ هـ."],[4074,"- مرآة الجنان وعبرة اليقظان في معرفة ما يعتبر من حوادث الزمان: عبد اللَّه ابن اسعد اليافعى اليمنى المكى (ت: ٧٦٨)، مؤسسة الاعلمى - بيروت. ط ٢/ سنة ١٣٩٠ هـ."],[4075,"- المراسيل: أبو داود سليمان بن أشعث السجستانى (ت: ٢٧٥)، مكتبة ومطبعة محمد على صبيح وأولاده - مصر."],[4076,"- المراسيل: عبد الرحمن بن أبى حاتم بن ادريس الرازى (ت ٣٢٧)، مؤسسة الرسالة - بيروت، ط ١."],[4077,"- مراصد الاطلاع على أسماء الامكنة والبقاع عبد المؤمن بن عبد الحق البغدادى (ت: ٧٣٩)، تحقيق على محمد البجاوى، دار إحياء الكتب العربية. ط ١، ١٣٧٣ هـ."],[4078,"- مسائل الإمام أحمد بن حنبل: - رواية اسحاق بن إبراهيم النيسابورى (ت: ٢٧٥) تحقيق: زهير الشاويش، المكتب الاسلامى، ١٤٠٠ هـ."],[4079,"- المستدرك على الصحيحين: أبو عبد اللَّه محمد بن عبد اللَّه المعروف بالحاكم (ت ٤٠٥)، دار الفكر - بيروت، ١٣٩٨ هـ."],[4080,"- المسند: عبد اللَّه بن الزبير الحميدى (ت ٢١٩)، عالم الكتب - بيروت، مكتبة المتنبى - القاهرة."],[4081,"- المسند: أحمد بن محمد بن حنبل (ت ٢٤١)، المكتب الاسلامى، دار صادر - بيروت."],[4082,"- المسند: - محمد بن ادريس الشافعى (ت ٢٠٤)، دار الكتب العلمية - بيروت، ط ١، ١٤٠٠ هـ."],[4083,"- مسند أبى عوانة: يعقوب بن اسحق الاسفرائينى (ت ٣١٦)، دار المعرفة بيروت."],[4084,"- المسند: - سليمان بن داود أبو داود الطيالسى (ت: ٢٥٣)، ترتيب أحمد عبد الرحمن البنا، المكتبة الاسلامية - بيروت، ط ٢ - ١٤٠٠ هـ."],[4085,"- مشاهير علماء الأمصار: - محمد بن حبان البستى (ت: ٣٥٤)، تصحيح: م. فلا يشهمر، دار الكتب العلمية."],[4086,"- مشكل الآثار: - أبو جعفر الطحاوى، دار صادر - بيروت."],[4087,"-المصنف: - عبد الرزاق بن همام الصنعانى (ت ٢١١)، تحقيق حبيب الرحمن الاعظمى، المجلس العلمى - ١٣٩٠ هـ."],[4088,"- المصنف: أبو بكر عبد اللَّه بن محمد بن أبى شيبة (ت ٢٣٥)، الدار السلفية - الهند."],[4089,"- المطالب العالية: - أحمد بن على بن حجر العسقلانى (ت ٨٥٢)، تحقيق حبيب الرحمن الاعظمى."],[4090,"- المعارف: - عبد اللَّه بن مسلم بن قتيبة (ت: ٢٧٦)، تحقيق د/ ثروت عكاشة دار المعارف - مصر. ط ٢"],[4091,"- معالم السنن: - حمد بن محمد بن إبراهيم الخطابى (ت ٣٨٨)، مكتبة السنة المحمدية - القاهرة."],[4092,"- معجم البلدان: شهاب الدين أبو عبد اللَّه ياقوت الحموى (ت ٦٢٦)، دار الكتاب العربى - بيروت."],[4093,"- معجم الشعراء: - الإمام أبو عبيد اللَّه محمد بن عمران المرزبانى (ت: ٣٨٤)، نشر/ مكتبة القدسى. ط ٢."],[4094,"- معجم الصحابة: عبد اللَّه بن محمد البغوى (ت: ٣١٧)، مصورة الخزانة العامة بالرباط رقم (٣٤١) منه نسخة ميكروفيلم لدى مركز البحث العلمى بجامعة أم القرى."],[4095,"- المعجم الصغير: - سليمان بن أحمد الطبرانى، دار النصر - القاهرة ١٣٨٨ هـ."],[4096,"- المعجم الكبير: سليمان بن أحمد الطبرانى (ت ٣٦٠)، تحقيق حمدى عبد المجيد السلفى، مطبعة الأمة - بغداد، ١٩٧٨ م."],[4097,"- معجم المؤلفين تراجم مصنفى الكتب العربية: - عمر رضا كحالة، مكتبة المثنى - لبنان."],[4098,"- المعرفة والتاريخ: - يعقوب بن سفيان الفسوى (ت: ٢٧٧)، تحقيق د/ أكرم العمرى، مؤسسة الرسالة، ط ٢."],[4099,"- معرفة علوم الحديث: - محمد بن عبد اللَّه الحاكم، المكتب التجارى - بيروت."],[4100,"- المغازى: - محمد بن عمر بن واقد الواقدى (ت ٢٠٧)، تحقيق د. مارسدن جونس، مؤسسة الاعلمى - بيروت."],[4101,"- المغازى النبوية: - محمد بن مسلم بن شهاب الزهرى (ت: ١٢٤)، تحقيق د/ سهيل زكار، دار الفكر، ط ١، ١٤٠٠ هـ."],[4102,"- المغرب في حلى المغرب: - تأليف: مجموعة من علماء الاندلس."],[4103,"- المغنى: - محمد بن طاهر بن على الهندى (ت: ٩٨٦) دائرة نشر الكتب الاسلامية، ط ١، ١٣٩٣ هـ."],[4104,"- المقاصد الحسنة: - محمد بن عبد الرحمن السخاوى (ت ٩٠٢)، تحقيق عبد اللَّه محمد صديق، دار الكتب العلمية - بيروت."],[4105,"- مقالات الاسلاميين واختلاف المصلين: - أبو الحسن على بن إسماعيل الاشعرى (ت: ٣٣٠)، تحقيق: محيى الدين عبد الحميد، طبع ونشر مكتبة النهضة المصرية - القاهرة."],[4106,"- المقتنى في سرد الكنى: - محمد بن أحمد بن عثمان الذهبى (ت: ٧٤٨)، مصورة مركز البحث العلمى بجامعة أم القرى (ميكروفيلم)."],[4107,"- مقدمة ابن الصلاح في علوم الحديث مع شرحها التقييد والايضاح: أبو عمرو عثمان بن عبد الرحمن بن عثمان المعروف بابن الصلاح (ت ٦٤٣)، المكتبة السلفية - المدينة المنورة، ط ١، ١٣٨٩ هـ."],[4108,"- الملل والنحل: - محمد بن عبد الكريم الشهرستانى (ت: ٥٤٨)، مكتبة ومطبعة محمد على صبيح وأولاده - القاهرة."],[4109,"- المنتقى: عبد اللَّه بن على بن الجارود (ت ٣٠٧)، المكتبة الاثرية - باكستان."],[4110,"- موار الظمآن إلى زوائد ابن حبان: نور الدين الهيثمى (ت ٧٠٨)، دار الكتب العلمية - بيروت."],[4111,"- الموضوعات: - أبو الفرج عبد الرحمن بن على بن الجوزى (ت ٥٩٧)، المكتبة السلفية، ط ١ - ١٣٨٦ هـ."],[4112,"- الموطأ: مالك بن أنس (ت ١٧٩)، دار إحياء الكتب العربية - القاهرة."],[4113,"- ميزان الاعتدال: محمد بن أحمد بن عثمان الذهبى (ت ٧٤٨)، دار المعرفة بيروت، ط ١، ١٣٨٢ هـ."],[4114,"- النجوم الزاهرة في ملوك مصر والقاهرة: - ابن تغرى بردى الاتابكى (ت: ٨٧٤) المؤسسة المصرية العامة للتأليف والترجمة والطباعة والنشر."],[4115,"- نزهة الالبّاء في طبقات الأدباء: - أبو البركات كمال الدين عبد الرحمن ابن محمد الانبارى (ت: ٥٧٧)، تحقيق محمد أبو الفضل إبراهيم، دار نهضة مصر للطباع والنشر- الفجالة - القاهرة."],[4116,"- نسب قريش: - أبو عبد اللَّه المصعب بن عبد اللَّه المصعب الزبيرى (ت: ٢٣٦)، نشر/ ١. ليفى بروفنسال، دار المعارف للطباعة والنشر."],[4117,"- نصب الراية: - عبد اللَّه بن يوسف الزيلعى (ت ٧٦٢)، إدارة المجلس العلمى - الهند."],[4118,"- نظم المتناثر في الحديث المتواتر: - محمد بن جعفر الكتانى، دار المعارف، حلب."],[4119,"- النكت الظراف على الاطراف: - أحمد بن على بن حجر (ت ٨٥٢)، الدار القيمة - الهند."],[4120,"- النهاية في غريب الحديث: مجد الدين المبارك بن محمد بن الاثير (ت ٦٠٦)، المكتبة الاسلامية - بيروت."],[4121,"- نوادر الأصول في معرفة أحاديث الرسول: - أبو عبد اللَّه محمد الحكيم الترمذى المكتبة العلمية بالمدينة المنورة لصاحبها محمد النمنكانى."],[4122,"- نيل الأوطار: - محمد بن على الشوكانى (ت ١٢٥٥)، دار الجيل - لبنان، ١٣٩٣ هـ."],[4123,"- هدى السارى مقدمة فتح البارى: - ابن حجر العسقلانى، المطبعة السلفية."],[4124,"- الوتر: محمد بن نصر المروزى (ت ٢٩٢)، المكتبة الاثرية - باكستان."],[4125,"- وفيات الأعيان وأنباء أبناء الزمان: - أحمد بن محمد بن خلكان (ت: ٦٨١)، تحقيق د. احسان عباس، دار الثقافة - بيروت."]])